    mouse: () => { const s = mk('ms'); s.shadow(64, 116, 32); s.shape('M64 14 C90 14 96 40 96 64 C96 94 84 108 64 108 C44 108 32 94 32 64 C32 40 38 14 64 14 Z', 'white', { depth: 6, glossD: 'M60 20 C44 22 38 40 38 58 C46 46 54 40 60 38 Z' }); s.raw('<path d="M64 16V50" stroke="#C3CCDA" stroke-width="2.5"/><rect x="60" y="28" width="8" height="16" rx="4" fill="#3B7DEB"/>'); return s; },
    usb: () => { const s = mk('ub'); s.shadow(64, 118, 28); s.slab(48, 10, 32, 26, 4, 'silver', { d: 0 }); s.raw('<rect x="55" y="17" width="6" height="6" fill="#566175"/><rect x="67" y="17" width="6" height="6" fill="#566175"/>'); s.slab(40, 34, 48, 78, 12, 'blue', { d: 6 }); s.raw('<circle cx="64" cy="92" r="5" fill="#fff" opacity=".8"/>'); return s; },
    harddisk: () => { const s = mk('hd'); s.shadow(64, 116, 50); s.slab(16, 18, 96, 88, 12, 'silver', { d: 8 }); s.circle(58, 58, 28, 'white', { depth: 0 }); s.raw('<circle cx="58" cy="58" r="6" fill="#A8B2C1"/><path d="M58 58 L96 92" stroke="#3B4252" stroke-width="5" stroke-linecap="round"/><circle cx="96" cy="92" r="4" fill="#E5484D"/>'); return s; },
    globe: () => { const s = mk('gl'); s.shadow(64, 118, 38); s.circle(64, 60, 46, 'sky', { depth: 6 }); s.raw('<g fill="none" stroke="#fff" stroke-opacity=".75" stroke-width="3"><ellipse cx="64" cy="60" rx="20" ry="46"/><path d="M18 60h92M26 36h76M26 84h76"/></g>'); return s; },
