    fingerprint: () => { const s = mk('fp'); s.shadow(64, 118, 42); s.slab(18, 12, 92, 98, 20, 'navy', { d: 7, gloss: 0.15 }); s.raw('<g fill="none" stroke="#19B9A6" stroke-width="4.5" stroke-linecap="round"><path d="M40 70a24 24 0 0 1 48 0v8"/><path d="M48 76v-6a16 16 0 0 1 32 0v14"/><path d="M56 88V70a8 8 0 0 1 16 0v20"/><path d="M64 70v26"/><path d="M34 52a36 36 0 0 1 60 0"/></g>'); return s; },
