UI.panel = ({ title, icon, tools = '', body, sub = '', cls = '', flush = false }) => html`<section class="panel ${cls}">${title ? html`<div class="panel-head"><h2>${icon ? UI.icon(icon) : ''}${title}</h2><div class="panel-tools">${tools}</div>${sub ? html`<p>${sub}</p>` : ''}</div>` : ''}${flush ? body : html`<div class="panel-body">${body}</div>`}</section>`;
UI.empty = ({ illu = 'box', title, text = '', action = '' }) => html`<div class="empty">${UI.illu(illu)}<h3>${title}</h3>${text ? html`<p>${text}</p>` : ''}${action}</div>`;
UI.noData = (t = 'لا توجد بيانات كافية لهذه الفترة') => html`<div class="no-data">${UI.icon('chart')}${t}</div>`;
