UI.pager = ({ offset, limit, count, hasMore }) => html`<nav class="pager" aria-label="التنقل بين الصفحات"><span class="pager-info">عرض ${fmtNum(count ? offset + 1 : 0)}–${fmtNum(offset + count)}</span><button class="btn btn-ghost btn-sm" data-page="prev"${offset <= 0 ? raw(' disabled') : ''}>${UI.icon('chevron-right')}السابق</button><span>صفحة ${Math.floor(offset / limit) + 1}</span><button class="btn btn-ghost btn-sm" data-page="next"${hasMore ? '' : raw(' disabled')}>التالي${UI.icon('chevron-left')}</button></nav>`;
UI.opts = (map) => Data.list(map).map((x) => ({ value: x.id, label: x.name }));
