  dlg.addEventListener('click', (e) => { if (e.target === dlg && downOnBackdrop) finish(null); });
  form.addEventListener('submit', (e) => { e.preventDefault(); const b = form.querySelector('button[type=submit]'); if (b && !b.disabled) b.click(); });
  actions.forEach((a, i) => form.querySelector(`[data-i="${i}"]`).addEventListener('click', async (e) => {
    e.preventDefault();
    if (!a.handler) return finish(a.value);
    const btn = e.currentTarget; UI.busy(btn, true);
    try { const r = await a.handler(form, dlg); if (r !== false) finish(r === undefined ? a.value : r); } catch (err) { UI.error(err); } finally { if (!done) UI.busy(btn, false); }
  }));
  dlg.showModal(); if (onMount) onMount(form, finish);
