/* ── شاشة المراقبة (وضع التلفاز) ────────────────────────────── */


/* ── البلاغات: القائمة ───────────────────────────────────────── */
/* علامة آخر ملاحظة على البلاغ: لمقدم البلاغ «ملاحظة من الفني» تنتظر رده، وللفنيين «ردّ الموظف». تختفي حين يرد الطرف الآخر أو يُغلق البلاغ */
Pages.notePending = (t) => {
  const me = Auth.user; if (!me || !t.noteAt || ['closed', 'cancelled'].includes(t.status)) return '';
  if (me.id === t.requesterId) return t.noteFrom === 'staff' ? 'staff' : '';
  return t.noteFrom === 'requester' && canUser(me, 'tickets.work') ? 'requester' : '';
};
/* ما رآه هذا الحساب من ملاحظات البلاغات على هذا الجهاز: الملاحظة التي لم تُفتح بعد تظهر بنقطة نابضة وسطر مظلل، وتهدأ بعد فتح البلاغ.
   وتبقى العلامة نفسها حتى يرد الطرف الآخر (لا تختفي بمجرد النظر) */
const NoteSeen = {
  key: () => `sq_nseen_${(Auth.user || {}).id || ''}`,
  map() { try { return JSON.parse(localStorage.getItem(this.key()) || '{}') || {}; } catch (_) { return {}; } },
  seen(t) { return (Number(this.map()[t.id]) || 0) >= (t.noteAt || 0); },
  mark(t) {
    if (!t || !t.noteAt || this.seen(t)) return;
    try { const m = this.map(); m[t.id] = t.noteAt; const ks = Object.keys(m); if (ks.length > 500) ks.sort((a, b) => m[a] - m[b]).slice(0, ks.length - 500).forEach((k) => { delete m[k]; }); localStorage.setItem(this.key(), JSON.stringify(m)); } catch (_) { /* تجاهل */ }
    Bus.emit('noteseen', { id: t.id });
  },
};
Pages.noteLabel = (t) => { const k = Pages.notePending(t); if (!k) return ''; const reply = t.noteReply === 1 || t.noteReply === true; return k === 'staff' ? (reply ? 'ردّ الفني' : 'ملاحظة من الفني') : t.noteReply == null ? 'ردّ الموظف' : reply ? 'ردّ الموظف' : 'ملاحظة من الموظف'; };
Pages.noteNew = (t) => !!Pages.notePending(t) && !NoteSeen.seen(t);
Pages.noteChip = (t) => { const k = Pages.notePending(t); if (!k) return ''; return html`<span class="nchip${Pages.noteNew(t) ? ' is-new' : ''}" title="${Pages.noteNew(t) ? 'لم تفتحها بعد' : 'بانتظار ردك'}">${UI.chip(k === 'staff' ? 'amber' : 'teal', Pages.noteLabel(t), 'send')}</span>`; };
/* سطر الملاحظة تحت عنوان البلاغ في القوائم: من كتبها ومقتطف منها، فيعرف الفني ما كُتب قبل أن يفتح البلاغ */
Pages.noteLine = (t) => { const k = Pages.notePending(t); if (!k || !t.noteText) return ''; const tx = String(t.noteText).replace(/\s+/g, ' '); return html`<div class="t-noteln tone-${k === 'staff' ? 'amber' : 'teal'}">${Pages.noteNew(t) ? html`<i class="nd" aria-label="جديدة"></i>` : UI.icon('send')}<b>${Data.userName(t.noteBy)}:</b> <span class="ellipsis">«${tx.length > 110 ? `${tx.slice(0, 110)}…` : tx}»</span> <span class="faint">${timeAgo(t.noteAt)}</span></div>`; };
Pages.noteRowCls = (t) => { const k = Pages.notePending(t); return k ? ` t-note t-note-${k === 'staff' ? 'amber' : 'teal'}${Pages.noteNew(t) ? ' t-note-new' : ''}` : ''; };
/* البلاغات التي فيها ملاحظة بانتظار رد هذا الحساب: للفني ما أُسند إليه أو يتابعه أو لم يُستلم بعد (ولمن يدير البلاغات كلها)، وللموظف بلاغاته */
Pages.noteTickets = async () => {
  const me = Auth.user; if (!me) return [];
  const pool = canUser(me, 'tickets.work') ? (await Promise.all(OPEN.map((s) => DB.getAll('tickets', 'status', KR(s))))).flat() : await DB.getAll('tickets', 'requester_createdAt', KR([me.id, 0], [me.id, Infinity]));
  const all = canUser(me, 'tickets.manage');
  return pool.filter((t) => { const k = Pages.notePending(t); if (!k) return false; if (k === 'staff') return true; return all || !t.assigneeId || t.assigneeId === me.id || (t.followers || []).includes(me.id); }).sort((a, b) => b.noteAt - a.noteAt);
};
Pages.tickets = async (ctx) => {
  const q = ctx.query, staff = Auth.can('tickets.all'), me = Auth.user.id;
  /* الفني يبدأ بما ينتظر الاستلام، فإن لم يكن شيء فبالمسند إليه */
  const first = !staff ? 'all' : q.scope ? '' : (await DB.count('tickets', 'status', KR('new'))) ? 'unassigned' : 'mine';
  const st = { scope: q.scope || first, view: q.view || localStorage.getItem(staff ? 'sq_tview' : 'sq_tview_e') || 'table', q: q.q || '', status: q.status || '', priority: q.priority || '', categoryId: q.cat || '', departmentId: q.dep || '', from: q.from || '', to: q.to || '', offset: Number(q.offset) || 0, limit: 25 };
  /* «ملاحظات الموظفين»: البلاغات التي كتب فيها الموظف ملاحظة أو رداً ينتظر الفني، وللموظف «ملاحظات الفني» التي تنتظر رده */
  const scopes = staff ? [['unassigned', 'بانتظار الاستلام', 'inbox'], ...((Auth.user.categories || []).length ? [['spec', 'تخصصي', 'tag']] : []), ['mine', 'المسندة إليّ', 'user'], ...(Auth.can('tickets.work') ? [['notes', 'ملاحظات الموظفين', 'send']] : []), ['open', 'كل المفتوحة', 'layers'], ['overdue', 'المتأخرة', 'alert'], ['all', 'كل البلاغات', 'database']] : [['all', 'كل بلاغاتي', 'ticket'], ['open', 'قيد المتابعة', 'clock'], ['notes', 'ملاحظات الفني', 'send'], ['closed', 'المنتهية', 'check']];
  const sel = (id, label, opts, val) => html`<select id="${id}" aria-label="${label}"><option value="">${label}</option>${opts.map((o) => html`<option value="${o.value}"${String(o.value) === String(val) ? raw(' selected') : ''}>${o.label}</option>`)}</select>`;
  ctx.view.innerHTML = String(html`
    ${UI.pageHead({ title: staff ? 'البلاغات' : 'بلاغاتي', sub: staff ? 'تابع البلاغات ووزّعها وأنجزها ضمن مواعيدها' : 'كل البلاغات التي قدّمتها وحالتها لحظة بلحظة', illu: 'bell', actions: html`${Auth.can('tickets.create') ? html`<a class="btn btn-primary" href="#/tickets/new">${UI.icon('plus')} بلاغ جديد</a>` : ''}<button class="btn" data-act="csv">${UI.icon('download')} تصدير Excel</button>` })}
    <div class="row" style="justify-content:space-between;align-items:flex-start"><div class="tabs" id="scopes"></div><div class="seg" role="radiogroup" aria-label="طريقة العرض" style="margin-bottom:16px">${[['table', 'قائمة', 'menu'], ['grid', 'شبكة', 'grid'], ...(staff ? [['board', 'لوحة', 'layers']] : [])].map(([k, l, ic]) => html`<label><input type="radio" name="tview" value="${k}"${st.view === k ? raw(' checked') : ''}><span>${UI.icon(ic)} ${l}</span></label>`)}</div></div>
    <section class="panel" id="tPanel"><div class="toolbar">
      <div class="search-box">${UI.icon('search')}<input id="tq" type="search" placeholder="ابحث برقم البلاغ أو العنوان أو اسم مقدم البلاغ" value="${st.q}"></div>
      ${sel('tstatus', 'كل الحالات', Object.entries(STATUS).map(([k, v]) => ({ value: k, label: v.label })), st.status)}
      ${sel('tprio', 'كل الأولويات', Object.entries(PRIORITY).map(([k, v]) => ({ value: k, label: v.label })), st.priority)}
      ${sel('tcat', 'كل الفئات', UI.opts('categories'), st.categoryId)}
      ${staff ? sel('tdep', 'كل الأقسام', UI.opts('departments'), st.departmentId) : ''}
      <input type="date" dir="ltr" lang="en-GB" id="tfrom" value="${st.from}" aria-label="من تاريخ" title="من تاريخ"><input type="date" dir="ltr" lang="en-GB" id="tto" value="${st.to}" aria-label="إلى تاريخ" title="إلى تاريخ">
      <button class="btn btn-ghost btn-sm" data-act="clear">${UI.icon('x')} مسح</button>
    </div><div id="tbody"></div></section><div id="tBoard" hidden></div>`);
  if (!staff && st.view === 'board') st.view = 'table';
  const view = ctx.view, body = $('#tbody', view), myCats = new Set(Auth.user.categories || []);
  let live = new Map();
  const liveOn = (t) => staff && t.assigneeId && t.assigneeId !== me && OPEN.includes(t.status) && (live.get(t.assigneeId) || {}).active;
  const filter = () => {
    const f = { q: st.q, priority: st.priority, categoryId: st.categoryId, departmentId: st.departmentId, from: fromDateInput(st.from), to: st.to ? fromDateInput(st.to, true) : 0, offset: st.offset, limit: st.limit };
    if (!staff) { f.requesterId = me; f.status = st.status || (st.scope === 'open' ? OPEN : st.scope === 'closed' ? ['resolved', 'closed', 'cancelled'] : ''); return f; }
    if (st.scope === 'mine') { f.assigneeId = me; f.status = st.status || OPEN; }
    else if (st.scope === 'unassigned') f.status = 'new';
    else if (st.scope === 'open' || st.scope === 'spec') f.status = st.status || OPEN;
    else { if (st.scope === 'overdue') f.overdue = true; if (st.status) f.status = st.status; }
    return f;
  };
  const fetch = async (all = false) => {
    const f = filter(); if (all) { f.offset = 0; f.limit = 1e6; }
    if (st.scope === 'notes') {
      const qn = normalizeAr(f.q), rows = (await Pages.noteTickets()).filter((t) => (!st.status || t.status === st.status) && (!f.priority || t.priority === f.priority) && (!f.categoryId || t.categoryId === f.categoryId) && (!f.departmentId || t.departmentId === f.departmentId) && (!qn || String(t.search).includes(qn)) && (!f.from || t.createdAt >= f.from) && (!f.to || t.createdAt <= f.to));
      return { rows: rows.slice(f.offset, f.offset + f.limit), hasMore: rows.length > f.offset + f.limit };
    }
    if (staff && Array.isArray(f.status) && ['mine', 'open', 'spec'].includes(st.scope)) {
      const lists = await Promise.all(f.status.map((s) => (st.scope === 'mine' ? DB.getAll('tickets', 'assignee_status', KR([me, s])) : DB.getAll('tickets', 'status_createdAt', KR([s, f.from || 0], [s, f.to || Infinity])))));
      const qn = normalizeAr(f.q), rows = lists.flat().filter((t) => (!f.priority || t.priority === f.priority) && (!f.categoryId || t.categoryId === f.categoryId) && (!f.departmentId || t.departmentId === f.departmentId) && (!qn || String(t.search).includes(qn)) && (!f.from || t.createdAt >= f.from) && (!f.to || t.createdAt <= f.to) && (st.scope !== 'spec' || (myCats.has(t.categoryId) && (!t.assigneeId || t.assigneeId === me)))).sort((a, b) => b.createdAt - a.createdAt);
      return { rows: rows.slice(f.offset, f.offset + f.limit), hasMore: rows.length > f.offset + f.limit };
    }
    if (f.status === '') delete f.status;
    return Data.tickets.list(f);
  };
  const row = (t) => html`<tr data-href="#/tickets/${t.id}"${liveOn(t) || Pages.notePending(t) ? raw(` class="${liveOn(t) ? 't-live' : ''}${Pages.noteRowCls(t)}"`) : ''}><td><div class="t-title"><span class="t-ico">${UI.illu(catIllu(t.categoryId))}${Pages.noteNew(t) ? html`<i class="t-ico-dot" title="ملاحظة لم تفتحها بعد"></i>` : ''}</span><div style="min-width:0"><div class="ellipsis" style="max-width:400px">${t.title}</div><div class="t-sub"><span class="t-num">${t.number}</span> ${Data.nameOf('categories', t.categoryId, 'أخرى')}${t.attachmentCount ? html` ${UI.icon('clip')}${t.attachmentCount}` : ''} ${Pages.noteChip(t)}</div>${Pages.noteLine(t)}</div></div></td>
    <td>${staff ? html`<div class="row nowrap" style="gap:8px;flex-wrap:nowrap">${UI.avatar(t.requesterId, 'av-sm')}<div><div>${Data.userName(t.requesterId)}</div><div class="t-sub">${Data.nameOf('departments', t.departmentId, '')}</div></div></div>` : Data.nameOf('departments', t.departmentId)}</td>
    <td>${UI.priority(t.priority)}</td><td>${UI.status(t.status)}</td>
    <td>${t.assigneeId ? html`<div class="row nowrap" style="gap:8px;flex-wrap:nowrap">${UI.avatar(t.assigneeId, 'av-sm')}<span>${Data.userName(t.assigneeId)}</span>${liveOn(t) ? html`<span class="live-chip" title="الفني متصل ونشط الآن">قيد العمل</span>` : ''}${staff && t.handover && t.handover.text && OPEN.includes(t.status) ? html`<span class="ho-dot" title="ملاحظة تسليم: ${t.handover.text}">${UI.icon('clipboard')}</span>` : ''}</div>` : html`<span class="faint">لم يُسند بعد</span>`}</td>
    <td>${UI.sla(t)}</td><td class="nowrap faint" title="${fmtDateTime(t.createdAt)}">${timeAgo(t.createdAt)}</td></tr>`;
  const sync = () => history.replaceState(null, '', '#/tickets?' + new URLSearchParams(Object.entries({ scope: st.scope, view: st.view === 'table' ? '' : st.view, q: st.q, status: st.status, priority: st.priority, cat: st.categoryId, dep: st.departmentId, from: st.from, to: st.to, offset: st.offset || '' }).filter(([, v]) => v !== '' && v != null)));
  const tabs = async () => {
    let counts = {};
    const notes = await Pages.noteTickets(), fresh = notes.filter(Pages.noteNew).length;
    if (staff) { const [mine, neu, all, over] = await Promise.all([Promise.all(OPEN.map((s) => Data.tickets.countFor(me, s))), DB.count('tickets', 'status', KR('new')), Data.tickets.countByStatus(), Data.tickets.countOverdue()]); counts = { mine: mine.reduce((a, b) => a + b, 0), unassigned: neu, open: OPEN.reduce((a, k) => a + all[k], 0), overdue: over }; }
    else { const mineAll = await DB.getAll('tickets', 'requester_createdAt', KR([me, 0], [me, Infinity])); counts = { all: mineAll.length, open: mineAll.filter((t) => OPEN.includes(t.status)).length, closed: mineAll.filter((t) => !OPEN.includes(t.status)).length }; }
    counts.notes = notes.length;
    if (!ctx.alive()) return;
    $('#scopes', view).innerHTML = String(html`${scopes.map(([k, l, ic]) => html`<button class="tab ${st.scope === k ? 'active' : ''}${k === 'notes' && notes.length ? ' tab-note' : ''}${k === 'notes' && fresh ? ' has-new' : ''}" data-scope="${k}"${k === 'notes' && fresh ? raw(` title="${fresh} لم تفتحها بعد"`) : ''}>${UI.icon(ic)}${l}${counts[k] != null ? html`<span class="count">${fmtNum(counts[k])}</span>` : ''}</button>`)}`);
  };
  const load = async () => {
    sync();
    const board = $('#tBoard', view), panel = $('#tPanel', view);
    if (staff && st.view === 'board') { panel.hidden = true; board.hidden = false; await Board.render(board, { all: st.scope !== 'mine', limit: 30 }); return; }
    panel.hidden = false; board.hidden = true; panel.classList.toggle('vm-grid', st.view === 'grid');
    const [res, lv] = await Promise.all([fetch(), staff ? Presence.map() : new Map()]); if (!ctx.alive()) return; live = lv;
    body.innerHTML = String(res.rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>البلاغ</th><th>${staff ? 'مقدم البلاغ' : 'القسم'}</th><th>الأولوية</th><th>الحالة</th><th>المسؤول</th><th>الموعد</th><th>الإنشاء</th></tr></thead><tbody class="stagger">${res.rows.map(row)}</tbody></table></div>${UI.pager({ offset: st.offset, limit: st.limit, count: res.rows.length, hasMore: res.hasMore })}` : UI.empty({ illu: 'box', title: 'لا توجد بلاغات مطابقة', text: st.q || st.status || st.priority || st.categoryId ? 'غيّر عوامل التصفية أو ابحث بكلمة أخرى.' : 'لا توجد بلاغات في هذا القسم حالياً.', action: Auth.can('tickets.create') ? html`<a class="btn btn-primary" href="#/tickets/new">${UI.icon('plus')} بلاغ جديد</a>` : '' }));
  };
  const reset = () => { st.offset = 0; load(); };
  $('#tq', view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); reset(); }, 320));
  [['tstatus', 'status'], ['tprio', 'priority'], ['tcat', 'categoryId'], ['tdep', 'departmentId'], ['tfrom', 'from'], ['tto', 'to']].forEach(([id, k]) => { const el = $('#' + id, view); if (el) el.addEventListener('change', () => { st[k] = el.value; reset(); }); });
  UI.on(view, 'click', '[data-act="clear"]', () => { Object.assign(st, { q: '', status: '', priority: '', categoryId: '', departmentId: '', from: '', to: '' }); $$('.toolbar input, .toolbar select', view).forEach((el) => { el.value = ''; }); reset(); });
  UI.on(view, 'click', '[data-scope]', (e, el) => { st.scope = el.dataset.scope; st.status = ''; const s = $('#tstatus', view); if (s) s.value = ''; $$('[data-scope]', view).forEach((b) => b.classList.toggle('active', b === el)); reset(); });
  UI.on(view, 'change', 'input[name="tview"]', (e, el) => { st.view = el.value; try { localStorage.setItem(staff ? 'sq_tview' : 'sq_tview_e', el.value); } catch (_) { /* تجاهل */ } load(); });
  UI.on(view, 'click', '[data-page]', (e, el) => { st.offset = Math.max(0, st.offset + (el.dataset.page === 'next' ? st.limit : -st.limit)); load().then(() => $('#tPanel', view).scrollIntoView({ behavior: 'smooth', block: 'start' })); });
  UI.on(view, 'click', 'tr[data-href]', (e, el) => { if (!e.target.closest('a,button')) Router.go(el.dataset.href.slice(1)); });
  UI.on(view, 'click', '[data-act="csv"]', async (e, btn) => {
    UI.busy(btn, true);
    try {
      const { rows } = await fetch(true);
      downloadBlob(new Blob([toCSV(rows, [{ label: 'رقم البلاغ', key: 'number' }, { label: 'العنوان', key: 'title' }, { label: 'الفئة', value: (t) => Data.nameOf('categories', t.categoryId, '') }, { label: 'الأولوية', value: (t) => PRIORITY[t.priority].label }, { label: 'الحالة', value: (t) => STATUS[t.status].label }, { label: 'مقدم البلاغ', value: (t) => Data.userName(t.requesterId) }, { label: 'القسم', value: (t) => Data.nameOf('departments', t.departmentId, '') }, { label: 'المسؤول', value: (t) => (t.assigneeId ? Data.userName(t.assigneeId) : '') }, { label: 'تاريخ الإنشاء', value: (t) => fmtDateTime(t.createdAt) }, { label: 'تاريخ الحل', value: (t) => (t.resolvedAt ? fmtDateTime(t.resolvedAt) : '') }, { label: 'ضمن الموعد', value: (t) => (t.resolvedAt ? (t.resolvedAt <= t.dueAt ? 'نعم' : 'لا') : '') }, { label: 'التقييم', key: 'rating' }])], { type: 'text/csv;charset=utf-8' }), `البلاغات-${dateInput(now())}.csv`);
      UI.toast(`تم تصدير ${arCount(rows.length, AR.ticket)}`);
    } catch (ex) { UI.error(ex); } finally { UI.busy(btn, false); }
  });
  ctx.onCleanup(Bus.on('tickets', debounce(() => { if (ctx.alive()) { load(); tabs(); } }, 500)));
  await Promise.all([tabs(), load()]);
};

/* ── بلاغ جديد: معالج من ثلاث خطوات ─────────────────────────── */
const QUICK_TITLES = { hardware: ['الجهاز لا يعمل', 'بطء شديد في الجهاز', 'الشاشة لا تعرض صورة', 'تعطل لوحة المفاتيح أو الماوس'], printer: ['الطابعة لا تطبع', 'انحشار الورق', 'طباعة باهتة أو مخططة', 'تعريف طابعة جديدة'], network: ['لا يوجد اتصال بالشبكة', 'بطء في الإنترنت', 'تركيب نقطة شبكة جديدة'], software: ['طلب تثبيت برنامج', 'البرنامج لا يفتح', 'رسالة خطأ في النظام'], email: ['نسيت كلمة مرور البريد', 'البريد لا يستقبل الرسائل', 'طلب بريد جديد'], card: ['إصدار بطاقة جديدة', 'بدل فاقد', 'تم الترقية'], path_code: ['طلب رمز جديد', 'الرمز لا يعمل'], backup: ['إنشاء حساب على نظام المراسلات', 'طلب صلاحية على سجل', 'استخراج وثيقة محفوظة'], ink: ['طلب حبر للطابعة', 'الحبر المركّب لا يعمل'], scanner: ['الماسح لا يعمل', 'إعداد المسح إلى البريد'], service_request: ['طلب خدمة شبكة', 'طلب مجلد مشترك'], other: [] };
const PRIO_HINT = { low: 'يمكن الانتظار', medium: 'يؤثر على العمل', high: 'يعطّل العمل', urgent: 'يوقف العمل بالكامل' };
Pages.newTicket = async (ctx) => {
  const cats = Data.list('categories').filter((c) => !c.hidden || c.id === ctx.query.cat), view = ctx.view, files = [], urls = [];
  const st = { cat: Data.c.categories.get(ctx.query.cat) ? ctx.query.cat : '', step: 1 };
  if (st.cat) st.step = 2;
  ctx.onCleanup(() => urls.forEach((x) => URL.revokeObjectURL(x)));
  const steps = () => html`<div class="wiz-steps">${['نوع المشكلة', 'تفاصيل البلاغ', 'المراجعة والإرسال'].map((l, i) => html`<div class="wiz-step ${st.step === i + 1 ? 'on' : st.step > i + 1 ? 'done' : ''}"><i>${st.step > i + 1 ? UI.icon('check') : i + 1}</i>${l}</div>`)}</div>`;
  const head = UI.pageHead({ title: 'بلاغ جديد', illu: 'bell' });
  const save = () => { const form = $('#tkForm', view); if (form) Object.assign(st, UI.formValues(form)); const cf = $('#catFields', view); if (cf) st.x = Forms.values(cf); const pb = $('[data-persons]', view); if (pb) st.persons = Forms.readPersons(pb); const cb2 = $('[data-codes]', view); if (cb2) st.codes = Forms.readCodes(cb2); };
  const step1 = () => {
    view.innerHTML = String(html`${head}${steps()}${UI.panel({ title: 'ما نوع المشكلة؟', icon: 'grid', sub: 'اختر الفئة الأقرب لمشكلتك', body: html`<div class="tiles stagger">${cats.map((c) => html`<button type="button" class="tile tilt ${st.cat === c.id ? 'selected' : ''}" data-cat="${c.id}">${UI.illu('cat:' + c.id)}<b>${c.name}</b><small>${(QUICK_TITLES[c.id] || [])[0] || 'مشكلة أخرى'}</small></button>`)}</div>` })}`);
  };
  const renderFiles = () => {
    const list = $('#fileList', view); if (!list) return;
    list.innerHTML = String(html`${files.map((f, i) => { let thumb = UI.icon('file'); if (f.type.startsWith('image/')) { if (!f._url) { f._url = URL.createObjectURL(f); urls.push(f._url); } thumb = html`<img src="${f._url}" alt="">`; } return html`<div class="file"><div class="thumb">${thumb}</div><div class="fname" title="${f.name}">${f.name}</div><button type="button" class="rm" data-rm="${i}" aria-label="حذف المرفق">${UI.icon('x')}</button></div>`; })}`);
  };
  const step2 = () => {
    const c = Data.c.categories.get(st.cat) || cats[0];
    view.innerHTML = String(html`${head}${steps()}<div class="grid g-side">
      ${UI.panel({ title: 'تفاصيل البلاغ', icon: 'edit', body: html`<form id="tkForm" novalidate class="stack" style="gap:16px">
        <div class="chosen">${UI.illu('cat:' + c.id)}<div class="grow"><div class="faint small">الفئة المختارة</div><b style="font-size:16px">${c.name}</b></div><button type="button" class="btn btn-ghost btn-sm" data-act="back1">${UI.icon('edit')} تغيير</button>${canCatAdmin() ? html`<button type="button" class="btn btn-soft btn-sm fs-live" data-act="fsedit" title="عدّل خانات هذا النموذج ونصوصه وإلزاميتها مباشرة">${UI.icon('sliders')} تعديل النموذج</button>` : ''}</div>
        <div data-svcnote></div>${Pages.catNotes(c.id)}${Pages.categoryFormBar(c.id)}<div id="catFields">${Forms.render(c.id, st.x || {})}</div>${c.id === 'card' ? Forms.personsBlock(st.persons || []) : ''}${c.id === 'path_code' ? Forms.codeBlock(st.codes || []) : ''}
        <div class="field"><label for="tt">${Forms.titleLabel(c.id)}<em>*</em></label><input id="tt" name="title" maxlength="120" placeholder="${catCfg(c.id) ? 'اكتب عنواناً مختصراً وواضحاً' : 'مثال: الطابعة في مكتب 12 لا تطبع'}" value="${st.title || ''}">${Forms.quickTitles(c.id).length ? html`<div class="quick-chips" style="margin-top:6px">${Forms.quickTitles(c.id).map((x) => html`<button type="button" class="qchip" data-quick="${x}">${x}</button>`)}</div>` : ''}</div>
        <div class="field"><label for="td">${Forms.sys(c.id, 'desc').l}${Forms.sys(c.id, 'desc').req ? html`<em>*</em>` : ''}</label><textarea id="td" name="description" rows="4" placeholder="${Forms.descHint(c.id)}">${st.description || ''}</textarea><div class="desc-tools" data-desctools></div></div>
        <div class="field"><label>مدى تأثير المشكلة</label><div class="seg" role="radiogroup">${Object.entries(PRIORITY).reverse().map(([k, p]) => html`<label class="tone-${p.tone}"><input type="radio" name="priority" value="${k}"${(st.priority || 'medium') === k ? raw(' checked') : ''}><span><i class="dot"></i>${p.label}<small class="faint">${PRIO_HINT[k]}</small></span></label>`)}</div><small class="hint" id="slaHint"></small></div>
        ${Forms.baseFields(c.id, st)}
        <div class="field"><label>المرفقات (صور أو ملفات)</label><div class="dropzone" id="drop" tabindex="0" role="button">${UI.icon('upload')}<b>اسحب الملفات هنا أو انقر للاختيار</b><span class="small faint">حتى 5 ملفات، 10 ميجابايت لكل ملف</span></div><div class="files" id="fileList" style="margin-top:10px"></div></div>
      </form>` })}
      <div class="stack">
        ${UI.panel({ title: 'حلول قد تغنيك عن الانتظار', icon: 'book', body: html`<div id="kbSuggest" class="stack" style="gap:10px"><p class="faint small">اكتب عنوان المشكلة لعرض حلول مقترحة من قاعدة المعرفة.</p></div>` })}
        ${UI.panel({ title: 'ماذا يحدث بعد الإرسال؟', icon: 'info', body: html`<div class="timeline"><div class="tl"><span class="tl-icon tone-sky">${UI.icon('send')}</span><div class="tl-head">يصل البلاغ فوراً إلى الفنيين</div></div><div class="tl"><span class="tl-icon tone-violet">${UI.icon('user-plus')}</span><div class="tl-head">يستلمه فني ويتواصل معك</div></div><div class="tl"><span class="tl-icon tone-teal">${UI.icon('check')}</span><div class="tl-head">تؤكد الحل وتقيّم الخدمة</div></div></div>` })}
      </div></div>
      <div class="row mt" style="justify-content:space-between"><button class="btn btn-ghost" data-act="back1">${UI.icon('chevron-right')} السابق</button><button class="btn btn-primary btn-lg" data-act="review">المراجعة ${UI.icon('chevron-left')}</button></div>`);
    Pages.serviceNotice(c.id).then((h) => { const el = $('[data-svcnote]', view); if (el) el.innerHTML = String(h); UI.hydrate(el); }).catch(() => {});
    const form = $('#tkForm', view), title = $('#tt', form), desc = $('#td', form), cf = $('#catFields', view);
    UI.bindOrgChain(form, { value: (form.querySelector('[name="unitId"]') || {}).value || '' });
    if (cf) cf.addEventListener('change', (e) => { const key = String((e.target || {}).name || '').slice(2); const defs = Forms.def(c.id); const deps = defs.some((f) => f.dep === key || (f.showIf && Object.keys(f.showIf).includes(key))); const vals = Forms.values(cf); st.x = vals; if (deps) cf.innerHTML = String(Forms.render(c.id, vals)); const sug = Forms.title(c.id, vals); if (sug && (!title.value.trim() || title.dataset.auto === '1')) { title.value = sug; title.dataset.auto = '1'; title.dispatchEvent(new Event('input')); } });
    title.addEventListener('input', () => { if (title.dataset.auto === '1' && cf && title.value !== Forms.title(c.id, Forms.values(cf))) title.dataset.auto = ''; });
    const slaHint = () => { const p = UI.formValues(form).priority || 'medium', s = Data.c.settings.sla[p]; $('#slaHint', view).textContent = `الوقت المستهدف للحل: ${fmtDuration(s.resolve * MIN)}، وأول استجابة خلال ${fmtDuration(s.respond * MIN)}`; };
    slaHint(); form.addEventListener('change', slaHint);
    const suggest = debounce(async () => {
      const text = `${title.value} ${desc.value}`.trim(), box = $('#kbSuggest', view); if (!box) return;
      if (text.length < 3) { box.innerHTML = '<p class="faint small">اكتب عنوان المشكلة لعرض حلول مقترحة من قاعدة المعرفة.</p>'; return; }
      const res = (await Data.kb.search(text, '')).slice(0, 3); if (!ctx.alive() || !$('#kbSuggest', view)) return;
      box.innerHTML = String(res.length ? html`${res.map((a) => html`<button type="button" class="kb-card" data-kb="${a.id}"><b>${a.title}</b><p>${a.body}</p><span class="kb-meta">${UI.icon('eye')} ${fmtNum(a.views)} ${UI.icon('check')} ${fmtNum(a.helpful)} وجدوه مفيداً</span></button>`)}` : html`<p class="faint small">لا توجد حلول مطابقة، أكمل البلاغ وسنساعدك.</p>`);
    }, 350);
    title.addEventListener('input', suggest); desc.addEventListener('input', suggest); suggest();
    Pages.descTools($('[data-desctools]', view), desc, c.id);
    const addFiles = (list) => { for (const f of list) { if (files.length >= 5) { UI.toast('الحد الأقصى 5 مرفقات', 'warn'); break; } if (f.size > 10 * 1048576) { UI.toast(`الملف ${f.name} أكبر من 10 ميجابايت`, 'warn'); continue; } files.push(f); } renderFiles(); };
    const drop = $('#drop', view);
    drop.addEventListener('sq:files', (e) => addFiles(e.detail || []));
    if (typeof FF !== 'undefined' && FF.pending.length) addFiles(FF.pending.splice(0));
    drop.onclick = async () => addFiles(await UI.pickFiles({ accept: 'image/*,.pdf,.doc,.docx,.xls,.xlsx,.txt' }));
    drop.onkeydown = (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); drop.click(); } };
    ['dragenter', 'dragover'].forEach((ev) => drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.add('over'); }));
    ['dragleave', 'drop'].forEach((ev) => drop.addEventListener(ev, (e) => { e.preventDefault(); drop.classList.remove('over'); }));
    drop.addEventListener('drop', (e) => addFiles([...e.dataTransfer.files]));
    renderFiles(); title.focus();
  };
  const step3 = () => {
    const c = Data.c.categories.get(st.cat) || cats[0], pr = st.priority || 'medium';
    view.innerHTML = String(html`${head}${steps()}<div class="grid g-main">
      ${UI.panel({ title: 'راجع بلاغك قبل الإرسال', icon: 'eye', body: html`<div class="chosen">${UI.illu('cat:' + c.id)}<div class="grow"><div class="faint small">${c.name}</div><b style="font-size:18px">${st.title}</b></div>${UI.priority(pr)}</div>
        ${st.description ? html`<p class="bubble mt">${st.description}</p>` : ''}
        <dl class="kv mt">${(Forms.extra(st.cat, st.x || {}) || { fields: [] }).fields.map((f) => html`<dt>${UI.icon('tag')} ${f.label}</dt><dd>${f.value}</dd>`)}<dt>${UI.icon('building')} الإدارة</dt><dd>${Data.nameOf('departments', st.departmentId)}${st.unitPath ? html`<div class="t-sub">${st.unitPath}</div>` : ''}</dd><dt>${UI.icon('phone')} التواصل</dt><dd><span class="ltr">${st.contact || '—'}</span></dd><dt>${UI.icon('monitor')} الجهاز</dt><dd>${[st.deviceName, st.printerBrand, st.printerModel].filter(Boolean).join(' — ') || '—'}</dd>${st.cat === 'card' && (st.persons || []).length ? html`<dt>${UI.icon('users')} أشخاص إضافيون</dt><dd>${st.persons.map((p) => [p.rank, p.name, p.militaryNo ? `(${p.militaryNo})` : ''].filter(Boolean).join(' ')).join('، ')}</dd>` : ''}${st.cat === 'path_code' && (st.codes || []).length ? html`<dt>${UI.icon('key')} الأشخاص المطلوب إصدار رمز لهم (${fmtNum(st.codes.length)})</dt><dd><ol class="codes-ol">${st.codes.map((p) => html`<li>${p.name || '—'}${p.militaryNo ? html` <span class="ltr faint">${p.militaryNo}</span>` : ''}</li>`)}</ol></dd>` : ''}<dt>${UI.icon('clip')} المرفقات</dt><dd>${files.length ? files.map((f) => f.name).join('، ') : 'لا يوجد'}</dd><dt>${UI.icon('clock')} الموعد المستهدف</dt><dd>${fmtDuration(Data.c.settings.sla[pr].resolve * MIN)}</dd></dl>` })}
      ${UI.panel({ title: 'جاهز للإرسال', icon: 'send', body: html`<div class="center stack" style="gap:12px;align-items:center">${UI.illu('bell', 'head-illu')}<p class="muted">سيصل البلاغ إلى فريق الدعم الفني فور الإرسال، وستتلقى إشعاراً عند كل تحديث.</p><button class="btn btn-primary btn-lg btn-block" data-act="submit">${UI.icon('send')} إرسال البلاغ</button><button class="btn btn-ghost btn-block" data-act="back2">${UI.icon('edit')} تعديل التفاصيل</button></div>` })}
    </div>`);
  };
  const render = () => { if (st.step === 1) step1(); else if (st.step === 2) step2(); else step3(); UI.hydrate(view); };
  UI.on(view, 'click', '.tile[data-cat]', (e, el) => { st.cat = el.dataset.cat; $$('.tile', view).forEach((x) => x.classList.toggle('selected', x === el)); setTimeout(() => { if (!ctx.alive()) return; st.step = 2; render(); window.scrollTo({ top: 0, behavior: 'smooth' }); }, 220); });
  UI.on(view, 'click', '[data-act="back1"]', () => { save(); st.step = 1; render(); });
  UI.on(view, 'click', '[data-act="back2"]', () => { st.step = 2; render(); });
  UI.on(view, 'click', '[data-act="fsedit"]', async () => { save(); if (await Pages.formStudioOverlay(st.cat)) { if (!ctx.alive()) return; render(); UI.toast('طُبّق تعديل النموذج، وبقيت القيم التي كتبتها', 'success'); } });
  UI.on(view, 'click', '[data-quick]', (e, el) => { const t = $('#tt', view); t.value = el.dataset.quick; t.dispatchEvent(new Event('input')); t.focus(); });
  UI.on(view, 'click', '[data-rm]', (e, el) => { files.splice(Number(el.dataset.rm), 1); renderFiles(); });
  UI.on(view, 'click', '[data-kb]', (e, el) => Pages.kbArticle(el.dataset.kb));
  const markMissing = () => {
    $$('.field-miss', view).forEach((el) => { el.classList.remove('field-miss'); const m = el.querySelector('.miss-msg'); if (m) m.remove(); });
    const form = $('#tkForm', view), out = [], mark = (el, label, msg = 'هذه الخانة مطلوبة') => { const box = el && (el.closest('.field') || el); if (!box) return; box.classList.add('field-miss'); box.insertAdjacentHTML('beforeend', `<small class="miss-msg">${esc(msg)}</small>`); out.push({ box, label }); };
    const cf = $('#catFields', view), v = st.x || {};
    Forms.def(st.cat).filter((f) => f.req && Forms.visible(f, v) && !v[f.k]).forEach((f) => mark(cf && cf.querySelector(`[name="x_${f.k}"]`), f.l));
    $$('.persons-box input[required], .persons-box [data-req]', form).forEach((el) => { if (!String(el.value || '').trim()) mark(el, el.placeholder || 'بيانات الشخص'); });
    Forms.sysMissing(st.cat, view, st).forEach(([el, label, msg]) => mark(el, label, msg));
    if (String(st.title || '').trim().length < 3) mark($('#tt', view), Forms.titleLabel(st.cat), 'اكتب عنواناً واضحاً (3 أحرف على الأقل)');
    if (catFormRequired(st.cat) && !files.length) mark($('#drop', view), 'مستند الفئة', 'أرفق مستند الفئة بعد تعبئته (إلزامي لهذه الفئة)');
    else if (Forms.attachReq(st.cat) && !files.length) mark($('#drop', view), 'المرفقات', Forms.attachMsg(st.cat));
    return out;
  };
  view.addEventListener('input', (e) => { const b = e.target.closest && e.target.closest('.field-miss'); if (b) { b.classList.remove('field-miss'); const m = b.querySelector('.miss-msg'); if (m) m.remove(); } });
  view.addEventListener('change', (e) => { const b = e.target.closest && e.target.closest('.field-miss'); if (b) { b.classList.remove('field-miss'); const m = b.querySelector('.miss-msg'); if (m) m.remove(); } });
  UI.on(view, 'click', '[data-act="review"]', () => {
    save(); const miss = markMissing();
    if (miss.length) { UI.toast(`أكمل ${miss.length === 1 ? 'الخانة المطلوبة' : `${fmtNum(miss.length)} خانات مطلوبة`}: ${miss.map((m) => m.label).join('، ')}`, 'warn', 7000); miss[0].box.scrollIntoView({ behavior: 'smooth', block: 'center' }); const f = miss[0].box.querySelector('input:not([type=hidden]),select,textarea'); if (f) setTimeout(() => f.focus({ preventScroll: true }), 350); return; }
    st.step = 3; render(); window.scrollTo({ top: 0, behavior: 'smooth' });
  });
  UI.on(view, 'click', '[data-act="submit"]', async (e, btn) => {
    UI.busy(btn, true);
    try {
      const extra = Forms.extra(st.cat, st.x || {}) || {};
      /* كل قائمة لفئتها فقط: من كتب أشخاصاً ثم عاد وغيّر الفئة لا تُرفق قائمته ببلاغ من فئة أخرى */
      if (st.cat === 'card' && (st.persons || []).length) extra.persons = st.persons;
      if (st.cat === 'path_code' && (st.codes || []).length) extra.codes = st.codes;
      const t = await Data.tickets.create({ ...st, categoryId: st.cat, extra }, files);
      view.innerHTML = String(html`${head}<section class="panel"><div class="success"><div class="burst"><svg viewBox="0 0 24 24"><path d="M5 12.5l4.5 4.5L19 7.5" pathLength="1"/></svg></div><h2 style="font-size:24px">تم إرسال بلاغك بنجاح</h2><p class="muted">احتفظ برقم البلاغ للمتابعة، وسيصلك إشعار عند استلامه.</p><span class="stamp">${t.number}</span>${Ratings.submitWidget(t)}<div class="row" style="justify-content:center;margin-top:10px"><a class="btn btn-primary" href="#/tickets/${t.id}">${UI.icon('eye')} متابعة البلاغ</a>${eformOn(t.categoryId) ? html`<button type="button" class="btn btn-soft" data-eformview="${t.id}">${UI.icon('paper')} عرض الاستمارة وطباعتها</button>` : ''}<a class="btn" href="#/tickets/new">${UI.icon('plus')} بلاغ آخر</a><a class="btn btn-ghost" href="#/dashboard">${UI.icon('grid')} الرئيسية</a></div></div></section>`);
      const r = $('.burst', view).getBoundingClientRect(); UI.confetti(r.left + r.width / 2, r.top + r.height / 2);
    } catch (ex) { UI.error(ex); UI.busy(btn, false); }
  });
  render();
};

/* ── تفاصيل البلاغ ───────────────────────────────────────────── */
const slaDial = (t) => {
  const open = OPEN.includes(t.status), end = open ? now() : t.resolvedAt || t.closedAt || now(), total = Math.max(1, t.dueAt - t.createdAt), used = Math.max(0, end - t.createdAt), p = clamp(used / total, 0, 1), late = end > t.dueAt, tone = late ? 'red' : p > 0.75 ? 'amber' : 'teal', r = 72, C = 2 * Math.PI * r, arc = C * 0.75;
  return raw(`<div class="gauge tone-${tone}"><svg viewBox="0 0 180 180" aria-hidden="true"><g transform="rotate(135 90 90)"><circle class="trk" cx="90" cy="90" r="${r}" stroke-dasharray="${arc.toFixed(1)} ${C.toFixed(1)}"/><circle class="val" cx="90" cy="90" r="${r}" stroke-dasharray="${(arc * Math.max(p, 0.01)).toFixed(1)} ${C.toFixed(1)}"/></g></svg><div class="g-center"><b style="font-size:21px">${open ? (late ? 'متأخر' : esc(fmtDuration(t.dueAt - now()))) : late ? 'بعد الموعد' : 'ضمن الموعد'}</b><small>${open ? (late ? `منذ ${esc(fmtDuration(now() - t.dueAt))}` : 'متبقٍ على الموعد') : `استغرق ${esc(fmtDuration(used))}`}</small></div></div>`);
};
const EVENT_VIEW = {
  created: (e) => ['inbox', 'sky', html`<b>${Data.userName(e.userId)}</b> أنشأ البلاغ`],
  assigned: (e) => ['user-plus', 'violet', !e.userId ? html`إسناد تلقائي إلى <b>${Data.userName(e.to)}</b> حسب التخصص` : e.to === e.userId ? html`<b>${Data.userName(e.userId)}</b> استلم البلاغ` : html`<b>${Data.userName(e.userId)}</b> أسند البلاغ إلى <b>${Data.userName(e.to)}</b>`],
  status: (e) => ['refresh', (STATUS[e.to] || {}).tone || 'slate', e.userId ? html`<b>${Data.userName(e.userId)}</b> غيّر الحالة إلى ${UI.status(e.to)}` : html`<b>النظام</b> غيّر الحالة إلى ${UI.status(e.to)}`],
  comment: (e) => ['send', e.internal ? 'amber' : 'teal', html`<b>${Data.userName(e.userId)}</b> ${e.internal ? html`أضاف ${UI.chip('amber', 'ملاحظة داخلية', 'lock')}` : 'كتب رداً'}`],
  priority: (e) => ['alert', (PRIORITY[e.to] || {}).tone || 'amber', html`<b>${Data.userName(e.userId)}</b> غيّر الأولوية إلى ${UI.priority(e.to)}`],
  rating: (e) => ['star', 'brass', html`<b>${Data.userName(e.userId)}</b> قيّم الخدمة ${UI.stars(e.stars)}${(e.tags || []).length ? html`<span class="rt-evtags">${e.tags.map((g) => html`<i>${g}</i>`)}</span>` : ''}`],
  attachment: (e) => ['clip', 'sky', html`<b>${Data.userName(e.userId)}</b> أضاف مرفقات`],
  takeover: (e) => ['swap', 'amber', html`<b>${Data.userName(e.to)}</b> استكمل البلاغ بدلاً من <b>${Data.userName(e.from)}</b>`],
  handover: (e) => ['clipboard', 'violet', html`<b>${Data.userName(e.userId)}</b> ${e.text ? 'كتب ملاحظة تسليم' : 'أزال ملاحظة التسليم'}${e.release ? html` ${UI.chip('violet', 'أتاح البلاغ للاستكمال', 'swap')}` : ''}`]
};
/* سبب تعليق البلاغ: من صفحته ومن لوحة البلاغات */
Pages.holdModal = () => UI.modal({ title: 'تعليق البلاغ', icon: 'pause', body: html`<div class="quick-chips" style="margin-bottom:10px">${['بانتظار رد المستفيد', 'بانتظار قطعة غيار', 'بانتظار جهة خارجية', 'بانتظار موعد زيارة'].map((x) => html`<button type="button" class="qchip" data-hold="${x}">${x}</button>`)}</div>${UI.field({ name: 'text', label: 'سبب التعليق (يصل المستفيد)', type: 'textarea', rows: 3, required: true })}`, onMount: (form) => UI.on(form, 'click', '[data-hold]', (e, b) => { const ta = form.querySelector('textarea'); ta.value = b.dataset.hold; ta.focus(); }), actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تعليق', kind: 'primary', icon: 'pause', submit: true, handler: (form) => { const text = UI.formValues(form).text.trim(); if (!text) throw new AppError('اكتب سبب التعليق'); return { text }; } }] });
Pages.ticket = async (ctx) => {
  const id = ctx.params.id, me = Auth.user, staff = Auth.can('tickets.work'), mgr = Auth.can('tickets.manage'), view = ctx.view, urls = [];
  ctx.onCleanup(() => urls.forEach((x) => URL.revokeObjectURL(x)));
  let t = await Data.tickets.get(id), atts = [];
  if (!t) { view.innerHTML = String(UI.empty({ illu: 'box', title: 'البلاغ غير موجود', text: 'ربما حُذف أو أن الرابط غير صحيح.', action: html`<a class="btn btn-primary" href="#/tickets">العودة إلى البلاغات</a>` })); return; }
  if (!staff && t.requesterId !== me.id) throw new AppError('لا تملك صلاحية عرض هذا البلاغ');
  const templates = staff && !(await DB.get('meta', 'migrate:templates')) ? await DB.getAll('templates') : [];
  /* الملاحظة التي كانت جديدة حين فُتح البلاغ تبقى معلَّمة «جديدة» في هذه الزيارة، وتُسجَّل مقروءة فلا تنبض في القوائم بعد ذلك */
  let shownNew = 0;
  const draw = async () => {
    t = await Data.tickets.get(id); const events = await Data.tickets.events(id); atts = await Data.tickets.attachments(id);
    if (!ctx.alive()) return;
    const nk = Pages.notePending(t); if (Pages.noteNew(t)) shownNew = t.noteAt;
    const nFresh = !!nk && shownNew === t.noteAt, nReply = t.noteReply === 1 || t.noteReply === true, nName = Data.userName(t.noteBy);
    const nHead = nk === 'requester' ? (t.noteReply == null || nReply ? `ردّ ${nName} على الملاحظة` : `ملاحظة جديدة من ${nName}`) : nReply ? `ردّ ${nName} على ملاحظتك` : `ملاحظة من ${nName}`;
    const noteEv = nk ? events.filter((e) => e.type === 'comment' && !e.internal && e.userId === t.noteBy && Math.abs((e.at || 0) - t.noteAt) < 120000).pop() : null;
    urls.splice(0).forEach((x) => URL.revokeObjectURL(x));
    const c = Data.c.categories.get(t.categoryId) || { name: 'أخرى', illustration: 'box' }, req = Data.c.users.get(t.requesterId), mine = t.requesterId === me.id, can = staff && (t.assigneeId === me.id || mgr);
    const acts = [];
    if (staff && OPEN.includes(t.status) && !t.assigneeId) acts.push(html`<button class="btn btn-primary" data-act="claim">${UI.icon('user-plus')} استلام البلاغ</button>`);
    if (staff && OPEN.includes(t.status) && t.assigneeId && t.assigneeId !== me.id) acts.push(html`<button class="btn btn-soft" data-act="takeover" title="البلاغ مع ${Data.userName(t.assigneeId)} ولم يُنجز بعد">${UI.icon('swap')} استكمال البلاغ</button>`);
    if (staff && OPEN.includes(t.status) && t.assigneeId && (t.assigneeId === me.id || mgr)) acts.push(html`<button class="btn btn-ghost" data-act="handover" title="ملاحظة تظهر للفنيين ولمن يستكمل البلاغ">${UI.icon('clipboard')} ملاحظة تسليم</button>`);
    if (can && ['assigned', 'waiting'].includes(t.status)) acts.push(html`<button class="btn btn-soft" data-act="start">${UI.icon('play')} بدء العمل</button>`);
    if (can && ['assigned', 'in_progress'].includes(t.status)) acts.push(html`<button class="btn" data-act="wait">${UI.icon('pause')} تعليق</button>`);
    if (can && OPEN.includes(t.status)) acts.push(html`<button class="btn btn-ok" data-act="resolve">${UI.icon('check')} تم الحل</button>`);
    if (can && t.status === 'resolved') acts.push(html`<button class="btn" data-act="close">${UI.icon('lock')} إغلاق</button>`);
    if (staff && ['closed', 'cancelled'].includes(t.status)) acts.push(html`<button class="btn btn-ghost" data-act="reopen">${UI.icon('undo')} إعادة فتح</button>`);
    if ((mine && ['new', 'assigned'].includes(t.status)) || (mgr && OPEN.includes(t.status))) acts.push(html`<button class="btn btn-ghost" data-act="cancel">${UI.icon('x')} إلغاء</button>`);
    acts.push(html`<button class="icon-btn" data-act="print" title="طباعة" aria-label="طباعة">${UI.icon('print')}</button>`);
    const gallery = atts.map((a) => { let thumb = UI.icon('file'); if (a.blob && String(a.type).startsWith('image/')) { a._url = URL.createObjectURL(a.blob); urls.push(a._url); thumb = html`<img src="${a._url}" alt="">`; } return html`<div class="file" data-att="${a.id}" title="${a.name}"><div class="thumb">${thumb}</div><div class="fname">${a.name}</div></div>`; });
    const tl = events.filter((e) => staff || !e.internal).map((e) => { const [ic, tone, headline] = (EVENT_VIEW[e.type] || EVENT_VIEW.comment)(e), hot = noteEv && e === noteEv; return html`<div class="tl${hot ? ` tl-note tone-${nk === 'staff' ? 'amber' : 'teal'}` : ''}"${hot ? raw(' id="tlNote"') : ''}><span class="tl-icon tone-${tone}">${UI.icon(ic)}</span><div style="min-width:0"><div class="tl-head">${headline}${hot ? html` <span class="tl-flag">${nFresh ? 'جديدة' : 'بانتظار الرد'}</span>` : ''}<span class="tl-time" title="${fmtDateTime(e.at)}">${timeAgo(e.at)}</span></div>${e.text ? html`<div class="bubble ${e.type === 'handover' ? 'ho' : e.internal ? 'internal' : e.userId === me.id ? 'mine' : ''}">${e.text}</div>` : ''}</div></div>`; });
    view.innerHTML = String(html`
      ${UI.pageHead({ crumbs: html`<a href="#/tickets">البلاغات</a>${UI.icon('chevron-left')}<span class="ltr">${t.number}</span>`, title: t.title, illu: 'cat:' + c.id, sub: html`<span class="row" style="gap:8px;margin-top:6px">${UI.status(t.status)}${UI.priority(t.priority)}<span class="faint small">فُتح ${timeAgo(t.createdAt)} بواسطة ${Data.userName(t.requesterId)}</span></span>`, actions: acts })}
      ${staff ? html`<div id="liveWork"></div>${Pages.handoverBox(t, me, mgr)}` : ''}${Ratings.ticketBar(t, staff)}
      ${nk ? html`<div class="banner tone-${nk === 'staff' ? 'amber' : 'teal'} note-bar${nFresh ? ' is-new' : ''}" role="status"><span class="nb-ico">${UI.icon('send')}${nFresh ? html`<i class="nd"></i>` : ''}</span><div class="grow"><b>${nHead}</b>${nFresh ? html` <span class="nb-new">جديدة</span>` : ''} <span class="faint small">${timeAgo(t.noteAt)}</span><p class="note-text">${t.noteText}</p></div><div class="row" style="gap:6px;flex-wrap:nowrap">${noteEv ? html`<button type="button" class="btn btn-sm btn-ghost" data-act="seenote">${UI.icon('eye')} في المحادثة</button>` : ''}<button type="button" class="btn btn-sm ${nk === 'staff' ? 'btn-primary' : 'btn-soft'}" data-act="replynote">${UI.icon('send')} ${nk === 'staff' ? 'الرد على الملاحظة' : 'الرد على الموظف'}</button></div></div>` : ''}
      <div class="grid g-side">
        <div class="stack">
          ${UI.panel({ title: 'مسار البلاغ', icon: 'layers', body: Pages.stepper(t) })}
          ${UI.panel({ title: 'وصف المشكلة', icon: 'file', tools: staff || mine ? html`<button class="btn btn-ghost btn-sm" data-act="attach">${UI.icon('clip')} إضافة مرفق</button>` : '', body: html`<p class="article" style="font-size:14.5px;line-height:1.9">${t.description || 'لم يُكتب وصف.'}</p>${Forms.summary(t)}${atts.length ? html`<div class="files mt">${gallery}</div>` : ''}` })}
          ${UI.panel({ title: 'المحادثة والسجل', icon: 'pulse', body: html`<div class="timeline">${tl}</div>${!['closed', 'cancelled'].includes(t.status) || staff ? html`<div class="mt" id="composer"><div class="field">${staff ? UI.replyTools('ticket', 'cmt') : ''}<textarea id="cmt" rows="3" aria-label="نص الرد" placeholder="${staff ? 'اكتب رداً للمستفيد أو ملاحظة داخلية...' : 'أضف معلومة أو استفساراً للفني...'}"></textarea></div><div class="row" style="margin-top:10px">${staff && templates.length ? html`<select id="tpl" class="input" style="width:auto;height:36px" aria-label="رد جاهز"><option value="">ردود جاهزة</option>${templates.map((x) => html`<option value="${x.id}">${x.name}</option>`)}</select>` : ''}${staff ? html`<label class="switch"><input type="checkbox" id="internal"><i></i><span class="small">ملاحظة داخلية</span></label>` : ''}<button class="btn btn-primary" data-act="send" style="margin-inline-start:auto">${UI.icon('send')} إرسال</button></div></div>` : ''}` })}
        </div>
        <div class="stack">
          ${UI.panel({ title: 'اتفاقية الخدمة', icon: 'clock', body: html`<div id="dial">${slaDial(t)}</div><dl class="kv mt"><dt>الموعد النهائي</dt><dd>${fmtDateTime(t.dueAt)}</dd><dt>أول استجابة</dt><dd>${t.firstResponseAt ? fmtDuration(t.firstResponseAt - t.createdAt) : 'لم تتم بعد'}</dd>${t.resolvedAt ? html`<dt>تاريخ الحل</dt><dd>${fmtDateTime(t.resolvedAt)}</dd>` : ''}</dl>` })}
          ${UI.panel({ title: 'التفاصيل', icon: 'info', body: html`<div class="row" style="flex-wrap:nowrap;margin-bottom:14px">${UI.avatar(req, 'av-lg')}<div><b>${Data.userName(t.requesterId)}</b><div class="t-sub">${Data.nameOf('departments', t.departmentId)}${t.unitPath ? ` ← ${t.unitPath}` : ''}</div></div></div><dl class="kv"><dt>${UI.icon('tag')} الفئة</dt><dd>${c.name}</dd><dt>${UI.icon('layers')} الموضع</dt><dd>${[Data.nameOf('departments', t.departmentId, ''), t.unitPath].filter(Boolean).join(' ← ') || t.location || '—'}</dd><dt>${UI.icon('phone')} التواصل</dt><dd><span class="ltr">${t.contact || '—'}</span></dd>${TINK.rows(t)}<dt>${UI.icon('calendar')} الإنشاء</dt><dd>${fmtDateTime(t.createdAt)}</dd><dt>${UI.icon('refresh')} آخر تحديث</dt><dd>${timeAgo(t.updatedAt)}</dd>${t.resolveMethod ? html`<dt>${UI.icon('tools')} طريقة الحل</dt><dd>${RESOLVE_LABEL[t.resolveMethod] || t.resolveMethod}</dd>` : ''}${t.rating ? html`<dt>${UI.icon('star')} التقييم</dt><dd>${UI.stars(t.rating)}${t.ratingComment ? html`<div class="t-sub">${t.ratingComment}</div>` : ''}</dd>` : ''}</dl>` })}
          ${staff && VAULT.on() && VAULT.canRead() ? html`<div data-tknotes="${t.id}"></div>` : ''}
          ${staff ? UI.panel({ title: 'الإسناد والأولوية', icon: 'user-plus', body: html`<div class="stack" style="gap:12px"><div class="row" style="flex-wrap:nowrap">${t.assigneeId ? html`${UI.avatar(t.assigneeId, 'av-lg')}<div><b>${Data.userName(t.assigneeId)}</b><div class="t-sub">الفني المسؤول</div></div>` : html`<span class="faint">لم يُسند إلى فني بعد</span>`}</div>${mgr && OPEN.includes(t.status) ? html`${UI.field({ name: 'assign', label: 'إسناد إلى', type: 'select', options: UI.userOpts(['technician', 'support_manager', 'supervisor']) }, t.assigneeId)}${UI.field({ name: 'prio', label: 'الأولوية', type: 'select', placeholder: false, options: Object.entries(PRIORITY).map(([k, p]) => ({ value: k, label: p.label })) }, t.priority)}` : ''}</div>` }) : ''}
          ${staff ? Pages.ticketFlow(t) : ''}
          ${Pages.categoryFormBar(t.categoryId) ? UI.panel({ title: 'استمارة الفئة', icon: 'file', body: Pages.categoryFormBar(t.categoryId) }) : ''}
          ${Pages.cardPanel(t)}
          ${Pages.eFormPanel(t)}
          ${staff ? await Pages.ticketParts(t) : ''}
        </div>
      </div>`);
    Pages.ticketNotes(view, t).catch(() => {});
    const assign = $('[name="assign"]', view), prio = $('[name="prio"]', view), tpl = $('#tpl', view);
    if (assign) assign.onchange = () => assign.value && run(() => Data.tickets.assign(id, assign.value), 'تم إسناد البلاغ');
    if (prio) prio.onchange = () => run(() => Data.tickets.setPriority(id, prio.value), 'تم تغيير الأولوية');
    if (tpl) tpl.onchange = () => { const x = templates.find((y) => y.id === tpl.value); if (x) { const box = $('#cmt', view); box.value = (box.value ? box.value + '\n' : '') + x.body; box.focus(); } tpl.value = ''; };
    UI.hydrate(view);
    if (staff) Pages.paintLive(view, t);
    /* يُعدّ مقروءاً حين يكون البلاغ مفتوحاً أمام صاحبه فعلاً، لا في تبويب مخفي وصله فيه الرد */
    if (nk && !document.hidden) NoteSeen.mark(t);
  };
  if (staff) { const liveT = setInterval(() => { if (ctx.alive() && t) Pages.paintLive(view, t); }, 20000); ctx.onCleanup(() => clearInterval(liveT)); }
  const run = async (fn, msg) => { try { await fn(); if (msg) UI.toast(msg); } catch (ex) { UI.error(ex); } };
  const textModal = (title, icon, label, required, okLabel, kind = 'primary', tplList = []) => UI.modal({ title, icon, body: html`${tplList.length ? html`<div class="quick-chips" style="margin-bottom:10px">${tplList.map((x) => html`<button type="button" class="qchip" data-tpl="${x.body}">${x.name}</button>`)}</div>` : ''}${UI.field({ name: 'text', label, type: 'textarea', rows: 4, required })}`, onMount: (form) => UI.on(form, 'click', '[data-tpl]', (e, b) => { form.querySelector('textarea').value = b.dataset.tpl; }), actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: okLabel, kind, submit: true, handler: (form) => { const v = form.querySelector('textarea').value.trim(); if (required && !v) throw new AppError('هذا الحقل مطلوب'); return { text: v }; } }] });
  UI.on(view, 'click', '[data-act]', async (e, el) => {
    const a = el.dataset.act;
    if (a === 'claim') return run(() => Data.tickets.claim(id), 'استلمت البلاغ، بالتوفيق!');
    if (a === 'takeover') { await Pages.takeoverFlow(id, run); return; }
    if (a === 'handover') { await Pages.handoverModal(id); return; }
    if (a === 'hoclear') { if (await UI.confirm('إزالة ملاحظة التسليم؟', { ok: 'إزالة' })) run(() => Data.tickets.handover(id, '', false), 'أُزيلت ملاحظة التسليم'); return; }
    if (a === 'start') return run(() => Data.tickets.setStatus(id, 'in_progress'), 'بدأ العمل على البلاغ');
    if (a === 'wait') { const r = await Pages.holdModal(); if (r) run(() => Data.tickets.setStatus(id, 'waiting', r.text), 'تم تعليق البلاغ'); return; }
    if (a === 'resolve') { const r = await Pages.resolveModal(t, templates); if (r) { await run(async () => { await Data.tickets.setStatus(id, 'resolved', r.text); if (r.method) await Data.tickets.mutate(id, (x) => { x.resolveMethod = r.method; return []; }); }, r.kept ? 'تم تسجيل الحل وحُفظ كرد جاهز' : 'تم تسجيل الحل وإشعار المستفيد'); UI.sound('success'); } return; }
    if (a === 'close') return run(() => Data.tickets.setStatus(id, 'closed'), 'تم إغلاق البلاغ');
    if (a === 'reopen' || a === 'notfixed') { const r = await textModal(a === 'notfixed' ? 'المشكلة لم تُحل' : 'إعادة فتح البلاغ', 'undo', 'ما الذي ما زال لا يعمل؟', a === 'notfixed', 'إعادة الفتح', 'danger'); if (r) run(() => Data.tickets.setStatus(id, t.assigneeId ? 'in_progress' : 'new', r.text), 'أُعيد فتح البلاغ'); return; }
    if (a === 'cancel') { if (await UI.confirm('هل تريد إلغاء هذا البلاغ؟ يمكن للفنيين إعادة فتحه لاحقاً.', { ok: 'إلغاء البلاغ', danger: true })) run(() => Data.tickets.setStatus(id, 'cancelled'), 'تم إلغاء البلاغ'); return; }
    if (a === 'rate') return Pages.rateModal(id);
    if (a === 'confirmfix') return run(() => Data.tickets.confirmFix(id), 'شكراً لتأكيدك، أُغلق البلاغ');
    if (a === 'replynote') { const box = $('#cmt', view); if (box) { box.scrollIntoView({ block: 'center', behavior: UI.reduced() ? 'auto' : 'smooth' }); box.focus(); } return; }
    if (a === 'seenote') { const el = $('#tlNote', view); if (el) { el.scrollIntoView({ block: 'center', behavior: UI.reduced() ? 'auto' : 'smooth' }); el.classList.remove('flash'); void el.offsetWidth; el.classList.add('flash'); } return; }
    if (a === 'send') { const box = $('#cmt', view), internal = $('#internal', view); if (!box.value.trim()) { box.focus(); return; } UI.busy(el, true); try { await Data.tickets.comment(id, box.value, !!(internal && internal.checked)); UI.toast('تم إرسال الرد'); } catch (ex) { UI.error(ex); UI.busy(el, false); } return; }
    if (a === 'attach') { const fl = (await UI.pickFiles({ accept: 'image/*,.pdf,.doc,.docx,.xls,.xlsx,.txt' })).filter((f) => f.size <= 10 * 1048576).slice(0, 5); if (fl.length) run(() => Data.tickets.addAttachments(id, fl), 'تمت إضافة المرفقات'); return; }
    if (a === 'parts') { const mv = await Pages.moveModal({ type: 'issue', ref: t.number }); if (mv) { const it = await DB.get('items', mv.itemId); run(() => Data.tickets.comment(id, `تم صرف ${mv.qty} ${it ? it.unit : ''} من «${it ? it.name : ''}» لهذا البلاغ.`, true)); } return; }
    if (a === 'print') { const evs = (await Data.tickets.events(id)).filter((x) => !x.internal && x.text); UI.print(html`<h2>بلاغ رقم ${t.number}</h2><table><tr><th>العنوان</th><td>${t.title}</td><th>الحالة</th><td>${STATUS[t.status].label}</td></tr><tr><th>مقدم البلاغ</th><td>${Data.userName(t.requesterId)}</td><th>القسم</th><td>${Data.nameOf('departments', t.departmentId)}</td></tr><tr><th>الفئة</th><td>${Data.nameOf('categories', t.categoryId)}</td><th>الأولوية</th><td>${PRIORITY[t.priority].label}</td></tr><tr><th>الفني</th><td>${t.assigneeId ? Data.userName(t.assigneeId) : '—'}</td><th>تاريخ الإنشاء</th><td>${fmtDateTime(t.createdAt)}</td></tr><tr><th>الوصف</th><td colspan="3">${t.description || '—'}</td></tr></table><h2>السجل</h2><table><tr><th>التاريخ</th><th>بواسطة</th><th>النص</th></tr>${evs.map((x) => html`<tr><td>${fmtDateTime(x.at)}</td><td>${Data.userName(x.userId)}</td><td>${x.text}</td></tr>`)}</table>${UI.signBlock([{ title: 'مقدم البلاغ', userId: t.requesterId }, { title: 'الفني المختص', userId: t.assigneeId }])}`, `بلاغ ${t.number}`); }
  });
  window.__ticketCtx = { number: t.number, name: Data.userName(t.requesterId), category: Data.nameOf('categories', t.categoryId, '') };
  UI.on(view, 'click', '[data-act="printcards"]', () => Pages.printAccessCards(t));
  UI.on(view, 'click', '[data-issue]', async (e, el) => { const it = await DB.get('items', el.dataset.issue); const mv = await Pages.moveModal({ type: 'issue', itemId: el.dataset.issue, ref: t.number, departmentId: t.departmentId, qty: el.dataset.qty }); if (mv && it) run(() => Data.tickets.comment(id, `صُرف من المخزن: ${fmtNum(mv.qty)} ${it.unit || ''} من «${it.name}» لهذا البلاغ.`, true), 'تم الصرف وتسجيله في البلاغ'); });
  UI.on(view, 'click', '[data-att]', (e, el) => {
    const a = atts.find((x) => x.id === el.dataset.att); if (!a || !a.blob) return;
    if (a._url) UI.modal({ title: a.name, icon: 'eye', size: 'lg', body: html`<div class="lightbox"><img src="${a._url}" alt="${a.name}"></div>`, actions: [{ label: 'تنزيل', icon: 'download', kind: 'soft', handler: () => { downloadBlob(a.blob, a.name); return false; } }, { label: 'إغلاق', kind: 'primary', value: null }] });
    else downloadBlob(a.blob, a.name);
  });
  await draw();
  ctx.onCleanup(Bus.on('tickets', debounce((e) => { if (ctx.alive() && (!e.detail || !e.detail.id || e.detail.id === id)) draw(); }, 250)));
  const tick = setInterval(() => { const d = $('#dial', view); if (d && OPEN.includes(t.status)) d.innerHTML = String(slaDial(t)); }, 30000); ctx.onCleanup(() => clearInterval(tick));
};

/* ── المخازن والعهد ─────────────────────────────────────────── */
/* أيقونة الصنف: رسمة مجلده، فإن لم تكن (صندوق) تُستنتج من نوعه (حاسب، شاشة، طابعة…) أو من أقرب مجلد أعلى له رسمة */
const itemIllu = (it) => { const v = (Data.c.itemCategories.get(it && it.categoryId) || {}).illustration; if (v && v !== 'box') return v; try { return it ? cmIllu(it) : 'box'; } catch (_) { return 'box'; } };
const MOVE_TONE = { receive: 'teal', issue: 'amber', transfer_out: 'violet', transfer_in: 'sky', adjust: 'slate', loan_out: 'pink', loan_return: 'green' };
Data.inv.summary = async () => {
  let units = 0, low = 0, out = 0, skus = 0, overdue = 0, active = 0; const t = now();
  /* «نفدت» و«منخفضة» لما له حد تنبيه فقط: النموذج بلا رصيد بعد، أو الصنف الموزّع كله على الإدارات، ليس نقصاً يُنبَّه عليه */
  await DB.each('items', {}, (i) => { if (i.archived) return; skus++; units += Math.max(0, i.onHand || 0); const oh = i.onHand || 0; if (i.minQty > 0 && oh <= 0) out++; else if (i.minQty > 0 && oh <= i.minQty) low++; });
  await DB.each('loans', { index: 'status', range: KR('active') }, (l) => { active++; if (l.dueAt && l.dueAt < t) overdue++; });
  return { skus, units, low, out, active, overdue };
};
UI.meter = (it) => {
  const cap = Math.max(it.minQty * 3, it.onHand, 1), p = clamp(it.onHand / cap, 0, 1), state = it.onHand <= 0 ? 'out' : it.minQty > 0 && it.onHand <= it.minQty ? 'low' : 'ok', tone = { out: 'red', low: 'amber', ok: 'teal' }[state];
  return html`<span class="meter tone-${tone} ${state !== 'ok' ? 'low' : ''}" title="${state === 'out' ? 'نفد الرصيد' : state === 'low' ? 'رصيد منخفض' : 'رصيد جيد'}"><span><i style="width:${Math.max(4, Math.round(p * 100))}%"></i></span>${fmtNum(it.onHand)} <small>${it.unit || ''}</small></span>`;
};

Pages.itemPicker = () => html`<div class="field picker"><label>الصنف<em>*</em></label><div class="search-box">${UI.icon('search')}<input type="search" data-picker placeholder="ابحث باسم الصنف أو رمزه" autocomplete="off"></div><input type="hidden" name="itemId"><div class="picker-list" data-picker-list></div></div>`;
Pages.bindPicker = (form, onPick) => {
  const input = form.querySelector('[data-picker]'); if (!input) return;
  const list = form.querySelector('[data-picker-list]'), hidden = form.querySelector('[name="itemId"]');
  const search = debounce(async () => { const { rows } = await Data.inv.items({ q: input.value.trim(), limit: 6 }); list.innerHTML = String(html`${rows.map((i) => html`<button type="button" class="picker-item" data-id="${i.id}" data-name="${i.name}">${UI.illu(itemIllu(i))}<span><b>${i.name}</b><small>${i.sku} — الرصيد ${fmtNum(i.onHand)} ${i.unit}</small></span></button>`)}${rows.length ? '' : html`<p class="faint small">لا توجد أصناف مطابقة</p>`}`); }, 200);
  input.addEventListener('input', () => { hidden.value = ''; search(); }); input.addEventListener('focus', search);
  list.addEventListener('click', (e) => { const b = e.target.closest('.picker-item'); if (!b) return; hidden.value = b.dataset.id; input.value = b.dataset.name; list.innerHTML = ''; if (onPick) onPick(b.dataset.id); });
};
Pages.returnModal = (loan) => UI.modal({
  title: `إرجاع العهدة ${loan.number}`, icon: 'undo', size: 'sm',
  body: html`<p class="muted" style="margin-bottom:12px">${loan.itemName} — لدى ${loan.borrower}. المتبقي: <b>${fmtNum(loan.qty - loan.returnedQty)}</b></p>${UI.fields([{ name: 'qty', label: 'الكمية المرتجعة', type: 'number', min: 1, value: loan.qty - loan.returnedQty, wide: true }, { name: 'note', label: 'حالة الصنف عند الإرجاع', type: 'textarea', rows: 2, wide: true }])}`,
  actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تأكيد الإرجاع', kind: 'ok', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); const l = await Data.inv.returnLoan(loan.id, v.qty, v.note); UI.toast(l.status === 'returned' ? 'أُغلقت العهدة بالكامل' : 'تم تسجيل الإرجاع الجزئي'); UI.sound('success'); return l; } }]
});
Pages.invActions = () => html`${Auth.can('inventory.move') ? html`<button class="btn btn-ok" data-move="receive">${UI.icon('download')} استلام</button><button class="btn" data-move="issue">${UI.icon('upload')} صرف</button><button class="btn" data-move="transfer">${UI.icon('swap')} تحويل</button><button class="btn btn-soft" data-act="lend">${UI.icon('clipboard')} تسليم عهدة</button>` : ''}${Auth.can('inventory.manage') ? html`<button class="btn btn-primary" data-act="newitem">${UI.icon('plus')} صنف جديد</button>` : ''}`;
Pages.bindInv = (ctx, refresh) => {
  UI.on(ctx.view, 'click', '[data-move]', async (e, el) => { if (await Pages.moveModal({ type: el.dataset.move, itemId: el.dataset.item, departmentId: el.dataset.dept })) refresh(); });
  UI.on(ctx.view, 'click', '[data-act="lend"]', async (e, el) => { if (await Pages.loanModal(el.dataset.item)) refresh(); });
  UI.on(ctx.view, 'click', 'tr[data-href]', (e, el) => { if (!e.target.closest('a,button')) Router.go(el.dataset.href.slice(1)); });
  UI.on(ctx.view, 'click', '[data-act="newitem"]', async (e, el) => { const it = await Pages.itemModal(null, { categoryId: el.dataset.cat || '', brand: el.dataset.brand || '' }); if (it) Router.go(`/inventory/items/${it.id}`); });
  ctx.onCleanup(Bus.on('inventory', debounce(() => { if (ctx.alive()) refresh(); }, 600)));
};

/* ── نظرة عامة على المخازن ── */
Pages.inventory = async (ctx) => {
  const draw = async () => {
    const days = 30, from = startOfDay() - (days - 1) * DAY, whs = Data.list('warehouses'), icats = Data.list('itemCategories');
    const [s, whStock, catCounts, recent, loans, deptList] = await Promise.all([Data.inv.summary(), Promise.all(whs.map((w) => DB.getAll('stock', 'warehouseId', KR(w.id)))), Promise.all(icats.map((c) => DB.count('items', 'categoryId', KR(c.id)))), Data.inv.movements({ limit: 7 }), DB.getAll('loans', 'status', KR('active')), Data.dept.all()]);
    const deptUnits = deptList.reduce((a, d) => a + d.units, 0);
    const inD = new Array(days).fill(0), outD = new Array(days).fill(0), issued = new Map(), lowItems = [];
    await DB.each('movements', { index: 'at', range: KR(from, now()) }, (m) => { const i = Math.floor((startOfDay(m.at) - from) / DAY); if (i < 0 || i >= days || m.type === 'adjust') return; if (m.delta > 0) inD[i] += m.qty; else outD[i] += m.qty; if (m.type === 'issue' || m.type === 'loan_out') issued.set(m.itemId, (issued.get(m.itemId) || 0) + m.qty); });
    await DB.each('items', {}, (i) => { if (i.onHand <= 0 || (i.minQty > 0 && i.onHand <= i.minQty)) lowItems.push(i); });
    lowItems.sort((a, b) => a.onHand / Math.max(1, a.minQty) - b.onHand / Math.max(1, b.minQty));
    const top = await Promise.all([...issued].sort((a, b) => b[1] - a[1]).slice(0, 6).map(async ([id, v], i) => { const it = await DB.get('items', id); return { label: it ? it.name : 'صنف محذوف', value: v, tone: TONES[i % TONES.length], lead: String(UI.illu(itemIllu(it))) }; }));
    const due = loans.filter((l) => l.dueAt).sort((a, b) => a.dueAt - b.dueAt).slice(0, 6), totalUnits = Math.max(1, s.units);
    if (!ctx.alive()) return;
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ title: 'المخازن والعهد', sub: 'أرصدة لحظية، حركات موثقة، وعهد لا تضيع', illu: 'box', actions: Pages.invActions() })}
      <div class="kpis">
        ${UI.kpi({ label: 'الأصناف المسجلة', icon: 'box', tone: 'sky', value: s.skus })}
        ${UI.kpi({ label: 'إجمالي الوحدات', icon: 'layers', tone: 'teal', value: s.units, spark: inD.map((v, i) => v - outD[i]).slice(-14).map((v, i, a) => a.slice(0, i + 1).reduce((x, y) => x + y, 0) + 1000) })}
        ${UI.kpi({ label: 'رصيد منخفض', icon: 'alert', tone: 'amber', value: s.low })}
        ${UI.kpi({ label: 'نفد رصيدها', icon: 'x', tone: 'red', value: s.out })}
        ${UI.kpi({ label: 'بعهدة الإدارات', icon: 'building', tone: 'violet', value: deptUnits })}
        ${UI.kpi({ label: 'عهد نشطة', icon: 'clipboard', tone: 'violet', value: s.active, foot: s.overdue ? html`<span class="delta bad">${fmtNum(s.overdue)} متأخرة</span>` : html`<span class="delta good">لا تأخير</span>` })}
      </div>
      <div class="grid g-main mt">
        ${UI.panel({ title: 'حركة الوارد والصادر', icon: 'swap', sub: `الكميات خلال آخر ${days} يوماً`, body: UI.chart.area([{ name: 'وارد', tone: 'teal', values: inD }, { name: 'صادر', tone: 'amber', values: outD }], Stats.dayLabels(from, days), { height: 210 }) })}
        ${UI.panel({ title: 'صحة الأرصدة', icon: 'shield', body: UI.chart.donut([{ label: 'سليمة', value: Math.max(0, s.skus - s.low - s.out), tone: 'teal' }, { label: 'منخفضة', value: s.low, tone: 'amber' }, { label: 'نفدت', value: s.out, tone: 'red' }], { label: 'صنف', size: 160 }) })}
      </div>
      <h2 class="mt" style="font-size:16px;margin-bottom:12px;display:flex;gap:8px;align-items:center">${UI.icon('warehouse')} المخازن</h2>
      <div class="grid g-3 stagger">${whs.map((w, i) => { const rows = whStock[i], units = rows.reduce((a, r) => a + Math.max(0, r.qty), 0), items = rows.filter((r) => r.qty > 0).length; return html`<a class="wh" href="#/inventory/items?wh=${w.id}"><div class="wh-head">${UI.illu(i % 2 ? 'box' : 'network')}<div class="grow"><b>${w.name}</b><div class="t-sub">${w.location || 'بدون موقع محدد'}${w.keeper ? ` — ${w.keeper}` : ''}</div></div></div><div class="row" style="justify-content:space-between"><span class="faint small">متوفر: ${arCount(items, AR.item)}</span><b style="font-family:var(--f-display);font-size:20px">${fmtNum(units)}</b></div><div class="shelf tone-${TONES[i % TONES.length]}"><i style="width:${Math.max(2, (units / totalUnits) * 100).toFixed(1)}%"></i></div></a>`; })}<a class="wh" href="#/inventory/departments"><div class="wh-head">${UI.illu('network')}<div class="grow"><b>عهدة الإدارات</b><div class="t-sub">ما بحوزة الإدارات من أصناف مصروفة</div></div></div><div class="row" style="justify-content:space-between"><span class="faint small">${fmtNum(deptList.length)} إدارة</span><b style="font-family:var(--f-display);font-size:20px">${fmtNum(deptUnits)}</b></div><div class="shelf tone-violet"><i style="width:${Math.min(100, Math.max(3, (deptUnits / totalUnits) * 100)).toFixed(1)}%"></i></div></a></div>
      ${await Pages.forecastPanel()}
      ${UI.panel({ title: 'التصنيفات', icon: 'grid', cls: 'mt', body: html`<div class="tiles sm">${icats.map((c, i) => html`<a class="tile tilt" href="#/inventory/items?cat=${c.id}">${catCounts[i] ? html`<span class="count">${fmtNum(catCounts[i])}</span>` : ''}${UI.illu(c.illustration)}<b>${c.name}</b></a>`)}</div>` })}
      <div class="grid g-3 mt">
        ${UI.panel({ title: 'تحتاج إلى توريد', icon: 'alert', tools: html`<a class="btn btn-ghost btn-sm" href="#/inventory/items?low=1">الكل ${UI.icon('chevron-left')}</a>`, body: lowItems.length ? html`<div class="list">${lowItems.slice(0, 6).map((i) => html`<a class="list-row" href="#/inventory/items/${i.id}">${UI.illu(itemIllu(i), 'mini')}<div class="grow ellipsis"><b>${i.name}</b><div class="t-sub">الحد الأدنى ${fmtNum(i.minQty)}</div></div>${UI.meter(i)}</a>`)}</div>` : UI.empty({ illu: 'box', title: 'كل الأرصدة سليمة', text: 'لا توجد أصناف تحت الحد الأدنى.' }) })}
        ${UI.panel({ title: 'الأكثر صرفاً', icon: 'upload', sub: `آخر ${days} يوماً`, body: UI.chart.hbars(top) })}
        ${UI.panel({ title: 'عهد يقترب موعدها', icon: 'clipboard', tools: html`<a class="btn btn-ghost btn-sm" href="#/inventory/loans">الكل ${UI.icon('chevron-left')}</a>`, body: due.length ? html`<div class="list">${due.map((l) => html`<div class="list-row"><span class="avatar av-sm" style="--h:${(l.borrower.length * 37) % 360}">${l.borrower.trim()[0] || '؟'}</span><div class="grow ellipsis"><b>${l.itemName}</b><div class="t-sub">${l.borrower}</div></div>${l.dueAt < now() ? UI.chip('red', `متأخرة ${fmtDuration(now() - l.dueAt)}`, 'alert') : UI.chip(l.dueAt - now() < 3 * DAY ? 'amber' : 'teal', `بعد ${fmtDuration(l.dueAt - now())}`, 'clock')}</div>`)}</div>` : UI.empty({ illu: 'card', title: 'لا توجد عهد مؤقتة', text: 'العهد ذات مواعيد الإرجاع ستظهر هنا.' }) })}
      </div>
      ${UI.panel({ title: 'آخر الحركات', icon: 'pulse', cls: 'mt', tools: html`<a class="btn btn-ghost btn-sm" href="#/inventory/movements">السجل الكامل ${UI.icon('chevron-left')}</a>`, flush: true, body: await Pages.moveTable(recent.rows) })}`);
    UI.hydrate(ctx.view); UI.tilt(ctx.view);
  };
  Pages.bindInv(ctx, draw);
  await draw();
};
Pages.moveTable = async (rows) => {
  if (!rows.length) return html`<div class="panel-body">${UI.empty({ illu: 'box', title: 'لا توجد حركات بعد', text: 'ستظهر هنا عمليات الاستلام والصرف والتحويل.' })}</div>`;
  const items = new Map((await Promise.all([...new Set(rows.map((m) => m.itemId))].map((id) => DB.get('items', id)))).filter(Boolean).map((i) => [i.id, i]));
  return html`<div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>الحركة</th><th>الصنف</th><th>المخزن</th><th>الكمية</th><th>الرصيد بعدها</th><th>الجهة / المرجع</th><th>بواسطة</th></tr></thead><tbody class="stagger">${rows.map((m) => { const it = items.get(m.itemId); return html`<tr${it ? raw(` data-href="#/inventory/items/${esc(it.id)}"`) : ''}><td class="nowrap faint">${fmtDateTime(m.at)}</td><td>${UI.chip(MOVE_TONE[m.type] || 'slate', (MOVES[m.type] || {}).label || m.type)}</td><td><div class="t-title" style="min-width:180px">${UI.illu(itemIllu(it))}<div class="ellipsis">${it ? it.name : 'صنف محذوف'}</div></div></td><td>${Data.nameOf('warehouses', m.warehouseId)}</td><td class="nowrap" style="font-weight:700;color:rgb(var(${m.delta >= 0 ? '--teal-ink' : '--red-ink'}))"><span class="ltr">${m.delta > 0 ? '+' : ''}${fmtNum(m.delta)}</span></td><td>${m.balance == null ? '—' : fmtNum(m.balance)}</td><td class="small">${m.party || m.departmentId || m.ref ? html`${[m.party, Data.nameOf('departments', m.departmentId, '')].filter(Boolean).join(' — ')}${m.ref ? html`<div class="t-num">${m.ref}</div>` : ''}` : '—'}</td><td class="small">${m.userId ? Data.userName(m.userId) : 'ترحيل'}</td></tr>`; })}</tbody></table></div>`;
};

/* ── الأصناف ── */
Pages.items = async (ctx) => {
  const q = ctx.query, st = { q: q.q || '', categoryId: q.cat || '', wh: q.wh || '', low: q.low === '1', view: localStorage.getItem('sq_iview') || 'grid', offset: 0, limit: 24 };
  ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'الأصناف والأرصدة', sub: 'ابحث عن أي صنف واعرف رصيده في كل مخزن', illu: 'box', actions: html`${Pages.invActions()}${Auth.can('inventory.manage') ? html`<button class="btn btn-ghost" data-act="import">${UI.icon('upload')} استيراد</button>` : ''}<button class="btn btn-ghost" data-act="export">${UI.icon('download')} تصدير</button>` })}
    <section class="panel"><div class="toolbar"><div class="search-box">${UI.icon('search')}<input id="iq" type="search" placeholder="اسم الصنف أو الرمز أو الرقم التسلسلي" value="${st.q}"></div>
      <select id="icat" aria-label="التصنيف"><option value="">كل التصنيفات</option>${UI.opts('itemCategories').map((o) => html`<option value="${o.value}"${o.value === st.categoryId ? raw(' selected') : ''}>${o.label}</option>`)}</select>
      <select id="iwh" aria-label="المخزن"><option value="">كل المخازن</option>${UI.opts('warehouses').map((o) => html`<option value="${o.value}"${o.value === st.wh ? raw(' selected') : ''}>${o.label}</option>`)}</select>
      <label class="switch"><input type="checkbox" id="ilow"${st.low ? raw(' checked') : ''}><i></i><span class="small">المنخفضة فقط</span></label>
      <div class="seg" style="margin-inline-start:auto"><label><input type="radio" name="iview" value="grid"${st.view === 'grid' ? raw(' checked') : ''}><span>${UI.icon('grid')}</span></label><label><input type="radio" name="iview" value="table"${st.view === 'table' ? raw(' checked') : ''}><span>${UI.icon('menu')}</span></label></div>
    </div><div id="ibody"></div></section>`);
  const view = ctx.view, body = $('#ibody', view);
  const fetch = async (all) => {
    const lim = all ? 1e6 : st.limit, off = all ? 0 : st.offset;
    if (!st.wh) return Data.inv.items({ q: st.q, categoryId: st.categoryId, low: st.low, offset: off, limit: lim });
    const ids = new Set((await DB.getAll('stock', 'warehouseId', KR(st.wh))).filter((s) => s.qty > 0).map((s) => s.itemId)), qn = normalizeAr(st.q), rows = [];
    await DB.each('items', { index: 'updatedAt', dir: 'prev' }, (i) => { if (ids.has(i.id) && (!st.categoryId || i.categoryId === st.categoryId) && (!qn || String(i.search).includes(qn)) && (!st.low || i.onHand <= i.minQty)) rows.push(i); });
    return { rows: rows.slice(off, off + lim), hasMore: rows.length > off + lim };
  };
  const load = async () => {
    const res = await fetch(); if (!ctx.alive()) return;
    if (!res.rows.length) { body.innerHTML = String(UI.empty({ illu: 'box', title: 'لا توجد أصناف مطابقة', text: 'غيّر البحث أو أضف صنفاً جديداً.', action: Auth.can('inventory.manage') ? html`<button class="btn btn-primary" data-act="newitem">${UI.icon('plus')} صنف جديد</button>` : '' })); return; }
    const mv = Auth.can('inventory.move');
    body.innerHTML = String(html`${st.view === 'grid' ? html`<div class="panel-body"><div class="tiles stagger" style="grid-template-columns:repeat(auto-fill,minmax(210px,1fr))">${res.rows.map((i) => html`<div class="tile tilt${i.archived ? ' x-off' : ''}" title="${i.archived ? 'صنف مؤرشف' : ''}" data-href="#/inventory/items/${i.id}" style="align-items:stretch;text-align:start;cursor:pointer">${UI.illu(itemIllu(i))}<b class="ellipsis">${i.name}</b><small class="ltr" style="text-align:start">${i.sku}</small><div class="row" style="justify-content:space-between;margin-top:6px;transform:translateZ(18px)">${UI.meter(i)}${mv ? html`<span class="row" style="gap:4px"><button class="icon-btn" style="width:32px;height:32px" data-move="receive" data-item="${i.id}" title="استلام" aria-label="استلام">${UI.icon('plus')}</button><button class="icon-btn" style="width:32px;height:32px" data-move="issue" data-item="${i.id}" title="صرف" aria-label="صرف">${UI.icon('upload')}</button><button class="icon-btn" style="width:32px;height:32px" data-cart-add="${i.id}" title="إضافة إلى السلة" aria-label="إضافة إلى السلة">${UI.icon('cart')}</button></span>` : ''}</div></div>`)}</div></div>` : html`<div class="table-wrap"><table class="table"><thead><tr><th>الصنف</th><th>التصنيف</th><th>الرصيد</th><th>الحد الأدنى</th><th>الشركة / الموديل</th><th>آخر تحديث</th></tr></thead><tbody class="stagger">${res.rows.map((i) => html`<tr data-href="#/inventory/items/${i.id}"${i.archived ? raw(' class="tr-off" title="صنف مؤرشف"') : ''}><td><div class="t-title">${UI.illu(itemIllu(i))}<div><div>${i.name}</div><div class="t-sub ltr" style="text-align:start">${i.sku}</div></div></div></td><td>${Data.nameOf('itemCategories', i.categoryId)}</td><td>${UI.meter(i)}</td><td>${fmtNum(i.minQty)}</td><td class="small">${[i.brand, i.model].filter(Boolean).join(' ') || '—'}</td><td class="faint nowrap">${timeAgo(i.updatedAt)}</td></tr>`)}</tbody></table></div>`}${UI.pager({ offset: st.offset, limit: st.limit, count: res.rows.length, hasMore: res.hasMore })}`);
    UI.hydrate(body);
  };
  const reset = () => { st.offset = 0; load(); };
  $('#iq', view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); reset(); }, 300));
  $('#icat', view).onchange = (e) => { st.categoryId = e.target.value; reset(); };
  $('#iwh', view).onchange = (e) => { st.wh = e.target.value; reset(); };
  $('#ilow', view).onchange = (e) => { st.low = e.target.checked; reset(); };
  UI.on(view, 'change', 'input[name="iview"]', (e, el) => { st.view = el.value; localStorage.setItem('sq_iview', el.value); load(); });
  UI.on(view, 'click', '[data-page]', (e, el) => { st.offset = Math.max(0, st.offset + (el.dataset.page === 'next' ? st.limit : -st.limit)); load(); });
  UI.on(view, 'click', '.tile[data-href]', (e, el) => { if (!e.target.closest('button,a')) Router.go(el.dataset.href.slice(1)); });
  UI.on(view, 'click', '[data-act="export"]', async () => { const { rows } = await fetch(true); downloadBlob(new Blob([toCSV(rows, [{ label: 'sku', key: 'sku' }, { label: 'name', key: 'name' }, { label: 'category', value: (i) => Data.nameOf('itemCategories', i.categoryId, '') }, { label: 'unit', key: 'unit' }, { label: 'minQty', key: 'minQty' }, { label: 'onHand', key: 'onHand' }, { label: 'brand', key: 'brand' }, { label: 'model', key: 'model' }, { label: 'serial', key: 'serial' }])], { type: 'text/csv;charset=utf-8' }), `الأصناف-${dateInput(now())}.csv`); UI.toast(`تم تصدير ${arCount(rows.length, AR.item)}`); });
  UI.on(view, 'click', '[data-act="import"]', async () => {
    const ok = await UI.modal({ title: 'استيراد أصناف من ملف CSV', icon: 'upload', body: html`<p class="muted" style="line-height:1.9">الأعمدة المدعومة: <span class="ltr">name, sku, category, unit, minQty, qty, warehouse, brand, model, serial</span>. يمكن تصدير الأصناف الحالية واستخدام الملف قالباً.</p>`, actions: [{ label: 'إلغاء', kind: 'ghost', value: false }, { label: 'اختيار الملف', kind: 'primary', icon: 'upload', value: true, submit: true }] });
    if (!ok) return;
    const [file] = await UI.pickFiles({ accept: '.xlsx,.csv,text/csv', multiple: false }); if (!file) return;
    try {
      const rows = /\.xlsx$/i.test(file.name) ? await XL.objRows(file) : parseCSV(await readText(file)), catBy = new Map(Data.list('itemCategories').map((c) => [normalizeAr(c.name), c.id])), whBy = new Map(Data.list('warehouses').map((w) => [normalizeAr(w.name), w.id])), defWh = (Data.list('warehouses')[0] || {}).id; let n = 0, fail = 0;
      for (const r of rows) { try { const it = await Data.inv.saveItem({ name: r.name, sku: r.sku, categoryId: catBy.get(normalizeAr(r.category)) || 'ic_other', unit: r.unit, minQty: r.minQty, brand: r.brand, model: r.model, serial: r.serial }); if (Number(r.qty) > 0) await Data.inv.move({ type: 'receive', itemId: it.id, warehouseId: whBy.get(normalizeAr(r.warehouse)) || defWh, qty: r.qty, note: 'استيراد من ملف' }); n++; } catch (_) { fail++; } }
      UI.toast(`تم استيراد ${fmtNum(n)} صنف${fail ? ` وتعذر ${fmtNum(fail)}` : ''}`, fail ? 'warn' : 'ok'); load();
    } catch (ex) { UI.error(ex); }
  });
  Pages.bindInv(ctx, load);
  await load();
};

/* ── تفاصيل الصنف ── */
Pages.item = async (ctx) => {
  const id = ctx.params.id, st = { offset: 0, limit: 15 };
  const draw = async () => {
    const it = await DB.get('items', id);
    if (!it) { ctx.view.innerHTML = String(UI.empty({ illu: 'box', title: 'الصنف غير موجود', action: html`<a class="btn btn-primary" href="#/inventory/items">العودة إلى الأصناف</a>` })); return; }
    const [stock, mv, loans, deptRows, units] = await Promise.all([Data.inv.stockOf(id), Data.inv.movements({ itemId: id, offset: st.offset, limit: st.limit }), DB.getAll('loans', 'itemId', KR(id)), Data.dept.ofItem(id), Data.assets.byItem(id)]);
    /* داخل المخزن تظهر الوحدات الموجودة فيه فقط، وأماكن البقية في البحث العام */
    const allUnits = units.splice(0, units.length); units.push(...allUnits.filter((a) => a.status === 'in_store'));
    const outside = isSerialItem(it) ? allUnits.filter((a) => a.status !== 'in_store' && a.status !== 'retired').length : deptRows.reduce((n, d) => n + (Number(d.qty) || 0), 0) + loans.filter((l) => l.status === 'active').reduce((n, l) => n + (Number(l.qty) - Number(l.returnedQty || 0)), 0);
    const days = 60, from = startOfDay() - (days - 1) * DAY, hist = await DB.getAll('movements', 'item_at', KR([id, from], [id, Infinity]));
    const bal = new Array(days).fill(0); let run = it.onHand, j = hist.length - 1;
    for (let d = days - 1; d >= 0; d--) { bal[d] = run; const dayStart = from + d * DAY; while (j >= 0 && hist[j].at >= dayStart) { run -= hist[j].delta; j--; } }
    const mvOk = Auth.can('inventory.move');
    if (!ctx.alive()) return;
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ crumbs: html`<a href="#/inventory/items">الأصناف</a>${UI.icon('chevron-left')}<span class="ltr">${it.sku}</span>`, title: it.name, illu: itemIllu(it), sub: html`<span class="row" style="gap:8px;margin-top:6px">${UI.chip('sky', Data.nameOf('itemCategories', it.categoryId), 'tag')}${it.brand || it.model ? UI.chip('slate', [it.brand, it.model].filter(Boolean).join(' '), 'box') : ''}${it.serial ? html`<span class="t-num">SN ${it.serial}</span>` : ''}</span>`, actions: html`${mvOk ? html`<button class="btn btn-ok" data-move="receive" data-item="${id}">${UI.icon('download')} استلام</button><button class="btn" data-move="issue" data-item="${id}">${UI.icon('upload')} صرف</button><button class="btn" data-move="transfer" data-item="${id}">${UI.icon('swap')} تحويل</button><button class="btn btn-soft" data-act="lend" data-item="${id}">${UI.icon('clipboard')} عهدة</button>` : ''}${Auth.can('inventory.move') ? UI.cartBtn(id, 'btn') : ''}${Auth.can('inventory.manage') ? html`<button class="btn btn-ghost" data-move="adjust" data-item="${id}">${UI.icon('refresh')} جرد</button><button class="btn btn-ghost" data-fixstock="${id}" title="إنقاص كمية أو وحدات سُجلت بالخطأ">${UI.icon('undo')} تصحيح خطأ</button><button class="icon-btn" data-act="edit" title="تعديل" aria-label="تعديل">${UI.icon('edit')}</button>` : ''}` })}
      <div class="grid g-side">
        <div class="stack">
          ${UI.panel({ title: 'الرصيد عبر الزمن', icon: 'pulse', sub: `آخر ${days} يوماً`, body: UI.chart.area([{ name: 'الرصيد الحالي', tone: 'teal', values: bal }], Stats.dayLabels(from, days), { height: 200, legend: 'last' }) })}
          ${UI.panel({ title: 'سجل الحركات', icon: 'swap', flush: true, body: html`${await Pages.moveTable(mv.rows)}${mv.rows.length ? UI.pager({ offset: st.offset, limit: st.limit, count: mv.rows.length, hasMore: mv.hasMore }) : ''}` })}
        </div>
        <div class="stack">
          ${UI.panel({ title: 'الرصيد الحالي', icon: 'box', body: html`<div class="center"><div style="font:800 54px/1.1 var(--f-display)" data-count="${it.onHand}">0</div><div class="faint">${it.unit}</div><div style="margin-top:12px">${UI.meter(it)}</div>${it.minQty ? html`<p class="small faint" style="margin-top:8px">حد التنبيه: ${fmtNum(it.minQty)} ${it.unit}</p>` : ''}</div>` })}
          ${UI.panel({ title: 'التوزيع على المخازن', icon: 'warehouse', body: stock.some((s) => s.qty) ? UI.chart.hbars(stock.filter((s) => s.qty).map((s, i) => ({ label: Data.nameOf('warehouses', s.warehouseId), value: s.qty, tone: TONES[i % TONES.length] }))) : UI.noData('لا يوجد رصيد في أي مخزن') })}
          ${units.length ? UI.panel({ title: 'الوحدات في المخزن', icon: 'tag', sub: `${fmtNum(units.length)} وحدة متاحة`, tools: html`<button class="btn btn-ghost btn-sm" data-act="labels">${UI.icon('print')} ملصقات</button>`, flush: true, body: html`<div class="table-wrap"><table class="table"><thead><tr><th>الرقم التسلسلي</th><th>الحالة</th><th>الموقع أو الحائز</th></tr></thead><tbody>${units.slice(0, 60).map((a) => html`<tr><td class="t-num"><button type="button" class="link-sn" data-asset="${a.id}" title="التفاصيل الكاملة وسجل الصيانة">${a.serial} ${UI.icon('info')}</button>${a.host ? html`<div class="t-sub ltr">${a.host}</div>` : ''}</td><td>${UI.chip(ASSET_STATUS[a.status].tone, ASSET_STATUS[a.status].label, ASSET_STATUS[a.status].icon)}</td><td class="small">${a.status === 'in_store' ? Data.nameOf('warehouses', a.warehouseId) : a.status === 'issued' ? Data.nameOf('departments', a.departmentId, a.holder || '—') : a.holder || '—'}</td></tr>`)}</tbody></table></div>` }) : ''}
          ${Object.keys(it.specs || {}).length ? UI.panel({ title: 'المواصفات', icon: 'info', body: html`<dl class="kv">${Object.entries(it.specs).filter(([, v2]) => String(v2 || '').trim()).map(([k, v2]) => html`<dt>${specLabel(it.categoryId, k)}</dt><dd>${v2}</dd>`)}</dl>` }) : ''}
          ${outside ? UI.panel({ title: 'خارج المخزن', icon: 'pin', body: html`<p class="muted" style="margin:0 0 10px">${fmtNum(outside)} ${it.unit || 'وحدة'} لدى الإدارات أو مُعارة أو في الصيانة. لا تظهر تفاصيلها داخل المخزن.</p><a class="btn btn-soft btn-sm" href="#/inventory/search?q=${encodeURIComponent(it.model || it.name)}">${UI.icon('search')} أماكنها في البحث العام</a>` }) : ''}
          
          ${it.notes ? UI.panel({ title: 'ملاحظات', icon: 'info', body: html`<p class="article" style="font-size:14px">${it.notes}</p>` }) : ''}
        </div>
      </div>`);
    UI.hydrate(ctx.view);
  };
  UI.on(ctx.view, 'click', '[data-act="edit"]', async () => { if (await Pages.itemModal(id)) draw(); });
  UI.on(ctx.view, 'click', '[data-act="labels"]', async () => { const it = await DB.get('items', id), units = await Data.assets.byItem(id); if (it && units.length) Pages.printLabels(it, units); });
  UI.on(ctx.view, 'click', '[data-page]', (e, el) => { st.offset = Math.max(0, st.offset + (el.dataset.page === 'next' ? st.limit : -st.limit)); draw(); });
  /* item rows handled in bindInv */
  Pages.bindInv(ctx, draw);
  await draw();
};

/* ── سجل الحركات ── */
Pages.movements = async (ctx) => {
  const st = { type: '', warehouseId: '', from: '', to: '', offset: 0, limit: 30 };
  ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'حركات المخزون', sub: 'سجل موثق لكل عملية استلام وصرف وتحويل وجرد', illu: 'network', actions: html`${Pages.invActions()}<button class="btn btn-ghost" data-act="csv">${UI.icon('download')} تصدير</button>` })}
    <section class="panel"><div class="toolbar"><select id="mtype" aria-label="نوع الحركة"><option value="">كل الحركات</option>${Object.entries(MOVES).map(([k, v]) => html`<option value="${k}">${v.label}</option>`)}</select><select id="mwh" aria-label="المخزن"><option value="">كل المخازن</option>${UI.opts('warehouses').map((o) => html`<option value="${o.value}">${o.label}</option>`)}</select><input type="date" id="mfrom" aria-label="من تاريخ"><input type="date" id="mto" aria-label="إلى تاريخ"></div><div id="mbody"></div></section>`);
  const f = () => ({ type: st.type, warehouseId: st.warehouseId, from: fromDateInput(st.from), to: st.to ? fromDateInput(st.to, true) : 0, offset: st.offset, limit: st.limit });
  const load = async () => { const res = await Data.inv.movements(f()); if (!ctx.alive()) return; $('#mbody', ctx.view).innerHTML = String(html`${await Pages.moveTable(res.rows)}${res.rows.length ? UI.pager({ offset: st.offset, limit: st.limit, count: res.rows.length, hasMore: res.hasMore }) : ''}`); };
  [['mtype', 'type'], ['mwh', 'warehouseId'], ['mfrom', 'from'], ['mto', 'to']].forEach(([id, k]) => { $('#' + id, ctx.view).onchange = (e) => { st[k] = e.target.value; st.offset = 0; load(); }; });
  UI.on(ctx.view, 'click', '[data-page]', (e, el) => { st.offset = Math.max(0, st.offset + (el.dataset.page === 'next' ? st.limit : -st.limit)); load(); });
  /* row clicks handled in bindInv */
  UI.on(ctx.view, 'click', '[data-act="csv"]', async () => { const { rows } = await Data.inv.movements({ ...f(), offset: 0, limit: 1e6 }); const names = new Map((await DB.getAll('items')).map((i) => [i.id, i.name])); downloadBlob(new Blob([toCSV(rows, [{ label: 'التاريخ', value: (m) => fmtDateTime(m.at) }, { label: 'الحركة', value: (m) => (MOVES[m.type] || {}).label }, { label: 'الصنف', value: (m) => names.get(m.itemId) || '' }, { label: 'المخزن', value: (m) => Data.nameOf('warehouses', m.warehouseId, '') }, { label: 'الكمية', key: 'delta' }, { label: 'الرصيد بعدها', key: 'balance' }, { label: 'الجهة', key: 'party' }, { label: 'المرجع', key: 'ref' }, { label: 'ملاحظات', key: 'note' }, { label: 'بواسطة', value: (m) => Data.userName(m.userId) }])], { type: 'text/csv;charset=utf-8' }), `حركات-المخزون-${dateInput(now())}.csv`); });
  Pages.bindInv(ctx, load);
  await load();
};

/* ── العهد والإعارات ── */
Pages.loans = async (ctx) => {
  const st = { tab: ctx.query.tab || 'active', q: '', offset: 0, limit: 25 };
  ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'العهد والإعارات', sub: 'من استلم ماذا، ومتى يعيده، بسند موقّع', illu: 'card', actions: Auth.can('loans.manage') ? html`<button class="btn btn-primary" data-act="lend">${UI.icon('plus')} تسليم عهدة جديدة</button>` : '' })}<div class="tabs" id="ltabs"></div><section class="panel"><div class="toolbar"><div class="search-box">${UI.icon('search')}<input id="lq" type="search" placeholder="رقم العهدة أو الصنف أو اسم المستلم أو القسم"></div></div><div id="lbody"></div></section>`);
  const tabs = async () => { const all = await DB.getAll('loans', 'status', KR('active')), t = now(); const c = { active: all.length, overdue: all.filter((l) => l.dueAt && l.dueAt < t).length, returned: await DB.count('loans', 'status', KR('returned')), all: await DB.count('loans') }; if (!ctx.alive()) return; $('#ltabs', ctx.view).innerHTML = String(html`${[['active', 'النشطة', 'clipboard'], ['overdue', 'المتأخرة', 'alert'], ['returned', 'المرتجعة', 'check'], ['all', 'الكل', 'database']].map(([k, l, ic]) => html`<button class="tab ${st.tab === k ? 'active' : ''}" data-tab="${k}">${UI.icon(ic)}${l}<span class="count">${fmtNum(c[k])}</span></button>`)}`); };
  const load = async () => {
    const res = await Data.inv.loans({ status: st.tab === 'returned' ? 'returned' : st.tab === 'active' ? 'active' : '', overdue: st.tab === 'overdue', q: st.q, offset: st.offset, limit: st.limit }); if (!ctx.alive()) return;
    const t = now(), manage = Auth.can('loans.manage');
    $('#lbody', ctx.view).innerHTML = String(res.rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>العهدة</th><th>الصنف</th><th>المستلم</th><th>الكمية</th><th>تاريخ التسليم</th><th>موعد الإرجاع</th><th>الحالة</th><th></th></tr></thead><tbody class="stagger">${res.rows.map((l) => { const late = l.status === 'active' && l.dueAt && l.dueAt < t; return html`<tr><td class="t-num">${l.number}</td><td><b>${l.itemName}</b></td><td><div>${l.borrower}</div><div class="t-sub">${Data.nameOf('departments', l.departmentId, '')}</div></td><td><div class="nowrap">${fmtNum(l.returnedQty)} / ${fmtNum(l.qty)}</div><div class="progress tone-${l.status === 'returned' ? 'teal' : 'sky'}" style="width:80px;height:5px;margin-top:4px"><i style="width:${Math.round((l.returnedQty / l.qty) * 100)}%"></i></div></td><td class="nowrap faint">${fmtDate(l.issuedAt)}</td><td class="nowrap">${l.dueAt ? html`${fmtDate(l.dueAt)}${late ? html`<div class="t-sub" style="color:rgb(var(--red-ink))">متأخرة ${fmtDuration(t - l.dueAt)}</div>` : ''}` : html`<span class="faint">عهدة دائمة</span>`}</td><td>${l.status === 'returned' ? UI.chip('teal', 'مرتجعة', 'check') : late ? UI.chip('red', 'متأخرة', 'alert') : UI.chip('sky', 'نشطة')}</td><td class="nowrap">${manage && l.status === 'active' ? html`<button class="btn btn-ok btn-sm" data-ret="${l.id}">${UI.icon('undo')} إرجاع</button>` : ''}<button class="icon-btn" style="width:32px;height:32px" data-print="${l.id}" title="طباعة السند" aria-label="طباعة السند">${UI.icon('print')}</button></td></tr>`; })}</tbody></table></div>${UI.pager({ offset: st.offset, limit: st.limit, count: res.rows.length, hasMore: res.hasMore })}` : UI.empty({ illu: 'card', title: 'لا توجد عهد في هذا القسم', text: 'سجّل تسليم أي جهاز أو صنف لموظف لتتبعه حتى إرجاعه.' }));
  };
  UI.on(ctx.view, 'click', '[data-tab]', (e, el) => { st.tab = el.dataset.tab; st.offset = 0; $$('[data-tab]', ctx.view).forEach((b) => b.classList.toggle('active', b === el)); load(); });
  $('#lq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); st.offset = 0; load(); }, 300));
  UI.on(ctx.view, 'click', '[data-page]', (e, el) => { st.offset = Math.max(0, st.offset + (el.dataset.page === 'next' ? st.limit : -st.limit)); load(); });
  UI.on(ctx.view, 'click', '[data-ret]', async (e, el) => { const l = await DB.get('loans', el.dataset.ret); if (l && (await Pages.returnModal(l))) { load(); tabs(); } });
  UI.on(ctx.view, 'click', '[data-print]', async (e, el) => { const l = await DB.get('loans', el.dataset.print); if (l) { if (VPV.pref() === 'print') Pages.loanReceipt(l); else VED.loan(l); } });
  Pages.bindInv(ctx, () => { load(); tabs(); });
  await Promise.all([tabs(), load()]);
};

/* ── التقارير والتحليلات ─────────────────────────────────────── */
Pages.reports = async (ctx) => {
  const st = { days: [7, 30, 90, 365].includes(Number(ctx.query.days)) ? Number(ctx.query.days) : 30, from: '', to: '' };
  const draw = async () => {
    const to = st.to ? startOfDay(fromDateInput(st.to, true)) + DAY - 1 : now();
    const from = st.from ? startOfDay(fromDateInput(st.from, true)) : startOfDay(to) - (st.days - 1) * DAY;
    const days = Math.max(1, Math.round((startOfDay(to) - startOfDay(from)) / DAY) + 1), bucket = days > 120 ? 7 : 1, n = Math.ceil(days / bucket);
    ctx.range = { from, to, days };
    const [win, prev, peak] = await Promise.all([Stats.window(from, to), Stats.window(from - days * DAY, from - 1), Stats.peak(from)]);
    const series = (rows, key) => { const a = new Array(n).fill(0); rows.forEach((r) => { const i = Math.floor((startOfDay(r[key]) - from) / DAY / bucket); if (i >= 0 && i < n) a[i]++; }); return a; };
    const labels = Array.from({ length: n }, (_, i) => { const d = new Date(from + i * bucket * DAY); return `${d.getDate()}/${d.getMonth() + 1}`; });
    let inQ = 0, outQ = 0; const byType = {}, issued = new Map();
    if (Auth.can('inventory.read')) await DB.each('movements', { index: 'at', range: KR(from, to) }, (m) => { byType[m.type] = (byType[m.type] || 0) + 1; if (m.type === 'adjust') return; if (m.delta > 0) inQ += m.qty; else outQ += m.qty; if (m.type === 'issue' || m.type === 'loan_out') issued.set(m.itemId, (issued.get(m.itemId) || 0) + m.qty); });
    const topItems = await Promise.all([...issued].sort((a, b) => b[1] - a[1]).slice(0, 6).map(async ([id, v], i) => { const it = await DB.get('items', id); return { label: it ? it.name : 'صنف محذوف', value: v, tone: TONES[i % TONES.length], lead: String(UI.illu(itemIllu(it))) }; }));
    const lb = Stats.leaderboard(win.resolved, 50), assignedBy = Stats.group(win.created.filter((t) => t.assigneeId), 'assigneeId'), avg = Stats.avgRes(win.resolved) / HOUR, first = Stats.avgFirst(win.created) / HOUR, sla = Stats.slaPct(win.resolved);
    const statusData = Object.keys(STATUS).map((k) => ({ label: STATUS[k].label, value: win.created.filter((t) => t.status === k).length, tone: STATUS[k].tone }));
    if (!ctx.alive()) return;
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ title: 'التقارير والتحليلات', sub: st.from && st.to ? `الفترة من ${fmtDate(from)} إلى ${fmtDate(to)} (${arCount(days, AR.day)})` : `أداء الدعم الفني والمخازن خلال آخر ${days} يوماً مقارنة بالفترة السابقة`, illu: 'display', actions: html`<div class="seg" role="radiogroup" aria-label="الفترة">${[[7, 'أسبوع'], [30, 'شهر'], [90, 'ربع سنة'], [365, 'سنة']].map(([d, l]) => html`<label><input type="radio" name="period" value="${d}"${!st.from && !st.to && d === days ? raw(' checked') : ''}><span>${l}</span></label>`)}</div><div class="range-bar"><span class="faint small">من</span><input type="date" id="rgFrom" dir="ltr" lang="en-GB" value="${st.from}" max="${dateInput(now())}"><span class="faint small">إلى</span><input type="date" id="rgTo" dir="ltr" lang="en-GB" value="${st.to}" max="${dateInput(now())}">${st.from || st.to ? html`<button class="btn btn-ghost btn-sm" data-range="clear">${UI.icon('refresh')} إلغاء التحديد</button>` : ''}</div><button class="btn" data-act="xlsx">${UI.icon('download')} تصدير Excel</button><button class="btn btn-soft" data-act="detailed">${UI.icon('file')} تقرير مفصّل</button><button class="btn btn-ghost" data-act="csv">${UI.icon('download')} CSV</button><button class="btn btn-ghost" data-act="print">${UI.icon('print')} طباعة</button>` })}
      <div class="kpis">
        ${UI.kpi({ label: 'بلاغات واردة', icon: 'download', tone: 'sky', value: win.created.length, foot: Stats.delta(win.created.length, prev.created.length, false), spark: series(win.created, 'createdAt').slice(-14) })}
        ${UI.kpi({ label: 'بلاغات محلولة', icon: 'check', tone: 'teal', value: win.resolved.length, foot: Stats.delta(win.resolved.length, prev.resolved.length), spark: series(win.resolved, 'resolvedAt').slice(-14) })}
        ${UI.kpi({ label: 'متوسط زمن الحل', icon: 'clock', tone: 'amber', value: avg, dec: 1, suffix: ' س', foot: Stats.delta(avg, Stats.avgRes(prev.resolved) / HOUR, false) })}
        ${UI.kpi({ label: 'متوسط أول استجابة', icon: 'send', tone: 'violet', value: first, dec: 1, suffix: ' س', foot: Stats.delta(first, Stats.avgFirst(prev.created) / HOUR, false) })}
        ${UI.kpi({ label: 'الالتزام بالموعد', icon: 'shield', tone: 'green', value: sla, suffix: '%', foot: Stats.delta(sla, Stats.slaPct(prev.resolved)) })}
        
      </div>
      ${UI.panel({ title: 'الوارد مقابل المحلول', icon: 'pulse', cls: 'mt', sub: bucket > 1 ? 'مجمّعة أسبوعياً' : 'يومياً', body: UI.chart.area([{ name: 'واردة', tone: 'sky', values: series(win.created, 'createdAt') }, { name: 'محلولة', tone: 'teal', values: series(win.resolved, 'resolvedAt') }], labels, { height: 250 }) })}
      <div class="grid g-3 mt">
        ${UI.panel({ title: 'حالات بلاغات الفترة', icon: 'layers', body: UI.chart.donut(statusData, { label: 'بلاغ', size: 150 }) })}
        ${UI.panel({ title: 'حسب الأولوية', icon: 'alert', body: UI.chart.bars(Object.entries(PRIORITY).map(([k, p]) => ({ label: p.label, value: win.created.filter((t) => t.priority === k).length, tone: p.tone })), { height: 200 }) })}
        ${UI.panel({ title: 'الالتزام باتفاقية الخدمة', icon: 'shield', body: UI.chart.gauge(sla, { label: 'ضمن الموعد', tone: sla >= 90 ? 'teal' : sla >= 70 ? 'amber' : 'red' }) })}
      </div>
      <div class="grid g-3 mt">
        ${UI.panel({ title: 'حسب الفئة', icon: 'tag', body: UI.chart.hbars(Stats.group(win.created, 'categoryId').slice(0, 8).map(([id, v], i) => ({ label: Data.nameOf('categories', id, 'أخرى'), value: v, tone: TONES[i % TONES.length], lead: String(UI.illu(catIllu(id))) }))) })}
        ${UI.panel({ title: 'حسب القسم', icon: 'building', body: UI.chart.treemap(Stats.group(win.created, 'departmentId').map(([id, v]) => ({ label: Data.nameOf('departments', id, 'غير محدد'), value: v }))) })}
        ${UI.panel({ title: 'حسب القسم والمكتب', icon: 'layers', body: UI.chart.hbars(Stats.group(win.created.filter((t) => t.unitId), 'unitId').slice(0, 8).map(([id, v], i) => ({ label: Data.nameOf('deptUnits', id, 'فرع محذوف'), value: v, tone: TONES[(i + 3) % TONES.length] }))) })}
      </div>
      <div class="grid g-main mt">
        ${UI.panel({ title: 'أداء الفنيين', icon: 'users', flush: true, body: lb.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>#</th><th>الفني</th><th>مسندة</th><th>محلولة</th><th>متوسط الحل</th><th>ضمن الموعد</th></tr></thead><tbody class="stagger">${lb.map((r, i) => { const mine = win.resolved.filter((t) => t.assigneeId === r.userId), p = Stats.slaPct(mine); return html`<tr><td><span class="rank">${i + 1}</span></td><td><div class="row nowrap" style="flex-wrap:nowrap;gap:8px">${UI.avatar(r.userId, 'av-sm')}${Data.userName(r.userId)}</div></td><td>${fmtNum((assignedBy.find(([id]) => id === r.userId) || [0, 0])[1])}</td><td><b>${fmtNum(r.value)}</b></td><td class="nowrap">${fmtDuration(r.avg)}</td><td><div class="row nowrap" style="gap:8px;flex-wrap:nowrap">${UI.ring(p / 100, p >= 90 ? 'teal' : p >= 70 ? 'amber' : 'red')}${Math.round(p)}%</div></td><td>${r.rate ? html`${UI.stars(Math.round(r.rate))} <span class="small faint">${r.rate.toFixed(1)}</span>` : html`<span class="faint">—</span>`}</td></tr>`; })}</tbody></table></div>` : html`<div class="panel-body">${UI.noData('لا توجد بلاغات محلولة في هذه الفترة')}</div>` })}
        ${UI.panel({ title: 'أوقات الذروة', icon: 'clock', sub: 'توزيع البلاغات على أيام الأسبوع وساعات اليوم', body: UI.chart.heatWeek(peak) })}
      </div>
      ${Auth.can('inventory.read') ? html`<h2 class="mt" style="font-size:16px;margin-bottom:12px;display:flex;gap:8px;align-items:center">${UI.icon('warehouse')} المخازن خلال الفترة</h2><div class="grid g-3">
        ${UI.panel({ title: 'الكميات', icon: 'swap', body: html`<div class="grid g-2" style="gap:10px"><div class="center"><div style="font:800 34px var(--f-display);color:rgb(var(--teal-ink))" data-count="${inQ}">0</div><div class="faint small">وحدة واردة</div></div><div class="center"><div style="font:800 34px var(--f-display);color:rgb(var(--amber-ink))" data-count="${outQ}">0</div><div class="faint small">وحدة صادرة</div></div></div>${UI.chart.bars(Object.entries(MOVES).map(([k, m]) => ({ label: m.label, value: byType[k] || 0, tone: MOVE_TONE[k] })), { height: 150 })}` })}
        ${UI.panel({ title: 'الأكثر صرفاً', icon: 'upload', body: UI.chart.hbars(topItems) })}
        ${UI.panel({ title: 'توزيع الحركات', icon: 'layers', body: UI.chart.donut(Object.entries(MOVES).map(([k, m]) => ({ label: m.label, value: byType[k] || 0, tone: MOVE_TONE[k] })), { label: 'حركة', size: 140 }) })}
      </div>` : ''}`);
    UI.hydrate(ctx.view);
    ctx.lastWin = win;
  };
  UI.on(ctx.view, 'change', 'input[name="period"]', (e, el) => { st.days = Number(el.value); st.from = ''; st.to = ''; history.replaceState(null, '', `#/reports?days=${st.days}`); draw(); });
  UI.on(ctx.view, 'click', '[data-act="avatar"]', async () => { if (await Pages.avatarModal()) draw(); });
  UI.on(ctx.view, 'click', '[data-act="print"]', () => window.print());
  UI.on(ctx.view, 'click', '[data-act="detailed"]', () => Pages.exportModal());
  UI.on(ctx.view, 'click', '[data-act="xlsx"]', () => Pages.reportExcel(ctx.lastWin, ctx.range || { from: now() - 30 * DAY, to: now() }));
  UI.on(ctx.view, 'change', '#rgFrom, #rgTo', (e, el) => { if (el.id === 'rgFrom') st.from = el.value; else st.to = el.value; if (st.from && st.to) draw(); });
  UI.on(ctx.view, 'click', '[data-range]', (e, el) => { const k = el.dataset.range; if (k === 'clear') { st.from = ''; st.to = ''; } else { st.days = Number(k); st.from = ''; st.to = ''; } draw(); });
  UI.on(ctx.view, 'click', '[data-act="csv"]', () => { const rows = (ctx.lastWin || { created: [] }).created; downloadBlob(new Blob([toCSV(rows, [{ label: 'رقم البلاغ', key: 'number' }, { label: 'العنوان', key: 'title' }, { label: 'الفئة', value: (t) => Data.nameOf('categories', t.categoryId, '') }, { label: 'القسم', value: (t) => Data.nameOf('departments', t.departmentId, '') }, { label: 'الأولوية', value: (t) => PRIORITY[t.priority].label }, { label: 'الحالة', value: (t) => STATUS[t.status].label }, { label: 'الفني', value: (t) => (t.assigneeId ? Data.userName(t.assigneeId) : '') }, { label: 'الإنشاء', value: (t) => fmtDateTime(t.createdAt) }, { label: 'زمن الحل بالساعات', value: (t) => (t.resolvedAt ? ((t.resolvedAt - t.createdAt) / HOUR).toFixed(1) : '') }, { label: 'ضمن الموعد', value: (t) => (t.resolvedAt ? (t.resolvedAt <= t.dueAt ? 'نعم' : 'لا') : '') }, ])], { type: 'text/csv;charset=utf-8' }), `تقرير-البلاغات-${st.days}يوم-${dateInput(now())}.csv`); UI.toast(`تم تصدير ${arCount(rows.length, AR.ticket)}`); });
  await draw();
};

/* ── المستخدمون ─────────────────────────────────────────────── */
const ROLE_TONE = { department: 'sky', technician: 'teal', support_manager: 'violet', supervisor: 'brass', monitor: 'slate' };
const genPassword = () => { const a = 'abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ', d = '23456789', b = new Uint8Array(10); crypto.getRandomValues(b); let s = Array.from(b.slice(0, 7), (x) => a[x % a.length]).join('') + Array.from(b.slice(7), (x) => d[x % d.length]).join(''); return s; };

/* ── الملف الشخصي والتخصيص ──────────────────────────────────── */
Pages.profile = async (ctx) => {
  const draw = async () => {
    const u = Auth.user, m = await Medals.compute(u), acts = [];
    await DB.each('activity', { index: 'at', dir: 'prev' }, (a) => { if (a.userId === u.id) acts.push(a); if (acts.length >= 8) return false; });
    if (!ctx.alive()) return;
    const theme = localStorage.getItem('sq_theme') || 'auto', accent = document.documentElement.dataset.accent, hue = UI.hueOf(u);
    ctx.view.innerHTML = String(html`
      ${needsPwChange(u) ? html`<div class="banner tone-amber">${UI.icon('lock')}<div class="grow"><b>يجب تغيير كلمة المرور المؤقتة قبل المتابعة</b><div class="small muted">اختر كلمة مرور خاصة بك من 8 أحرف على الأقل تتضمن حروفاً وأرقاماً.</div></div></div>` : ''}
      <section class="profile-hero"><div class="avatar-edit">${UI.avatar(u, 'av-xl')}<button class="icon-btn" data-act="photo" title="تغيير الصورة" aria-label="تغيير الصورة">${UI.icon('upload')}</button></div>
        <div><h1>${u.name}</h1><div class="row" style="margin-top:6px">${UI.chip(ROLE_TONE[u.role] || 'slate', ROLES[u.role], 'shield')}<span class="faint">@${u.username}</span><span class="faint">${Data.nameOf('departments', u.departmentId, '')}</span></div><p class="small faint" style="margin-top:6px">آخر دخول ${u.lastLoginAt ? fmtDateTime(u.lastLoginAt) : '—'}</p></div>
        <div class="profile-stats"><div><b data-count="${m.submitted}">0</b><small>بلاغ قدّمته</small></div>${m.staff ? html`<div><b data-count="${m.resolved}">0</b><small>بلاغ حللته</small></div>` : ''}</div>
      </section>
      <div class="grid g-2">
        ${UI.panel({ title: 'تخصيص المظهر', icon: 'sliders', body: html`<div class="stack" style="gap:18px">
          <div class="field"><label>المظهر</label><div class="seg">${[['dark', 'داكن', 'moon'], ['light', 'فاتح', 'sun'], ['auto', 'حسب الجهاز', 'monitor']].map(([k, l, ic]) => html`<label><input type="radio" name="theme" value="${k}"${theme === k ? raw(' checked') : ''}><span>${UI.icon(ic)}${l}</span></label>`)}</div></div>
          <div class="field"><label>لون التمييز</label><div class="swatches">${[['brass', 'نحاسي'], ['teal', 'فيروزي'], ['sky', 'سماوي'], ['violet', 'بنفسجي'], ['red', 'قرمزي']].map(([k, l]) => html`<button class="swatch tone-${k} ${accent === k ? 'active' : ''}" data-accent="${k}" title="${l}" aria-label="${l}"></button>`)}</div></div>
          <div class="field"><label>لون الصورة الرمزية</label><div class="hues">${[210, 250, 280, 330, 0, 25, 45, 150, 175, 195].map((h) => html`<button style="--h:${h}" class="${h === hue ? 'active' : ''}" data-hue="${h}" aria-label="لون ${h}"></button>`)}</div></div>
          <div class="row" style="gap:22px">${UI.field({ name: 'motion', type: 'switch', text: 'الحركات والمؤثرات' }, document.documentElement.dataset.motion !== 'off')}</div>
          ${u.photo ? html`<button class="btn btn-ghost btn-sm" data-act="nophoto" style="align-self:flex-start">${UI.icon('trash')} حذف الصورة الشخصية</button>` : ''}
        </div>` })}
        ${isSysAccount(u) && u.role !== 'supervisor' ? UI.panel({ title: 'كلمة المرور', icon: 'lock', body: html`<div class="banner tone-brass" style="margin:0">${UI.icon('shield')}<div class="grow"><b>حساب أساسي ثابت</b><div class="small muted">اسم المستخدم وكلمة المرور لهذا الحساب ثابتان، ولا يغيّرهما إلا المشرف. يمكنك تخصيص المظهر والصورة من هذه الصفحة.</div></div></div>` }) : UI.panel({ title: 'تغيير كلمة المرور', icon: 'lock', body: html`<form id="pwForm" class="stack" style="gap:14px" novalidate><input type="text" name="username" autocomplete="username" value="${u.username || ''}" hidden tabindex="-1" aria-hidden="true">${UI.field({ name: 'current', label: 'كلمة المرور الحالية', type: 'password', autocomplete: 'current-password', required: true })}${UI.field({ name: 'next', label: 'كلمة المرور الجديدة', type: 'password', autocomplete: 'new-password', required: true })}<div class="strength" id="pwStr"><i></i><i></i><i></i><i></i></div>${UI.field({ name: 'confirm', label: 'تأكيد كلمة المرور الجديدة', type: 'password', autocomplete: 'new-password', required: true })}<button class="btn btn-primary" type="submit">${UI.icon('check')} تحديث كلمة المرور</button></form>` })}
      </div>
      ${UI.panel({ title: 'نشاطي الأخير', icon: 'pulse', cls: 'mt', body: acts.length ? html`<div class="timeline">${acts.map((a) => html`<div class="tl"><span class="tl-icon tone-${ACT_TONE[a.action] || 'slate'}">${UI.icon(ACT_ICON[a.action] || 'pulse')}</span><div class="tl-head">${a.summary}<span class="tl-time">${timeAgo(a.at)}</span></div></div>`)}</div>` : UI.noData('لا يوجد نشاط مسجل بعد') })}`);
    const pwf = $('#pwForm', ctx.view);
    if (!pwf) return;
    pwf.querySelector('[name="next"]').addEventListener('input', (e) => { $('#pwStr', ctx.view).dataset.s = e.target.value ? Data.users.strength(e.target.value) : 0; });
    pwf.addEventListener('submit', async (e) => {
      e.preventDefault(); const v = UI.formValues(pwf), btn = pwf.querySelector('[type=submit]');
      try {
        if (v.next !== v.confirm) throw new AppError('كلمتا المرور الجديدتان غير متطابقتين');
        if (v.next === v.current) throw new AppError('اختر كلمة مرور مختلفة عن الحالية');
        UI.busy(btn, true); await new Promise((r) => setTimeout(r, 40));
        const rec = await DB.get('users', u.id); if (!(Sync.on && Sync.token) && !(await Crypto.verifyPassword(v.current, rec.pass))) throw new AppError('كلمة المرور الحالية غير صحيحة');
        const forced = needsPwChange(u); await Data.users.setPassword(u.id, v.next, false, v.current); Auth.user = await DB.get('users', u.id);
        rememberPw(u, v.next);
        UI.toast('تم تحديث كلمة المرور بنجاح'); UI.confetti();
        if (forced) { Shell.unmount(); Router.go('/dashboard'); } else pwf.reset();
      } catch (ex) { UI.error(ex); } finally { UI.busy(btn, false); }
    });
  };
  const saveUser = async (patch) => { const rec = await DB.get('users', Auth.user.id); Object.assign(rec, patch, { updatedAt: now() }); await DB.put('users', rec); await Data.refresh('users'); Auth.user = rec; Shell.unmount(); await Router.resolve(); };
  UI.on(ctx.view, 'change', 'input[name="theme"]', (e, el) => { if (el.value === 'auto') { localStorage.removeItem('sq_theme'); UI.theme.apply(); } else UI.theme.set('theme', el.value); });
  UI.on(ctx.view, 'click', '[data-accent]', (e, el) => { UI.theme.set('accent', el.dataset.accent); $$('[data-accent]', ctx.view).forEach((b) => b.classList.toggle('active', b === el)); UI.sound('notify'); });
  UI.on(ctx.view, 'click', '[data-hue]', (e, el) => saveUser({ prefs: { ...(Auth.user.prefs || {}), hue: Number(el.dataset.hue) } }));
  UI.on(ctx.view, 'change', 'input[name="motion"]', (e, el) => UI.theme.set('motion', el.checked ? 'on' : 'off'));
  UI.on(ctx.view, 'click', '[data-act="photo"]', async () => { const [f] = await UI.pickFiles({ accept: 'image/*', multiple: false }); if (!f) return; try { await saveUser({ photo: await UI.resizeImage(f, 180) }); UI.toast('تم تحديث الصورة الشخصية'); } catch (ex) { UI.error(ex); } });
  UI.on(ctx.view, 'click', '[data-act="nophoto"]', () => saveUser({ photo: '' }));
  await draw();
};
const ACT_ICON = { create: 'plus', update: 'edit', delete: 'trash', login: 'key', logout: 'logout', password: 'lock', move: 'swap', status: 'refresh', assign: 'user-plus', comment: 'send', rate: 'star' };
const ACT_LABEL = { create: 'إضافة', update: 'تعديل', delete: 'حذف', login: 'تسجيل دخول', logout: 'تسجيل خروج', password: 'كلمة المرور', move: 'حركة مخزون', status: 'تغيير حالة', assign: 'إسناد', comment: 'رد', rate: 'تقييم', backup: 'نسخة احتياطية', lend: 'تسليم عهدة', return: 'إرجاع عهدة', import: 'استيراد', migrate: 'ترحيل' };
const ACT_TONE = { create: 'teal', update: 'sky', delete: 'red', login: 'violet', logout: 'slate', password: 'amber', move: 'amber', status: 'sky', assign: 'violet', comment: 'teal', rate: 'brass' };

/* ── قاعدة المعرفة ─────────────────────────────────────────── */
Pages.kbEditor = async (id) => {
  const a = id ? await DB.get('kb', id) : {};
  return UI.modal({ title: id ? 'تعديل المقال' : 'مقال حل جديد', icon: 'book', size: 'lg', body: UI.fields([{ name: 'title', label: 'عنوان المشكلة', required: true, wide: true }, { name: 'categoryId', label: 'الفئة', type: 'select', options: UI.opts('categories') }, { name: 'keywords', label: 'كلمات مفتاحية للبحث', placeholder: 'مثال: طباعة، ورق، انحشار' }, { name: 'body', label: 'خطوات الحل', type: 'textarea', rows: 10, wide: true, placeholder: '1. ...\n2. ...' }], a), actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ المقال', kind: 'primary', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); if (!v.title.trim() || !v.body.trim()) throw new AppError('العنوان وخطوات الحل مطلوبة'); const r = await Data.saveRecord('kb', { ...a, ...v, author: a.author || Auth.user.name, views: a.views || 0, helpful: a.helpful || 0 }, 'مقال'); UI.toast('تم حفظ المقال'); return r; } }] });
};
Pages.kbArticle = async (id) => {
  const a = await Data.kb.view(id).then(() => DB.get('kb', id)); if (!a) return;
  const write = Auth.can('kb.write');
  const r = await UI.modal({ title: a.title, icon: 'book', size: 'lg', body: html`<div class="row" style="margin-bottom:14px">${UI.chip('sky', Data.nameOf('categories', a.categoryId, 'عام'), 'tag')}<span class="kb-meta">${UI.icon('eye')} ${fmtNum(a.views)} مشاهدة ${UI.icon('check')} ${fmtNum(a.helpful)} وجدوه مفيداً</span></div><div class="article">${a.body}</div>${a.author ? html`<p class="small faint mt">كتبه ${a.author} — آخر تحديث ${timeAgo(a.updatedAt || a.createdAt)}</p>` : ''}`, actions: [...(write ? [{ label: 'حذف', kind: 'danger', icon: 'trash', value: 'delete' }, { label: 'تعديل', kind: 'ghost', icon: 'edit', value: 'edit' }] : []), { label: 'لم يحل مشكلتي', kind: 'ghost', value: 'ticket' }, { label: 'مفيد', kind: 'ok', icon: 'check', value: 'vote' }] });
  if (r === 'vote') { await Data.kb.vote(id); UI.toast('شكراً! رأيك يساعد الآخرين'); UI.sound('success'); Bus.emit('data:kb'); }
  else if (r === 'ticket' && Auth.can('tickets.create')) Router.go(`/tickets/new${a.categoryId ? `?cat=${a.categoryId}` : ''}`);
  else if (r === 'edit') { if (await Pages.kbEditor(id)) Bus.emit('data:kb'); }
  else if (r === 'delete' && (await UI.confirm(`حذف المقال «${a.title}» نهائياً؟`, { danger: true, ok: 'حذف' }))) { await Data.deleteRecord('kb', id, 'مقال'); UI.toast('تم حذف المقال'); Bus.emit('data:kb'); }
};
Pages.kb = async (ctx) => {
  const st = { q: '', cat: '' }, write = Auth.can('kb.write');
  ctx.view.innerHTML = String(html`<section class="kb-hero"><div><h1>كيف يمكننا مساعدتك؟</h1><p class="muted">حلول مجرّبة لأكثر المشكلات التقنية شيوعاً في الأكاديمية</p><div class="search-box">${UI.icon('search')}<input id="kbq" type="search" placeholder="اكتب المشكلة، مثل: الطابعة لا تطبع" autocomplete="off"></div><div class="quick-chips" id="kbcats" style="margin-top:14px"></div></div>${UI.illu('software')}</section>
    <div class="row mb" style="justify-content:space-between"><h2 style="font-size:16px" id="kbCount"></h2>${write ? html`<button class="btn btn-primary" data-act="new">${UI.icon('plus')} مقال جديد</button>` : ''}</div><div id="kbList"></div>`);
  const cats = Data.list('categories');
  const chips = () => { $('#kbcats', ctx.view).innerHTML = String(html`<button class="qchip" data-cat="" style="${st.cat ? '' : 'border-style:solid;color:rgb(var(--accent-ink))'}">الكل</button>${cats.map((c) => html`<button class="qchip" data-cat="${c.id}" style="${st.cat === c.id ? 'border-style:solid;color:rgb(var(--accent-ink))' : ''}">${c.name}</button>`)}`); };
  const load = async () => {
    const rows = await Data.kb.search(st.q, st.cat); if (!ctx.alive()) return;
    $('#kbCount', ctx.view).textContent = arCount(rows.length, AR.article);
    $('#kbList', ctx.view).innerHTML = String(rows.length ? html`<div class="grid g-3 stagger">${rows.map((a) => html`<button class="kb-card" data-kb="${a.id}"><div class="row" style="flex-wrap:nowrap">${UI.illu(catIllu(a.categoryId), 'mini')}<b>${a.title}</b></div><p>${a.body}</p><span class="kb-meta">${UI.icon('eye')} ${fmtNum(a.views)} ${UI.icon('check')} ${fmtNum(a.helpful)} ${a.categoryId ? html`<span style="margin-inline-start:auto">${Data.nameOf('categories', a.categoryId)}</span>` : ''}</span></button>`)}</div>` : UI.empty({ illu: 'software', title: 'لم نجد حلاً مطابقاً', text: 'جرّب كلمات أخرى، أو قدّم بلاغاً وسيساعدك فريق الدعم.', action: Auth.can('tickets.create') ? html`<a class="btn btn-primary" href="#/tickets/new">${UI.icon('plus')} بلاغ جديد</a>` : '' }));
  };
  $('#kbq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value; load(); }, 220));
  UI.on(ctx.view, 'click', '[data-cat]', (e, el) => { st.cat = el.dataset.cat; chips(); load(); });
  UI.on(ctx.view, 'click', '[data-kb]', (e, el) => Pages.kbArticle(el.dataset.kb));
  UI.on(ctx.view, 'click', '[data-act="new"]', async () => { if (await Pages.kbEditor()) load(); });
  ctx.onCleanup(Bus.on('data:kb', () => { if (ctx.alive()) load(); }));
  chips(); await load();
  if (ctx.query.open) setTimeout(() => Pages.kbArticle(ctx.query.open), 200);
};

/* ── الإشعارات وسجل النشاط ─────────────────────────────────── */
/* أيقونة فئة البلاغ في الإشعار (طابعة، شبكة، بريد…) مع شارة صغيرة لنوعه، بدل أيقونة «بلاغ» واحدة لكل البلاغات.
   الفئة من الإشعار نفسه، وللإشعارات الأقدم من البلاغ إن كان على الجهاز */
const NotifCat = {
  tid(n) { const m = /^\/tickets\/([^/?#]+)/.exec(n.link || ''); return m && m[1] !== 'new' ? m[1] : ''; },
  async map(rows) {
    const out = new Map();
    await Promise.all(rows.map(async (n) => { let c = n.cat || ''; const id = !c && NotifCat.tid(n); if (id) { try { const t = await DB.get('tickets', id); if (t) c = t.categoryId || 'other'; } catch (_) { /* تجاهل */ } } if (c) out.set(n.id, c); }));
    return out;
  },
  ic(n, cats, fallback) { const c = cats.get(n.id); return c ? html`<span class="n-ic n-cat" title="${Data.nameOf('categories', c, 'أخرى')}">${UI.illu(catIllu(c))}<i class="n-kind${n.tone === 'urgent' ? ' urgent' : ''}">${UI.icon(n.tone === 'urgent' ? 'alert' : 'ticket')}</i></span>` : fallback; }
};
Pages.notifications = async (ctx) => {
  const st = { unread: false, offset: 0, limit: 40 }, me = Auth.user.id;
  ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'الإشعارات', sub: 'كل ما يخصك من تحديثات', illu: 'bell', actions: html`<label class="switch"><input type="checkbox" id="nUnread"><i></i><span>غير المقروءة فقط</span></label><button class="btn" data-act="readall">${UI.icon('check')} قراءة الكل</button><button class="btn" data-act="delread">${UI.icon('trash')} حذف المقروءة</button>` })}<section class="panel"><div class="panel-body" id="nList"></div></section><p class="hint mt">تُحذف الإشعارات المقروءة تلقائياً بعد ${NOTE_KEEP_DAYS} أيام من فتحها.</p>`);
  const load = async () => {
    const { rows, hasMore } = await DB.page('notifications', { index: 'user_at', range: KR([me, 0], [me, Infinity]), offset: st.offset, limit: st.limit, filter: st.unread ? (n) => !n.read : null }); if (!ctx.alive()) return;
    const cats = await NotifCat.map(rows); if (!ctx.alive()) return;
    let last = '';
    $('#nList', ctx.view).innerHTML = String(rows.length ? html`${rows.map((n) => { const day = fmtDate(n.at), headRow = day !== last ? html`<div class="day-head">${startOfDay(n.at) === startOfDay() ? 'اليوم' : startOfDay(n.at) === startOfDay() - DAY ? 'أمس' : day}</div>` : ''; last = day; return html`${headRow}<div class="note tone-${n.kind === 'inventory' ? 'amber' : n.kind === 'ticket' ? 'sky' : 'teal'} ${n.read ? '' : 'unread'}" data-id="${n.id}" data-link="${n.link}">${NotifCat.ic(n, cats, html`<span class="n-ic">${UI.icon(n.kind === 'inventory' ? 'box' : n.kind === 'ticket' ? 'ticket' : 'bell')}</span>`)}<div class="grow"><b>${n.title}</b><small>${n.body || ''}</small></div><small class="faint nowrap">${fmtTime(n.at)}</small><button type="button" class="icon-btn n-del" data-del="${n.id}" aria-label="حذف الإشعار" title="حذف">${UI.icon('x')}</button></div>`; })}${UI.pager({ offset: st.offset, limit: st.limit, count: rows.length, hasMore })}` : UI.empty({ illu: 'bell', title: 'لا توجد إشعارات', text: 'ستصلك هنا تحديثات البلاغات والمخازن.' }));
  };
  $('#nUnread', ctx.view).onchange = (e) => { st.unread = e.target.checked; st.offset = 0; load(); };
  UI.on(ctx.view, 'click', '[data-act="readall"]', async () => { await Data.notes.readAll(); load(); });
  UI.on(ctx.view, 'click', '[data-act="delread"]', async () => { const rows = (await DB.getAll('notifications', 'user_at', KR([me, 0], [me, Infinity]))).filter((n) => n.read); if (!rows.length) { UI.toast('لا توجد إشعارات مقروءة'); return; } await Data.notes.remove(rows.map((n) => n.id)); UI.toast(`حُذف ${fmtNum(rows.length)} إشعار`); Shell.refreshBell(); load(); });
  UI.on(ctx.view, 'click', '.note', async (e, el) => { const d = e.target.closest('[data-del]'); if (d) { e.stopPropagation(); await Data.notes.remove(d.dataset.del); Shell.refreshBell(); load(); return; } await Data.notes.read(el.dataset.id); Shell.refreshBell(); if (el.dataset.link) Router.go(el.dataset.link); else load(); });
  UI.on(ctx.view, 'click', '[data-page]', (e, el) => { st.offset = Math.max(0, st.offset + (el.dataset.page === 'next' ? st.limit : -st.limit)); load(); });
  await load();
};
Pages.activity = async (ctx) => {
  const st = { user: '', action: '', from: '', to: '', offset: 0, limit: 40 };
  ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'سجل النشاط', sub: 'تتبع كامل لكل عملية في النظام: من، ماذا، ومتى', illu: 'cctv', actions: html`<button class="btn" data-act="csv">${UI.icon('download')} تصدير</button>` })}<section class="panel"><div class="toolbar"><select id="aUser" aria-label="المستخدم"><option value="">كل المستخدمين</option>${UI.userOpts().map((o) => html`<option value="${o.value}">${o.label}</option>`)}</select><select id="aAct" aria-label="نوع العملية"><option value="">كل العمليات</option>${Object.keys(ACT_LABEL).map((k) => html`<option value="${k}">${ACT_LABEL[k]}</option>`)}</select><input type="date" dir="ltr" lang="en-GB" id="aFrom" aria-label="من تاريخ"><input type="date" dir="ltr" lang="en-GB" id="aTo" aria-label="إلى تاريخ"></div><div id="aBody"></div></section>`);
  const opts = (all) => ({ index: 'at', range: KR(fromDateInput(st.from), st.to ? fromDateInput(st.to, true) : Infinity), offset: all ? 0 : st.offset, limit: all ? 1e6 : st.limit, filter: st.user || st.action ? (a) => (!st.user || a.userId === st.user) && (!st.action || a.action === st.action) : null });
  const load = async () => {
    const { rows, hasMore } = await DB.page('activity', opts()); if (!ctx.alive()) return;
    $('#aBody', ctx.view).innerHTML = String(rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>الوقت</th><th>المستخدم</th><th>العملية</th><th>التفاصيل</th></tr></thead><tbody class="stagger">${rows.map((a) => html`<tr><td class="nowrap faint">${fmtDateTime(a.at)}</td><td>${a.userId ? html`<div class="row nowrap" style="gap:8px;flex-wrap:nowrap">${UI.avatar(a.userId, 'av-sm')}${Data.userName(a.userId)}</div>` : html`<span class="faint">النظام</span>`}</td><td>${UI.chip(ACT_TONE[a.action] || 'slate', ACT_LABEL[a.action] || a.action, ACT_ICON[a.action] || 'pulse')}</td><td>${a.summary}</td></tr>`)}</tbody></table></div>${UI.pager({ offset: st.offset, limit: st.limit, count: rows.length, hasMore })}` : UI.empty({ illu: 'cctv', title: 'لا يوجد نشاط مطابق', text: 'غيّر عوامل التصفية.' }));
  };
  [['aUser', 'user'], ['aAct', 'action'], ['aFrom', 'from'], ['aTo', 'to']].forEach(([id, k]) => { $('#' + id, ctx.view).onchange = (e) => { st[k] = e.target.value; st.offset = 0; load(); }; });
  UI.on(ctx.view, 'click', '[data-page]', (e, el) => { st.offset = Math.max(0, st.offset + (el.dataset.page === 'next' ? st.limit : -st.limit)); load(); });
  UI.on(ctx.view, 'click', '[data-act="csv"]', async () => { const { rows } = await DB.page('activity', opts(true)); downloadBlob(new Blob([toCSV(rows, [{ label: 'الوقت', value: (a) => fmtDateTime(a.at) }, { label: 'المستخدم', value: (a) => Data.userName(a.userId) }, { label: 'العملية', key: 'action' }, { label: 'الكيان', key: 'entity' }, { label: 'التفاصيل', key: 'summary' }])], { type: 'text/csv;charset=utf-8' }), `سجل-النشاط-${dateInput(now())}.csv`); });
  await load();
};

