Pages.live = async (ctx, draw, boardOpts) => {
  await draw(); if (!ctx.alive()) return;
  Pages.bindCommon(ctx);
  let dirty = false, busy = false;
  const mark = () => { dirty = true; };
  ctx.onCleanup(Bus.on('tickets', mark)); ctx.onCleanup(Bus.on('inventory', mark));
  if (boardOpts) ctx.onCleanup(Bus.on('tickets', debounce(() => { const el = $('#board', ctx.view); if (ctx.alive() && el) Board.render(el, boardOpts); }, 500)));
  const tick = setInterval(async () => {
    if (!dirty || busy || !ctx.alive() || document.hidden || $('dialog[open]') || $('.cmdk') || now() - (Pages.lastMove || 0) < 4000) return;
    busy = true; dirty = false; const y = window.scrollY;
    ctx.view.classList.remove('page-in'); ctx.view.classList.add('quiet');
    try { await draw(); if (ctx.alive()) { UI.hydrate(ctx.view); window.scrollTo(0, y); } } catch (e) { console.warn('live refresh', e); }
    busy = false;
  }, 25000);
  ctx.onCleanup(() => clearInterval(tick));
};
