Data.sample.load = async function ({ tickets = 400, items = 60 } = {}) {
  const t = now(), me = Auth.user, rnd = Math.random, int = (a, b) => a + Math.floor(rnd() * (b - a + 1)), pick = (a) => a[Math.floor(rnd() * a.length)];
  const wpick = (pairs) => { let r = rnd() * pairs.reduce((s, p) => s + p[1], 0); for (const [v, w] of pairs) { r -= w; if (r < 0) return v; } return pairs[pairs.length - 1][0]; };
  const deps = Data.list('departments'), cats = Data.list('categories'), itDep = (deps.find((d) => /تقنية/.test(d.name)) || deps[0] || {}).id || '';
  const demoUser = async (username, name, role, departmentId, phone = '') => { if ((await DB.getAll('users', 'username', KR(username))).length) return; await DB.put('users', { id: uid('u'), username, name, role, departmentId, locationId: (pick(Data.list('locations')) || {}).id || '', office: `مكتب ${int(101, 340)}`, rankId: '', militaryNo: '', phone, email: '', active: 1, mustChangePassword: 1, pass: null, createdAt: t, updatedAt: t, lastLoginAt: 0, demo: 1 }); };
  let staff = Data.list('users').filter((u) => u.active && ['technician', 'support_manager'].includes(u.role));
  if (staff.length < 3) {
    for (const [name, username] of [['سالم بن خميس الحارثي', 'demo.salim'], ['يوسف بن أحمد البلوشي', 'demo.yousuf'], ['مريم بنت سعيد الكندية', 'demo.maryam'], ['حمد بن علي الشكيلي', 'demo.hamad']]) await demoUser(username, name, 'technician', itDep);
    await Data.refresh('users'); staff = Data.list('users').filter((u) => u.active && ['technician', 'support_manager'].includes(u.role));
  }
  let people = Data.list('users').filter((u) => u.active && u.role === 'department');
  if (people.length < 5) {
    const emp = [['خالد بن سيف المعمري', 'المالية'], ['عائشة بنت محمد الرواحية', 'الموارد البشرية'], ['ناصر بن حمود السعدي', 'الشؤون الإدارية'], ['فاطمة بنت راشد العبرية', 'ضمان الجودة'], ['سعيد بن مبارك الغافري', 'الكلية'], ['هدى بنت عبدالله الزدجالية', 'مركز البحوث والدراسات'], ['أحمد بن سالم المقبالي', 'العلاقات'], ['عبدالعزيز بن خلفان الوهيبي', 'مكتب القائد']];
    for (const [i, [name, depName]] of emp.entries()) { const dep = deps.find((d) => d.name === depName) || pick(deps); await demoUser(`demo.emp${i + 1}`, name, 'department', dep ? dep.id : '', `9${int(1000000, 9999999)}`); }
    await Data.refresh('users'); people = Data.list('users').filter((u) => u.active && u.role === 'department');
  }
  const requesters = people.length ? people : [me];
  /* البلاغات مع مسار زمني كامل */
  const sla = Data.c.settings.sla, rows = [], evs = [];
  let seq = ((await DB.get('meta', 'seq:ticket')) || { value: 0 }).value;
  for (let i = 0; i < tickets; i++) {
    let created = 0;
    for (let k = 0; k < 8; k++) { const day = new Date(startOfDay(t) - Math.floor(Math.pow(rnd(), 1.25) * 90) * DAY); day.setHours(wpick([[7, 3], [8, 9], [9, 12], [10, 12], [11, 10], [12, 8], [13, 7], [14, 4], [15, 2], [16, 1.5], [18, 0.6], [20, 0.4], [22, 0.2]]), int(0, 59)); created = day.getTime(); const dow = day.getDay(); if (created <= t && !((dow === 5 || dow === 6) && rnd() < 0.85)) break; }
    if (created > t) created = t - int(5, 300) * MIN;
    const age = t - created, pr = wpick([['low', 2], ['medium', 5], ['high', 2.4], ['urgent', 0.9]]), S = sla[pr], cat = pick(cats), req = pick(requesters);
    const st = age < 6 * HOUR ? wpick([['new', 5], ['assigned', 2], ['in_progress', 2], ['resolved', 0.5]]) : age < 2 * DAY ? wpick([['new', 1.2], ['assigned', 1.5], ['in_progress', 2.5], ['waiting', 1], ['resolved', 3], ['closed', 1]]) : age < 10 * DAY ? wpick([['in_progress', 0.5], ['waiting', 0.5], ['resolved', 1.5], ['closed', 6], ['cancelled', 0.3]]) : wpick([['closed', 12], ['resolved', 0.5], ['cancelled', 0.5]]);
    const tech = pick(staff), assigneeId = st === 'new' || (st === 'cancelled' && rnd() < 0.6) || !tech ? '' : tech.id;
    const first = assigneeId ? Math.min(t - MIN, created + Math.round((0.15 + rnd() * 1.1) * S.respond * MIN)) : 0;
    let resolvedAt = 0, closedAt = 0;
    if (st === 'resolved' || st === 'closed') { resolvedAt = created + Math.round(wpick([[0.2, 3], [0.45, 4], [0.75, 3], [1.15, 1.1], [2, 0.7]]) * (0.75 + rnd() * 0.5) * S.resolve * MIN); if (resolvedAt <= first) resolvedAt = first + int(15, 90) * MIN; if (resolvedAt >= t) resolvedAt = t - int(2, 30) * MIN; }
    if (st === 'closed') closedAt = Math.max(resolvedAt + MIN, Math.min(t - MIN, resolvedAt + int(1, 36) * HOUR));
    const rating = st === 'closed' && rnd() < 0.72 ? wpick([[5, 6], [4, 3.2], [3, 1], [2, 0.3], [1, 0.15]]) : 0;
    seq++;
    const r = { id: uid('t'), number: `IT-${new Date(created).getFullYear()}-${pad(seq, 5)}`, legacyId: '', title: pick(S_TITLES[cat.id] || S_TITLES.other), description: pick(S_DESC), categoryId: cat.id, priority: pr, status: st, requesterId: req.id, departmentId: req.departmentId || pick(deps).id, assigneeId, locationId: req.locationId || '', location: req.office || `مكتب ${int(101, 340)}`, contact: req.phone || '', deviceName: rnd() < 0.5 ? `PC-${int(1000, 9999)}` : '', assetTag: '', extra: cat.id === 'printer' ? { printerBrand: pick(['HP', 'Kyocera', 'Canon', 'Ricoh']), printerModel: '' } : null, createdAt: created, updatedAt: closedAt || resolvedAt || first || created, respondBy: created + S.respond * MIN, dueAt: created + S.resolve * MIN, firstResponseAt: first, resolvedAt, closedAt, rating, ratingComment: rating >= 4 && rnd() < 0.4 ? pick(['شكراً على سرعة الاستجابة', 'خدمة ممتازة', 'تم الحل بشكل احترافي']) : rating && rating <= 2 ? 'تأخر الحل عن المتوقع' : '', attachmentCount: 0, sample: 1 };
    r.openDue = OPEN.includes(st) ? r.dueAt : 0; r.search = Data.tickets.searchOf(r); rows.push(r);
    const E = (o) => evs.push({ id: uid('ev'), ticketId: r.id, text: '', ...o });
    E({ type: 'created', at: created, userId: req.id });
    if (assigneeId) E({ type: 'assigned', at: first, userId: assigneeId, from: '', to: assigneeId });
    if (assigneeId && ['in_progress', 'waiting', 'resolved', 'closed'].includes(st)) E({ type: 'status', at: first + 3 * MIN, userId: assigneeId, from: 'assigned', to: 'in_progress' });
    if (st === 'waiting') E({ type: 'status', at: Math.min(t - MIN, first + int(20, 180) * MIN), userId: assigneeId, from: 'in_progress', to: 'waiting', text: pick(['بانتظار توفر قطعة الغيار من المخزن', 'بانتظار رد المستفيد لتحديد موعد الزيارة', 'بانتظار موافقة القسم المختص']) });
    if (resolvedAt) { if (rnd() < 0.5) E({ type: 'comment', at: first + int(5, 30) * MIN, userId: assigneeId, text: pick(['تم التواصل مع المستفيد وجاري الفحص', 'سيتم الحضور إلى المكتب خلال ساعة', 'تم فحص الجهاز عن بُعد']) }); E({ type: 'status', at: resolvedAt, userId: assigneeId, from: 'in_progress', to: 'resolved', text: pick(S_RES[cat.id] || S_RES.other) }); }
    if (closedAt) E({ type: 'status', at: closedAt, userId: req.id, from: 'resolved', to: 'closed' });
    if (rating) E({ type: 'rating', at: closedAt, userId: req.id, stars: rating, text: r.ratingComment });
    if (st === 'cancelled') E({ type: 'status', at: Math.min(t - MIN, created + int(30, 600) * MIN), userId: req.id, from: 'new', to: 'cancelled', text: 'تم حل المشكلة ذاتياً' });
  }
  await DB.bulkPut('tickets', rows); await DB.bulkPut('ticketEvents', evs); await DB.put('meta', { key: 'seq:ticket', value: seq });
  /* المخازن والأصناف و60 يوماً من الحركات والعهد */
  let movesN = 0, loansN = 0;
  if (items > 0) {
    let whs = Data.list('warehouses');
    for (const [name, location, keeper] of [['مخزن الصيانة', 'مبنى تقنية المعلومات - الطابق الأرضي', 'أمين مخزن الصيانة'], ['مخزن الكلية', 'مبنى الكلية - الجناح الشرقي', 'أمين مخزن الكلية']]) { if (whs.length >= 3) break; if (!whs.some((w) => w.name === name)) { await Data.saveRecord('warehouses', { name, location, keeper, sample: 1 }, 'مخزن'); whs = Data.list('warehouses'); } }
    const icId = new Map(Data.list('itemCategories').map((c) => [String(c.id).replace(/^ic_/, ''), c.id])), catKeys = Object.keys(S_CATALOG).filter((k) => icId.has(k)), all = catKeys.flatMap((k) => S_CATALOG[k].map((e) => [k, icId.get(k), ...e])), main = whs[0].id, keepers = staff.length ? staff : [me];
    const its = [], stockRows = [], moves = [], loans = [], deptRows = [];
    let iseq = ((await DB.get('meta', 'seq:item')) || { value: 0 }).value;
    {
      let seq = ((await DB.get('meta', 'seq:loan')) || { value: 0 }).value;
      for (let n = 0; n < items && all.length; n++) {
        const [ck, catId, baseName, brand, model, minQty] = all[n % all.length], dup = Math.floor(n / all.length), loanable = S_LOANABLE.includes(ck); iseq++;
        const it = { id: uid('it'), sku: `ITM-${pad(iseq, 5)}`, name: dup ? `${baseName} — دفعة ${dup + 1}` : baseName, categoryId: catId, unit: ck === 'ink' ? 'علبة' : 'قطعة', minQty, brand, model, serial: loanable ? `5CD${int(1000000, 9999999)}` : '', notes: '', onHand: 0, createdAt: t - 62 * DAY, updatedAt: t - n * MIN, sample: 1 };
        const bal = new Map(), add = (wh, d) => { bal.set(wh, (bal.get(wh) || 0) + d); return bal.get(wh); }, pending = [], dq = new Map();
        const mv = (o) => moves.push({ id: uid('mv'), itemId: it.id, note: '', ref: '', party: '', departmentId: '', userId: pick(keepers).id, ...o });
        const flush = (until) => { pending.sort((a, b) => a.at - b.at); while (pending.length && pending[0].at <= until) { const p = pending.shift(); mv({ ...p.o, balance: add(p.o.warehouseId, 1) }); } };
        let at = t - 60 * DAY + int(0, 4) * DAY + int(8, 13) * HOUR;
        const q0 = Math.max(minQty * 3, 3) + int(0, minQty * 2 + 2);
        mv({ type: 'receive', at, warehouseId: main, qty: q0, delta: q0, balance: add(main, q0), party: pick(S_SUPPLIERS), ref: `PO-${int(1000, 9999)}`, note: 'توريد ضمن العقد السنوي' });
        for (;;) {
          at += Math.round((0.4 + rnd() * (loanable ? 7 : 4)) * DAY); flush(Math.min(at, t - HOUR)); if (at > t - HOUR) break;
          const total = [...bal.values()].reduce((a, b) => a + b, 0), fromWh = [...bal.entries()].filter(([, q]) => q > 0).map(([w]) => w);
          const act = total <= minQty ? 'restock' : wpick([['issue', loanable ? 3 : 7], ['transfer', whs.length > 1 ? 1.2 : 0], ['loan', loanable ? 1.4 : 0], ['adjust', 0.3]]);
          if (act === 'restock') { const q = minQty * 2 + int(2, 8); mv({ type: 'receive', at, warehouseId: main, qty: q, delta: q, balance: add(main, q), party: pick(S_SUPPLIERS), ref: `PO-${int(1000, 9999)}`, note: 'إعادة توريد بعد انخفاض الرصيد' }); }
          else if (act === 'issue' && fromWh.length) { const w = pick(fromWh), q = Math.min(bal.get(w), int(1, ck === 'cable' || ck === 'ink' ? 4 : 2)), who = pick(requesters), tk = rows.length && rnd() < 0.45 ? pick(rows) : null; mv({ type: 'issue', at, warehouseId: w, qty: q, delta: -q, balance: add(w, -q), departmentId: who.departmentId || '', party: who.name, ref: tk ? tk.number : '' }); if (who.departmentId) dq.set(who.departmentId, (dq.get(who.departmentId) || 0) + q); }
          else if (act === 'transfer' && (bal.get(main) || 0) > 2 && whs.length > 1) { const to = pick(whs.slice(1)).id, q = int(1, Math.min(5, bal.get(main) - 1)); mv({ type: 'transfer_out', at, warehouseId: main, qty: q, delta: -q, balance: add(main, -q), note: `تحويل إلى ${Data.nameOf('warehouses', to)}` }); mv({ type: 'transfer_in', at: at + MIN, warehouseId: to, qty: q, delta: q, balance: add(to, q), note: `تحويل من ${Data.nameOf('warehouses', main)}` }); }
          else if (act === 'loan' && fromWh.length) {
            const w = pick(fromWh), who = pick(requesters); seq++;
            const dueAt = rnd() < 0.25 ? 0 : at + int(10, 45) * DAY, back = rnd() < 0.85 ? at + int(2, dueAt ? Math.max(3, Math.round((dueAt - at) / DAY)) : 30) * DAY : 0, returned = !!back && back < t - HOUR;
            const loan = { id: uid('ln'), number: `LN-${pad(seq, 5)}`, itemId: it.id, itemName: it.name, warehouseId: w, qty: 1, returnedQty: returned ? 1 : 0, borrower: who.name, departmentId: who.departmentId || '', issuedAt: at, dueAt, status: returned ? 'returned' : 'active', note: pick(['لمهمة عمل خارجية', 'للاستخدام في قاعة التدريب', 'بديل مؤقت لجهاز قيد الصيانة', 'لعرض تقديمي']), userId: pick(keepers).id, returnedAt: returned ? back : 0, sample: 1 };
            loans.push(loan); mv({ type: 'loan_out', at, warehouseId: w, qty: 1, delta: -1, balance: add(w, -1), party: who.name, departmentId: loan.departmentId, ref: loan.number });
            if (returned) pending.push({ at: back, o: { type: 'loan_return', at: back, warehouseId: w, qty: 1, delta: 1, party: who.name, departmentId: loan.departmentId, ref: loan.number, note: 'أُعيد بحالة سليمة' } });
          }
          else if (act === 'adjust' && (bal.get(main) || 0) > 1) { const d = rnd() < 0.5 ? -1 : 1; mv({ type: 'adjust', at, warehouseId: main, qty: 1, delta: d, balance: add(main, d), note: 'تسوية بعد الجرد الدوري' }); }
        }
        flush(t - HOUR);
        it.onHand = [...bal.values()].reduce((a, b) => a + b, 0);
        bal.forEach((qty, warehouseId) => stockRows.push({ warehouseId, itemId: it.id, qty, updatedAt: t }));
        dq.forEach((qty, departmentId) => deptRows.push({ departmentId, itemId: it.id, qty, updatedAt: t }));
        it.search = Data.inv.searchOf(it); its.push(it);
      }
      await DB.put('meta', { key: 'seq:loan', value: seq });
    }
    await DB.bulkPut('items', its); await DB.bulkPut('stock', stockRows); await DB.bulkPut('deptStock', deptRows); await DB.bulkPut('movements', moves); await DB.bulkPut('loans', loans); await DB.put('meta', { key: 'seq:item', value: iseq });
    movesN = moves.length; loansN = loans.length;
  }
  await Data.log('create', 'system', '', `تحميل بيانات تجريبية: ${arCount(tickets, AR.ticket)} و${arCount(items, AR.item)}`);
  Bus.emit('tickets', {}); Bus.emit('inventory', {});
  return { tickets: rows.length, events: evs.length, items, movements: movesN, loans: loansN };
};

Data.sample.clear = async () => {
  const collect = async (store, pred, key = (r) => r.id) => { const keys = []; await DB.each(store, {}, (r) => { if (pred(r)) keys.push(key(r)); }); for (const k of keys) await DB.del(store, k); return keys.length; };
  const tIds = new Set(), iIds = new Set();
  await DB.each('tickets', {}, (x) => { if (x.sample) tIds.add(x.id); });
  await DB.each('items', {}, (x) => { if (x.sample) iIds.add(x.id); });
  const n = {
    tickets: await collect('tickets', (x) => x.sample), events: await collect('ticketEvents', (e) => tIds.has(e.ticketId)),
    items: await collect('items', (x) => x.sample), stock: await collect('stock', (s) => iIds.has(s.itemId), (s) => [s.warehouseId, s.itemId]),
    movements: await collect('movements', (m) => iIds.has(m.itemId)), loans: await collect('loans', (l) => iIds.has(l.itemId)),
    users: await collect('users', (u) => u.demo && (!Auth.user || u.id !== Auth.user.id)), warehouses: 0
  };
  for (const w of Data.list('warehouses').filter((x) => x.sample)) { if (!(await DB.count('stock', 'warehouseId', KR(w.id)))) { await DB.del('warehouses', w.id); n.warehouses++; } }
  await Data.refresh(); await Data.log('delete', 'system', '', `حذف البيانات التجريبية: ${arCount(n.tickets, AR.ticket)} و${arCount(n.items, AR.item)}`);
  Bus.emit('tickets', {}); Bus.emit('inventory', {});
  return n;
};

