const PERM_KEYS = new Set(PERM_GROUPS.flatMap((g) => g.items.map((i) => i[0])));
const PERM_LABEL = Object.fromEntries(PERM_GROUPS.flatMap((g) => g.items.map((i) => [i[0], i[1]])));
const roleDefaults = (role) => (PERMS[role] || []).filter((p) => PERM_KEYS.has(p));
const canUser = (u, perm) => {
  if (!perm) return true;
  if (!u) return false;
  if (u.role === 'monitor') return perm === 'monitor';
  const p = PERMS[u.role] || [];
  if (p.includes('*')) return true;
  /* رئاسة إدارة أو فرع: صلاحية مشتقة من الهيكل نفسه، لا تُمنح من شاشة الصلاحيات */
  if (perm === 'org.head') return OrgScope.heads(u.id);
  if ((u.deniedPerms || []).includes(perm)) return false;
  return p.includes(perm) || (u.extraPerms || []).includes(perm);
};
const effPerms = (u) => (u.role === 'supervisor' ? [...PERM_KEYS] : [...PERM_KEYS].filter((k) => canUser(u, k)));
Data.tickets.staffIds = () => Data.list('users').filter((u) => u.active && canUser(u, 'tickets.work')).map((u) => u.id);
