  const terms = [get('ink'), get('model'), get('brand'), get('device'), t.deviceName].map((x) => String(x || '').trim()).filter(Boolean);
  const found = new Map();
  for (const term of terms) { const { rows } = await Data.inv.items({ q: term, limit: 4 }); rows.forEach((r) => found.set(r.id, r)); if (found.size >= 4) break; }
  const rows = [...found.values()].slice(0, 4), qty = Math.max(1, Number(get('qty')) || 1), canMove = Auth.can('inventory.move') && OPEN.includes(t.status);
