UI.serialPick = (assets, need) => html`<div class="field"><label class="row" style="justify-content:space-between"><span>اختر الوحدات <span class="faint small">(المطلوب ${fmtNum(need)} من ${fmtNum(assets.length)})</span></span><button type="button" class="btn btn-ghost btn-sm" data-scanfor="pick">${UI.icon('search')} مسح رمز</button></label><div class="chip-pick serial-pick">${assets.map((a) => html`<label><input type="checkbox" data-pick="${a.id}"><span>${UI.icon('tag')}${a.serial}${a.tag ? ` (${a.tag})` : ''}</span></label>`)}</div><small class="hint">اختر الأجهزة بأرقامها ليُسجَّل خروجها من المخزن.</small></div>`;

/* ملصقات الباركود (Code 39) */
const C39 = { '0': '101001101101', '1': '110100101011', '2': '101100101011', '3': '110110010101', '4': '101001101011', '5': '110100110101', '6': '101100110101', '7': '101001011011', '8': '110100101101', '9': '101100101101', A: '110101001011', B: '101101001011', C: '110110100101', D: '101011001011', E: '110101100101', F: '101101100101', G: '101010011011', H: '110101001101', I: '101101001101', J: '101011001101', K: '110101010011', L: '101101010011', M: '110110101001', N: '101011010011', O: '110101101001', P: '101101101001', Q: '101010110011', R: '110101011001', S: '101101011001', T: '101011011001', U: '110010101011', V: '100110101011', W: '110011010101', X: '100101101011', Y: '110010110101', Z: '100110110101', '-': '100101011011', '.': '110010101101', ' ': '100110101101', '*': '100101101101' };
UI.barcode = (text, { height = 42, w = 1.6 } = {}) => {
  const s = `*${String(text || '').toUpperCase().replace(/[^0-9A-Z\-. ]/g, '-')}*`, bars = [];
  let x = 0;
  for (const ch of s) { const p = C39[ch] || C39['-']; for (let i = 0; i < p.length; i++) { const wide = p[i] === '1' ? w * 2.2 : w; if (i % 2 === 0) bars.push(`<rect x="${x.toFixed(2)}" y="0" width="${wide.toFixed(2)}" height="${height}" fill="#000"/>`); x += wide; } x += w; }
  return raw(`<svg class="barcode" viewBox="0 0 ${Math.ceil(x)} ${height}" width="${Math.ceil(x)}" height="${height}" preserveAspectRatio="xMidYMid meet">${bars.join('')}</svg>`);
};
Pages.printLabels = (item, assets) => UI.print(html`<h2>ملصقات ${item.name}</h2><div class="label-sheet">${assets.map((a) => html`<div class="label"><b>${item.name}</b><span>${[item.brand, item.model].filter(Boolean).join(' ')}</span>${UI.barcode(a.serial)}<span class="ltr">${a.serial}</span></div>`)}</div>`, `ملصقات ${item.name}`);

