  monitor: [{ k: 'size', l: 'المقاس', o: ['19 بوصة', '22 بوصة', '24 بوصة', '27 بوصة', '32 بوصة'] }, { k: 'ports', l: 'المنافذ', o: ['VGA', 'HDMI', 'DisplayPort', 'متعدد'] }],
