/* الرقم التسلسلي ورقم الأصل معاً */
UI.serialBox = (qty, values = []) => html`<div class="serial-wrap"><div class="row" style="justify-content:space-between;margin-bottom:8px"><b class="small">${UI.icon('tag')} الأرقام التسلسلية وأرقام الأصل <span class="faint">(${fmtNum(qty)})</span></b><span class="row" style="gap:6px"><button type="button" class="btn btn-ghost btn-sm" data-sn="paste" data-snmode="serial">${UI.icon('clip')} لصق الأرقام التسلسلية</button><button type="button" class="btn btn-ghost btn-sm" data-sn="paste" data-snmode="tag">${UI.icon('clip')} لصق أرقام التاج</button><button type="button" class="btn btn-ghost btn-sm" data-sn="auto">${UI.icon('refresh')} ترقيم تلقائي</button></span></div>
  <div class="serial-grid" data-sn-grid>${Array.from({ length: qty }, (_, i) => { const v = values[i] || {}; const sv = typeof v === 'string' ? { serial: v } : v; return html`<div class="serial-cell"><span>${i + 1}</span><div class="sc-inputs"><input name="sn_${i}" value="${sv.serial || ''}" dir="ltr" autocomplete="off" placeholder="الرقم التسلسلي S/N"><input name="tg_${i}" value="${sv.tag || ''}" dir="ltr" autocomplete="off" placeholder="رقم الأصل / التاج"><input name="hn_${i}" value="${sv.host || ''}" dir="ltr" autocomplete="off" placeholder="اسم الجهاز على الشبكة (اختياري) NZW…"></div></div>`; })}</div>
  <label class="row" style="gap:6px;margin-top:10px;font-size:12.5px;cursor:pointer"><input type="checkbox" name="noSerial"><span>هذه الوحدات بدون أرقام تسلسلية</span></label>
  <small class="hint">يكفي إدخال أحدهما: الرقم التسلسلي أو رقم الأصل، ويمكن إدخالهما معاً. لا يقبل النظام رقماً تسلسلياً أو رقم أصل أو اسم جهاز مسجلاً من قبل.</small></div>`;
UI.serialPairs = (root) => $$('[name^="sn_"]', root).map((inp) => { const i = inp.name.slice(3), val = (k) => String((root.querySelector(`[name="${k}_${i}"]`) || {}).value || '').trim(); return { serial: String(inp.value || '').trim(), tag: val('tg'), host: val('hn') }; }).filter((p) => p.serial || p.tag);
UI.serialValues = (root) => UI.serialPairs(root).map((p) => p.serial || p.tag);
/* منع تكرار الرقم التسلسلي ورقم الأصل واسم الجهاز على الشبكة: لا يُسجل جهاز برقم موجود مسبقاً */
Data.assets.norm = (v) => String(v || '').trim().toUpperCase().replace(/\s+/g, '');
Data.assets.index = async () => {
  const all = await DB.getAll('assets'), ids = new Map(), hosts = new Map(), N = Data.assets.norm;
  for (const a of all) { [a.serial, a.tag].forEach((v) => { const k = N(v); if (k && !ids.has(k)) ids.set(k, a); }); const h = N(a.host); if (h && !hosts.has(h)) hosts.set(h, a); }
  return { ids, hosts };
};
Data.assets.problems = async (pairs, idx = null) => {
  const N = Data.assets.norm, { ids, hosts } = idx || (await Data.assets.index()), out = [], seenIds = new Set(), seenHosts = new Set();
  const where = async (a) => { const it = await DB.get('items', a.itemId).catch(() => null); return it ? it.name : 'جهاز آخر'; };
  for (const p of pairs) {
    const keys = [...new Set([p.serial, p.tag].map(N).filter(Boolean))];
    for (const k of keys) { const shown = [p.serial, p.tag].find((v) => N(v) === k); if (seenIds.has(k)) out.push({ value: shown, msg: `«${shown}» مكرر في القائمة نفسها` }); else if (ids.has(k)) out.push({ value: shown, msg: `«${shown}» مسجل مسبقاً على ${await where(ids.get(k))}` }); seenIds.add(k); }
    const h = N(p.host);
    if (h) { if (seenHosts.has(h)) out.push({ value: p.host, msg: `اسم الجهاز «${p.host}» مكرر في القائمة نفسها` }); else if (hosts.has(h)) out.push({ value: p.host, msg: `اسم الجهاز «${p.host}» مستخدم لجهاز آخر (${await where(hosts.get(h))})` }); seenHosts.add(h); }
  }
  return out;
};
Data.assets.check = async (pairs) => {
  const bad = await Data.assets.problems(pairs);
  if (bad.length) throw new AppError(`لا يمكن التسجيل لوجود تكرار: ${bad.slice(0, 3).map((x) => x.msg).join('، ')}${bad.length > 3 ? ` و${fmtNum(bad.length - 3)} غيرها` : ''}`);
};
Data.assets.add = async ({ itemId, warehouseId, serials = [], note = '' }) => {
  const pairs = serials.map((s) => (typeof s === 'string' ? { serial: s, tag: '', host: '' } : s)).filter((p) => p.serial || p.tag);
  await Data.assets.check(pairs);
  const t = now(), rows = pairs.map((p) => ({ id: uid('as'), itemId, serial: p.serial || p.tag, tag: p.tag || '', host: String(p.host || '').trim(), status: 'in_store', warehouseId, departmentId: '', holder: '', holderId: '', loanId: '', note, addedAt: t, updatedAt: t }));
  if (rows.length) await DB.bulkPut('assets', rows);
  return { added: rows.length, dupes: [] };
};
/* تصفية المتواجدين الآن حسب نوع الحساب (للمشرف) */
document.addEventListener('click', (e) => { if (e.target.closest('#presPop [data-presretry]')) { e.preventDefault(); e.stopPropagation(); if (Presence.refresh) Presence.refresh(); return; } const f = e.target.closest('[data-presf]'); if (!f || !f.closest('#presPop')) return; e.preventDefault(); e.stopPropagation(); e.stopImmediatePropagation(); const r = f.dataset.presf; Presence.flt = Presence.flt === r ? '' : r; Presence.fill(); });
/* البحث بالرقم التسلسلي يشمل رقم الأصل واسم الجهاز على الشبكة */
{ const bs = Data.assets.bySerial; Data.assets.bySerial = async (v) => { const a = await bs(v); if (a) return a; const k = Data.assets.norm(v); if (!k) return null; return (await DB.getAll('assets')).find((x) => [x.serial, x.tag, x.host].some((y) => Data.assets.norm(y) === k)) || null; }; }
/* تنبيه فوري على الخانة المكررة أثناء الكتابة */
document.addEventListener('focusout', async (e) => {
  const inp = e.target; if (!inp.matches || !inp.matches('[data-sn-grid] input')) return;
  const grid = inp.closest('[data-sn-grid]'), root = grid.closest('form') || grid.parentElement;
  const bad = await Data.assets.problems(UI.serialPairs(root)), N = Data.assets.norm, badSet = new Map(bad.map((x) => [N(x.value), x.msg]));
  $$('input', grid).forEach((el) => { const m = badSet.get(N(el.value)); el.classList.toggle('sn-dup', !!m && !!el.value.trim()); el.title = m && el.value.trim() ? m : ''; });
});

/* تحديث قائمة الرتب عند فتح نموذج البطاقات */
