/* إدارة كلمات المرور حسب الدور */
const canSetPassword = (actor, target) => {
  if (!actor || !target || actor.id === target.id) return false;
  if (actor.role === 'supervisor' || canUser(actor, 'users.manage')) return true;
  if (!canUser(actor, 'users.password')) return false;
  if (actor.role === 'support_manager') return ['department', 'technician'].includes(target.role);
  /* الفني، والموظف الذي مُنح «كلمات المرور»: حسابات الموظفين فقط (كانت الصلاحية لا تعمل للموظف) */
  if (['technician', 'department'].includes(actor.role)) return target.role === 'department';
  return false;
};
Data.users.setPassword = async (id, password, mustChange = 0) => {
  const target = await DB.get('users', id); if (!target) throw new AppError('الحساب غير موجود');
  /* المستخدم يغيّر كلمة مروره بنفسه (أول دخول أو من الملف الشخصي) بشرط السياسة الكاملة */
  const self = !!Auth.user && Auth.user.id === id;
  if (!self && !canSetPassword(Auth.user, target)) throw new AppError('لا تملك صلاحية تغيير كلمة مرور هذا الحساب');
  const pw = self ? String(password || '') : String(password || '').trim();
  if (self) Data.users.checkPolicy(pw); else if (pw.length < 6) throw new AppError('كلمة المرور 6 أحرف على الأقل');
  target.pass = Crypto.makePassword(pw); target.mustChangePassword = pwForce() && mustChange ? 1 : 0; target.updatedAt = now();
  await DB.put('users', target); await Data.refresh('users');
  await Data.log('password', 'user', id, self ? 'تغيير كلمة المرور الشخصية' : `تعيين كلمة مرور لحساب ${target.name}`);
  if (self) Auth.user = target;
  else await Data.notify([id], { title: 'تم تعيين كلمة مرور جديدة لحسابك', body: `راجع من أصدرها لاستلامها${pwForce() ? '، وسيُطلب منك تغييرها عند الدخول' : ''}.`, link: '/profile', kind: 'user' });
  Bus.emit('users', {});
  return pw;
};
const randomPw = () => Crypto.tempPassword();

