/* ── شارات الرتب، أيقونات خيارات الفئات، حقول برنامج مسار ── */
/* شارات الرتب: صور كتّافات شرطة عُمان السلطانية (مقتطعة من اللوحة المرجعية ومضمّنة في الملف) */
const RANK_IMG = {"ملازم": "data:image/webp;base64,","ملازم أول": "data:image/webp;base64,","نقيب": "data:image/webp;base64,","رائد": "data:image/webp;base64,","مقدم": "data:image/webp;base64,","عقيد": "data:image/webp;base64,","عميد": "data:image/webp;base64,","لواء": "data:image/webp;base64,","فريق": "data:image/webp;base64,","شرطي": "data:image/webp;base64,","عريف": "data:image/webp;base64,","رقيب": "data:image/webp;base64,","رقيب أول": "data:image/webp;base64,","وكيل": "data:image/webp;base64,","وكيل أول": "data:image/webp;base64,"};
const RANK_CIVIL = '<svg class="rank-badge" viewBox="0 0 30 46" width="{w}" height="{h}" role="img" aria-label="مدني"><path d="M2.5 44.5V10.5Q2.5 3 15 2.5Q27.5 3 27.5 10.5V44.5Z" fill="#2B3650" stroke="#6F86A8"/><circle cx="15" cy="19" r="4.2" fill="#9DB2CF"/><path d="M7.5 34a7.5 7.5 0 0 1 15 0z" fill="#9DB2CF"/></svg>';
UI.rankIcon = (rank, size = 34) => {
  const k = String(rank || '').trim(), src = RANK_IMG[k];
  if (src) return raw(`<img class="rank-badge rank-img" src="${src}" alt="${esc(k)}" title="${esc(k)}" height="${size}" style="height:${size}px;width:auto">`);
  if (k === 'مدني') return raw(RANK_CIVIL.replace('{w}', ((size * 30) / 46).toFixed(1)).replace('{h}', size));
  return raw('');
};
UI.rankPickList = (name, value = '') => html`<div class="rank-pick">${Data.list('ranks').map((r) => html`<label><input type="radio" name="${name}" value="${r.name}"${value === r.name ? raw(' checked') : ''}><span>${UI.rankIcon(r.name, 52)}<b>${r.name}</b></span></label>`)}</div>`;
UI.rankPick = (name, value = '') => html`<div class="field wide"><label>الرتبة</label>${UI.rankPickList(name, value)}</div>`;

