/* حقول برنامج مسار: عدة أشخاص بأسمائهم وأرقامهم */
Forms.codeBlock = (list = []) => html`<div class="persons-box" data-codes>
  <div class="row" style="justify-content:space-between;align-items:center;margin-bottom:8px"><b class="small">${UI.icon('users')} الأشخاص المطلوب إصدار رمز لهم</b><span class="row" style="gap:6px"><input class="qty-in" type="number" min="1" max="30" value="${Math.max(1, list.length || 1)}" data-codecount aria-label="عدد الأشخاص"><button type="button" class="btn btn-ghost btn-sm" data-act="setcodes">${UI.icon('refresh')} تجهيز الخانات</button></span></div>
  <div class="persons-list">${(list.length ? list : [{}]).map((p, i) => Forms.codeRow(p, i))}</div>
  <small class="hint">اكتب عدد الأشخاص ثم اضغط «تجهيز الخانات» لتظهر خانة اسم ورقم عسكري لكل شخص.</small></div>`;
Forms.codeRow = (p = {}, i = 0) => html`<div class="person-row" data-code="${i}">
  <input name="cn_${i}" value="${p.name || ''}" placeholder="الاسم الكامل">
  <input name="cm_${i}" value="${p.militaryNo || ''}" placeholder="الرقم العسكري" dir="ltr">
  <button type="button" class="icon-btn" data-delcode="${i}" aria-label="حذف">${UI.icon('trash')}</button></div>`;
Forms.readCodes = (root) => {
  const out = [];
  $$('[data-code]', root).forEach((row) => {
    const i = row.dataset.code, name = String((root.querySelector(`[name="cn_${i}"]`) || {}).value || '').trim();
    const no = String((root.querySelector(`[name="cm_${i}"]`) || {}).value || '').trim();
    if (name || no) out.push({ name, militaryNo: no });
  });
  return out;
};
document.addEventListener('click', (e) => {
  const set = e.target.closest('[data-act="setcodes"]');
  if (set) {
    const box = set.closest('[data-codes]'); if (!box) return;
    const n = clamp(Number((box.querySelector('[data-codecount]') || {}).value) || 1, 1, 30);
    const cur = Forms.readCodes(box), list = box.querySelector('.persons-list');
    list.innerHTML = String(Array.from({ length: n }, (_, i) => Forms.codeRow(cur[i] || {}, i)));
    UI.hydrate(list);
    return;
  }
  const del = e.target.closest('[data-delcode]');
  if (del) { const row = del.closest('.person-row'); if (row) row.remove(); }
});

/* عنوان الطلب حسب الفئة */
const CAT_TITLE_LABEL = { card: 'موضوع الطلب', path_code: 'موضوع الطلب', backup: 'موضوع الطلب', service_request: 'موضوع الطلب', email: 'موضوع الطلب', ink: 'موضوع الطلب' };
Forms.titleLabel = (catId) => CAT_TITLE_LABEL[catId] || 'عنوان مختصر للمشكلة';

/* ── قراءة الباركود و QR: بالكاميرا أو بقارئ الشفرات، مع البحث والصرف السريع ── */
const SCAN_FORMATS = ['qr_code', 'code_128', 'code_39', 'ean_13', 'ean_8', 'upc_a', 'upc_e', 'itf', 'data_matrix', 'pdf417', 'codabar'];
const scanSupported = () => typeof window !== 'undefined' && 'BarcodeDetector' in window;
Data.assets.bySerialOrTag = async (code) => {
  const c = String(code || '').trim(); if (!c) return null;
  const direct = await Data.assets.bySerial(c);
  if (direct) return direct;
  const all = await DB.getAll('assets');
  const norm = (x) => String(x || '').trim().toUpperCase();
  return all.find((a) => norm(a.tag) === norm(c)) || all.find((a) => norm(a.serial) === norm(c)) || null;
};
Pages.scanModal = ({ title = 'مسح الرمز', hint = 'وجّه الكاميرا إلى الباركود أو رمز QR، أو استخدم قارئ الشفرات.' } = {}) => {
  let stream = null, stop = false, detector = null;
  return UI.modal({
    title, icon: 'search', size: 'lg',
    body: html`<div class="scan-wrap">
        <div class="scan-view" data-scanview>${scanSupported() ? html`<video id="scanVideo" playsinline muted></video><div class="scan-frame"></div>` : html`<div class="scan-off">${UI.icon('alert')}<b>${window.isSecureContext ? 'الكاميرا غير مدعومة في هذا المتصفح' : 'الكاميرا لا تعمل على http'}</b><span>${window.isSecureContext ? 'استخدم قارئ الشفرات أو اكتب الرقم يدوياً' : 'يمنعها المتصفح على الاتصال غير الآمن (http). استخدم قارئ الشفرات أو اكتب الرقم يدوياً'}</span></div>`}</div>
        <p class="hint">${hint}</p>
      </div>
      <div class="field mt"><label for="scanIn">قارئ الشفرات أو إدخال يدوي</label><div class="combo"><input id="scanIn" name="code" dir="ltr" placeholder="امسح بالقارئ أو اكتب الرقم ثم اضغط Enter" autocomplete="off"><button type="button" class="combo-btn" data-scan="cam" title="تشغيل الكاميرا">${UI.icon('eye')}</button></div><small class="hint">قارئ الشفرات USB يعمل مباشرة: ضع المؤشر في الخانة وامسح.</small></div>
      <div class="scan-status" data-scanstatus hidden></div>`,
    onMount: async (form, finish) => {
      const input = $('#scanIn', form), status = form.querySelector('[data-scanstatus]');
      const say = (msg, tone = 'sky') => { status.hidden = false; status.className = `scan-status tone-${tone}`; status.textContent = msg; };
      const done = (code) => { stop = true; if (stream) stream.getTracks().forEach((t) => t.stop()); finish(String(code || '').trim()); };
      input.addEventListener('keydown', (e) => { if (e.key === 'Enter') { e.preventDefault(); if (input.value.trim()) done(input.value); } });
      setTimeout(() => input.focus(), 120);
      const startCam = async () => {
        if (!scanSupported()) { say(window.isSecureContext ? 'المتصفح لا يدعم قراءة الرموز بالكاميرا، استخدم القارئ أو الإدخال اليدوي' : `${httpBlocked('قراءة الرموز بالكاميرا')}. استخدم القارئ أو الإدخال اليدوي`, 'amber'); return; }
        try {
          detector = new window.BarcodeDetector({ formats: SCAN_FORMATS.filter((f) => true) });
          stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: { ideal: 'environment' } } });
          const v = $('#scanVideo', form); if (!v) return;
          v.srcObject = stream; await v.play();
          say('جارٍ البحث عن رمز...', 'sky');
          const tick = async () => {
            if (stop || !v.videoWidth) { if (!stop) requestAnimationFrame(tick); return; }
            try { const codes = await detector.detect(v); if (codes && codes.length) { UI.sound('success'); done(codes[0].rawValue); return; } } catch (_) { /* تجاهل */ }
            if (!stop) setTimeout(tick, 220);
          };
          tick();
        } catch (e) { say('تعذر فتح الكاميرا (قد تحتاج اتصالاً آمناً https أو إذناً بالكاميرا)، استخدم القارئ أو الإدخال اليدوي', 'amber'); }
      };
      UI.on(form, 'click', '[data-scan="cam"]', startCam);
      startCam();
      form.addEventListener('modal:close', () => { stop = true; if (stream) stream.getTracks().forEach((t) => t.stop()); });
    },
    actions: [{ label: 'إلغاء', kind: 'ghost', value: null }, { label: 'استخدام المُدخل', kind: 'primary', icon: 'check', submit: true, handler: (form) => { const v = String(($('#scanIn', form) || {}).value || '').trim(); if (!v) throw new AppError('امسح رمزاً أو اكتب الرقم'); return v; } }]
  });
};
UI.scanBtn = (target, cls = 'btn btn-soft') => html`<button type="button" class="${cls}" data-scanfor="${target}">${UI.icon('search')} مسح رمز</button>`;

/* مسح سريع: يفتح الجهاز أو يحدد الوحدة أو يعبّئ خانة */
Pages.scanLookup = async () => {
  const code = await Pages.scanModal({ title: 'بحث بالشفرة', hint: 'امسح ملصق الجهاز لعرض بياناته وموقعه الحالي.' });
  if (!code) return null;
  const asset = await Data.assets.bySerialOrTag(code);
  if (asset) {
    UI.toast(`${asset.serial}${asset.tag ? ` — أصل ${asset.tag}` : ''}: ${ASSET_STATUS[asset.status].label}`);
    await Pages.deviceModal(asset.itemId, asset.status === 'issued' ? { departmentId: asset.departmentId } : {});
    return asset;
  }
  const items = (await DB.getAll('items')).filter((i) => normalizeAr(`${i.sku} ${i.name} ${i.model || ''}`).includes(normalizeAr(code)));
  if (items.length === 1) { await Pages.deviceModal(items[0].id, {}); return items[0]; }
  UI.toast(`لم يُعثر على وحدة أو صنف بالرمز ${code}`, 'warn');
  Router.go(`/inventory/search?q=${encodeURIComponent(code)}`);
  return null;
};
document.addEventListener('click', async (e) => {
  const q = e.target.closest('[data-scanfor]');
  if (!q) return;
  e.preventDefault();
  const target = q.dataset.scanfor;
  if (target === 'lookup') { await Pages.scanLookup(); return; }
  if (target === 'pick') {
    const box = q.closest('.modal-card, form, .field') || document;
    const code = await Pages.scanModal({ title: 'مسح الوحدة', hint: 'امسح ملصق الجهاز لتحديده في القائمة.' });
    if (!code) return;
    const asset = await Data.assets.bySerialOrTag(code);
    const id = asset && asset.id;
    const cb = id ? box.querySelector(`[data-pick="${id}"]`) : null;
    if (cb) { cb.checked = true; cb.dispatchEvent(new Event('change', { bubbles: true })); UI.toast(`تم تحديد ${asset.serial}`); UI.sound('success'); }
    else UI.toast(asset ? `الوحدة ${asset.serial} غير متاحة في هذه القائمة (${ASSET_STATUS[asset.status].label})` : `لا توجد وحدة بالرمز ${code}`, 'warn');
    return;
  }
  const el = document.getElementById(target);
  if (el) { const code = await Pages.scanModal(); if (code) { el.value = code; el.dispatchEvent(new Event('input', { bubbles: true })); el.dispatchEvent(new Event('change', { bubbles: true })); } }
});

/* تصدير التقارير إلى Excel */
Pages.reportExcel = async (win, meta) => {
  const rows = (win && win.created) || [];
  const byCat = new Map(), byTech = new Map(), byDep = new Map();
  rows.forEach((t) => {
    byCat.set(t.categoryId, (byCat.get(t.categoryId) || 0) + 1);
    if (t.assigneeId) byTech.set(t.assigneeId, (byTech.get(t.assigneeId) || 0) + 1);
    byDep.set(t.departmentId, (byDep.get(t.departmentId) || 0) + 1);
  });
  const sheet = (name, head, data, widths) => ({ name, widths, rows: [head, ...data] });
  const book = [
    sheet('البلاغات', ['رقم البلاغ', 'العنوان', 'الفئة', 'الأولوية', 'الحالة', 'الإدارة', 'المسؤول', 'تاريخ الفتح', 'تاريخ الإغلاق'],
      rows.map((t) => [t.number, t.title, Data.nameOf('categories', t.categoryId, ''), (PRIORITY[t.priority] || {}).label || '', (STATUS[t.status] || {}).label || '', Data.nameOf('departments', t.departmentId, ''), t.assigneeId ? Data.userName(t.assigneeId) : '', fmtDateTime(t.createdAt), t.closedAt ? fmtDateTime(t.closedAt) : '']),
      [16, 40, 18, 12, 14, 20, 20, 20, 20]),
    sheet('حسب الفئة', ['الفئة', 'عدد البلاغات'], [...byCat].sort((a, b) => b[1] - a[1]).map(([k, v]) => [Data.nameOf('categories', k, 'غير محدد'), String(v)]), [26, 14]),
    sheet('حسب الإدارة', ['الإدارة', 'عدد البلاغات'], [...byDep].sort((a, b) => b[1] - a[1]).map(([k, v]) => [Data.nameOf('departments', k, 'غير محدد'), String(v)]), [26, 14]),
    sheet('حسب الفني', ['الفني', 'عدد البلاغات'], [...byTech].sort((a, b) => b[1] - a[1]).map(([k, v]) => [Data.userName(k), String(v)]), [26, 14])
  ];
  downloadBlob(XL.write(book), `تقرير-${dateInput(meta.from)}_${dateInput(meta.to)}.xlsx`);
  UI.toast('تم تصدير التقرير إلى Excel');
};

/* تصدير تقارير مفصّلة باختيار الأقسام والمدة */
const EXPORT_PARTS = [
  ['tickets', 'البلاغات بالتفصيل', 'ticket'],
  ['ticketsAgg', 'إحصاء البلاغات (الإدارات، الفئات، الأجهزة)', 'chart'],
  ['chat', 'الاستفسارات (إحصاء بلا محتوى)', 'bell'],
  ['inventory', 'المخزن والأرصدة', 'warehouse'],
  ['movements', 'حركات المخزون', 'swap'],
  ['custody', 'عهد الإدارات', 'building'],
  ['maint', 'الصيانة والخارج عن الخدمة', 'tools'],
  ['vouchers', 'السندات الصادرة', 'file']
];
Pages.exportModal = () => UI.modal({
  title: 'تصدير تقرير مفصّل', icon: 'download', size: 'lg',
  body: html`<p class="muted" style="margin-bottom:10px">اختر المدة والأقسام المطلوبة، ويُصدَّر ملف Excel بورقة لكل قسم.</p>
    <div class="range-bar mb"><span class="faint small">من</span><input type="date" id="exFrom" dir="ltr" lang="en-GB" value="${dateInput(now() - 30 * DAY)}"><span class="faint small">إلى</span><input type="date" id="exTo" dir="ltr" lang="en-GB" value="${dateInput(now())}"></div>
    <div class="chip-pick">${EXPORT_PARTS.map(([k, l, ic]) => html`<label><input type="checkbox" data-part="${k}"${['tickets', 'ticketsAgg'].includes(k) ? raw(' checked') : ''}><span>${UI.icon(ic)} ${l}</span></label>`)}</div>`,
  actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تصدير Excel', kind: 'primary', icon: 'download', submit: true, handler: async (form) => {
    const parts = $$('[data-part]:checked', form).map((x) => x.dataset.part);
    if (!parts.length) throw new AppError('اختر قسماً واحداً على الأقل');
    const from = startOfDay(fromDateInput(form.querySelector('#exFrom').value, true));
    const to = startOfDay(fromDateInput(form.querySelector('#exTo').value, true)) + DAY - 1;
    const book = [];
    const tickets = (await DB.getAll('tickets')).filter((t) => t.createdAt >= from && t.createdAt <= to);
    const items = new Map((await DB.getAll('items')).map((i) => [i.id, i]));
    if (parts.includes('tickets')) book.push({ name: 'البلاغات', widths: [16, 40, 18, 12, 14, 22, 20, 20, 20], rows: [['رقم البلاغ', 'العنوان', 'الفئة', 'الأولوية', 'الحالة', 'الإدارة', 'المسؤول', 'تاريخ الفتح', 'تاريخ الإغلاق'], ...tickets.map((t) => [t.number, t.title, Data.nameOf('categories', t.categoryId, ''), (PRIORITY[t.priority] || {}).label || '', (STATUS[t.status] || {}).label || '', Data.nameOf('departments', t.departmentId, ''), t.assigneeId ? Data.userName(t.assigneeId) : '', fmtDateTime(t.createdAt), t.closedAt ? fmtDateTime(t.closedAt) : ''])] });
    if (parts.includes('ticketsAgg')) {
      const agg = (keyFn, nameFn) => { const m = new Map(); tickets.forEach((t) => { const k = keyFn(t); m.set(k, (m.get(k) || 0) + 1); }); return [...m].sort((a, b) => b[1] - a[1]).map(([k, v]) => [nameFn(k), String(v)]); };
      book.push({ name: 'إحصاء الإدارات', widths: [30, 14], rows: [['الإدارة', 'عدد البلاغات'], ...agg((t) => t.departmentId, (k) => Data.nameOf('departments', k, 'غير محدد'))] });
      book.push({ name: 'إحصاء الفئات', widths: [30, 14], rows: [['الفئة', 'عدد البلاغات'], ...agg((t) => t.categoryId, (k) => Data.nameOf('categories', k, 'غير محدد'))] });
      book.push({ name: 'إحصاء الحالات', widths: [24, 14], rows: [['الحالة', 'عدد البلاغات'], ...agg((t) => t.status, (k) => (STATUS[k] || {}).label || k)] });
      book.push({ name: 'إحصاء الفنيين', widths: [26, 14], rows: [['الفني', 'عدد البلاغات'], ...agg((t) => t.assigneeId || '—', (k) => (k === '—' ? 'غير مسند' : Data.userName(k)))] });
      const dev = new Map(); tickets.forEach((t) => { const f = ((t.extra || {}).fields || []); const b = (f.find((x) => x.key === 'brand') || {}).value || ''; const d = (f.find((x) => x.key === 'device') || {}).value || Data.nameOf('categories', t.categoryId, ''); const k = [d, b].filter(Boolean).join(' — '); dev.set(k, (dev.get(k) || 0) + 1); });
      book.push({ name: 'إحصاء الأجهزة', widths: [34, 14], rows: [['نوع الجهاز أو الماركة', 'عدد البلاغات'], ...[...dev].sort((a, b) => b[1] - a[1]).map(([k, v]) => [k, String(v)])] });
    }
    if (parts.includes('chat')) {
      const chats = (await DB.getAll('chats')).filter((c) => c.createdAt >= from && c.createdAt <= to);
      const byDep = new Map(), byUser = new Map();
      chats.forEach((c) => { byDep.set(c.departmentId, (byDep.get(c.departmentId) || 0) + 1); byUser.set(c.userId, (byUser.get(c.userId) || 0) + 1); });
      book.push({ name: 'الاستفسارات', widths: [30, 16, 16], rows: [['الإدارة', 'عدد الاستفسارات', 'الحالة'], ...[...byDep].sort((a, b) => b[1] - a[1]).map(([k, v]) => [Data.nameOf('departments', k, 'غير محدد'), String(v), '']), [''], ['أكثر المستفيدين', 'العدد', ''], ...[...byUser].sort((a, b) => b[1] - a[1]).slice(0, 20).map(([k, v]) => [Data.userName(k), String(v), ''])] });
    }
    if (parts.includes('inventory')) book.push({ name: 'المخزن', widths: [34, 16, 20, 12, 12], rows: [['الصنف', 'الرمز', 'التصنيف', 'الرصيد', 'الحد الأدنى'], ...[...items.values()].map((i) => [i.name, i.sku || '', Data.nameOf('itemCategories', i.categoryId, ''), String(i.onHand), String(i.minQty || 0)])] });
    if (parts.includes('movements')) { const mv = (await DB.getAll('movements')).filter((m) => m.at >= from && m.at <= to); book.push({ name: 'الحركات', widths: [20, 30, 12, 20, 22, 18], rows: [['النوع', 'الصنف', 'الكمية', 'المخزن', 'الإدارة', 'التاريخ'], ...mv.map((m) => [(MOVES[m.type] || {}).label || m.type, (items.get(m.itemId) || {}).name || '', String(m.qty), Data.nameOf('warehouses', m.warehouseId, ''), Data.nameOf('departments', m.departmentId, ''), fmtDateTime(m.at)])] }); }
    if (parts.includes('custody')) { const ds = (await DB.getAll('deptStock')).filter((d) => d.qty > 0); book.push({ name: 'عهد الإدارات', widths: [28, 34, 12], rows: [['الإدارة', 'الصنف', 'الكمية'], ...ds.map((d) => [Data.nameOf('departments', d.departmentId, ''), (items.get(d.itemId) || {}).name || '', String(d.qty)])] }); }
    if (parts.includes('maint')) { const mt = (await DB.getAll('maintenance')).filter((m) => m.openedAt >= from && m.openedAt <= to); book.push({ name: 'الصيانة', widths: [30, 18, 22, 22, 18, 30, 16], rows: [['الجهاز', 'الرقم التسلسلي', 'الإدارة', 'السبب', 'الحالة', 'ما تم', 'التاريخ'], ...mt.map((m) => [m.itemName, m.serial || '', Data.nameOf('departments', m.fromDepartmentId, ''), m.reason, (MAINT_STATUS[m.status] || {}).label || m.status, m.workDone || '', fmtDate(m.openedAt)])] }); }
    if (parts.includes('vouchers')) { const vs = (await DB.getAll('vouchers')).filter((v) => v.at >= from && v.at <= to); book.push({ name: 'السندات', widths: [18, 16, 24, 24, 12, 18], rows: [['رقم السند', 'النوع', 'المستلم', 'الإدارة', 'الوحدات', 'التاريخ'], ...vs.map((v) => [v.number, (VOUCHER_KIND[v.type] || {}).label || v.type, v.holder || '', Data.nameOf('departments', v.departmentId, ''), String(v.units || 0), fmtDateTime(v.at)])] }); }
    downloadBlob(XL.write(book), `تقرير-مفصل-${dateInput(from)}_${dateInput(to)}.xlsx`);
    UI.toast(`تم تصدير ${arCount(book.length, AR.item).replace('صنف', 'ورقة').replace('أصناف', 'أوراق')}`);
    return true;
  } }]
});

/* ── الصيانة والأجهزة الخارجة عن الخدمة ── */
const MAINT_STATUS = {
  open: { label: 'تحت الصيانة', tone: 'sky', icon: 'tools' },
  done: { label: 'انتهت الصيانة — بانتظار التسليم', tone: 'teal', icon: 'check' },
  returned: { label: 'أُرجع إلى الموقع', tone: 'green', icon: 'undo' },
  retired: { label: 'خارج عن الخدمة (تالف)', tone: 'red', icon: 'x' }
};
const MAINT_REASONS = ['عطل في التشغيل', 'بطء أو تعليق', 'عطل في الشاشة', 'عطل في الطاقة', 'عطل في الطباعة', 'تلف مادي', 'صيانة دورية', 'سبب آخر'];
const RETIRE_REASONS = ['تلف لا يمكن إصلاحه', 'تقادم وانتهاء العمر التشغيلي', 'فقدان', 'استبدال بجهاز أحدث', 'سبب آخر'];
Data.maint = {
  list: () => DB.getAll('maintenance'),
  async byAsset(assetId) { return (await DB.getAll('maintenance', 'assetId', KR(assetId))).sort((a, b) => b.openedAt - a.openedAt); },
  async byItem(itemId) { return (await DB.getAll('maintenance', 'itemId', KR(itemId))).sort((a, b) => b.openedAt - a.openedAt); },
  async send({ itemId, assetId = '', departmentId = '', unitId = '', reason, symptom = '', ticketId = '' }) {
    const item = await DB.get('items', itemId); if (!item) throw new AppError('الصنف غير موجود');
    const asset = assetId ? await DB.get('assets', assetId) : null;
    const t = now();
    if (departmentId) {
      const ds = await DB.get('deptStock', [departmentId, itemId]);
      if (!ds || ds.qty < 1) throw new AppError('هذا الصنف غير مسجل في عهدة الإدارة المحددة');
      ds.qty -= 1; ds.updatedAt = t; await DB.put('deptStock', ds);
      if (unitId) { const us = await DB.get('unitStock', [unitId, itemId]); if (us && us.qty > 0) { us.qty -= 1; us.updatedAt = t; await DB.put('unitStock', us); } }
    }
    if (asset) { asset.status = 'maintenance'; asset.departmentId = ''; asset.holder = ''; asset.holderId = ''; asset.updatedAt = t; await DB.put('assets', asset); }
    const rec = { id: uid('mt'), itemId, assetId, serial: asset ? asset.serial : '', tag: asset ? asset.tag || '' : '', itemName: item.name, brand: item.brand || '', model: item.model || '', fromDepartmentId: departmentId, fromUnitId: unitId, reason, symptom, ticketId, status: 'open', openedAt: t, openedBy: Auth.user.id, workDone: '', parts: '', cost: '', closedAt: 0, closedBy: '', returnedAt: 0, returnedBy: '', toDepartmentId: '', toUnitId: '' };
    await DB.put('maintenance', rec);
    await Data.log('update', 'inventory', itemId, `إرسال ${item.name}${rec.serial ? ` (${rec.serial})` : ''} إلى الصيانة — ${reason}`);
    const managers = Data.list('users').filter((u) => u.active && canUser(u, 'inventory.move')).map((u) => u.id);
    if (managers.length) await Data.notify(managers, { title: `جهاز في الصيانة: ${item.name}`, body: `${reason}${departmentId ? ` — من ${Data.nameOf('departments', departmentId)}` : ''}`, link: '/maintenance', kind: 'inventory' });
    Bus.emit('inventory', {});
    return rec;
  },
  async complete(id, { workDone, parts = '', result = 'repaired', retireReason = '' }) {
    const rec = await DB.get('maintenance', id); if (!rec) throw new AppError('السجل غير موجود');
    if (!String(workDone || '').trim()) throw new AppError('اكتب ما تم في الصيانة');
    rec.workDone = String(workDone).trim(); rec.parts = parts; delete rec.cost; rec.closedAt = now(); rec.closedBy = Auth.user.id;
    if (result === 'retired') { rec.status = 'retired'; rec.retireReason = retireReason || 'تلف لا يمكن إصلاحه'; if (rec.assetId) await Data.maint.markRetired(rec.assetId, rec.retireReason, rec.fromDepartmentId); }
    else rec.status = 'done';
    await DB.put('maintenance', rec);
    await Data.log('update', 'inventory', rec.itemId, `${result === 'retired' ? 'إخراج من الخدمة بعد الصيانة' : 'انتهت صيانة'} ${rec.itemName}${rec.serial ? ` (${rec.serial})` : ''}`);
    Bus.emit('inventory', {});
    return rec;
  },
  async markRetired(assetId, reason, fromDepartmentId = '', replacedBy = '') {
    const a = await DB.get('assets', assetId); if (!a) return null;
    a.status = 'retired'; a.retiredAt = now(); a.retireReason = reason; a.retiredFrom = fromDepartmentId || a.departmentId || ''; a.replacedBy = replacedBy; a.departmentId = ''; a.holder = ''; a.holderId = ''; a.warehouseId = ''; a.updatedAt = now();
    await DB.put('assets', a); Bus.emit('inventory', {});
    return a;
  },
  async back(id, { departmentId, unitId = '' }) {
    const rec = await DB.get('maintenance', id); if (!rec) throw new AppError('السجل غير موجود');
    if (!departmentId) throw new AppError('اختر الإدارة المستلمة');
    const t = now();
    const ds = (await DB.get('deptStock', [departmentId, rec.itemId])) || { departmentId, itemId: rec.itemId, qty: 0 };
    ds.qty += 1; ds.updatedAt = t; await DB.put('deptStock', ds);
    if (unitId) await Data.units.add(unitId, departmentId, rec.itemId, 1);
    if (rec.assetId) { const a = await DB.get('assets', rec.assetId); if (a) { a.status = 'issued'; a.departmentId = departmentId; a.updatedAt = t; await DB.put('assets', a); } }
    rec.status = 'returned'; rec.returnedAt = t; rec.returnedBy = Auth.user.id; rec.toDepartmentId = departmentId; rec.toUnitId = unitId;
    await DB.put('maintenance', rec);
    await Data.log('move', 'inventory', rec.itemId, `إرجاع ${rec.itemName} بعد الصيانة إلى ${Data.nameOf('departments', departmentId)}`);
    Bus.emit('inventory', {});
    return rec;
  }
};

/* نوافذ الصيانة والشطب */
Pages.maintSendModal = async (itemId, scope = {}) => {
  const item = await DB.get('items', itemId); if (!item) return false;
  const assets = (await Data.assets.byItem(itemId)).filter((a) => ['issued', 'in_store', 'loaned'].includes(a.status) && (!scope.departmentId || a.departmentId === scope.departmentId || a.status === 'in_store'));
  const tree = scope.departmentId ? await Data.units.tree(scope.departmentId) : [];
  const offices = tree.flatMap((s) => s.offices.map((o) => ({ value: o.id, label: `${s.name} — ${o.name}` })));
  return UI.modal({
    title: `إرسال ${item.name} إلى الصيانة`, icon: 'tools', size: 'lg',
    body: html`<div class="banner tone-sky">${UI.icon('info')}<div class="grow">يخرج الجهاز من عهدة الإدارة ويُسجَّل تحت الصيانة، ويمكن متابعته وإرجاعه بعد الإصلاح.</div></div>
      <div class="form-grid mt">
        ${UI.field({ name: 'departmentId', label: 'من إدارة', type: 'select', options: UI.opts('departments') }, scope.departmentId || '')}
        ${offices.length ? UI.field({ name: 'unitId', label: 'من مكتب', type: 'select', options: offices }, scope.unitId || '') : ''}
        ${assets.length ? UI.field({ name: 'assetId', label: 'الوحدة (الرقم التسلسلي)', type: 'select', options: assets.map((a) => ({ value: a.id, label: `${a.serial}${a.tag ? ` — أصل ${a.tag}` : ''}` })) }) : ''}
        ${UI.field({ name: 'reason', label: 'سبب الإرسال', type: 'select', placeholder: false, options: MAINT_REASONS.map((r) => ({ value: r, label: r })) })}
        ${UI.field({ name: 'symptom', label: 'وصف العطل كما ظهر', type: 'textarea', rows: 3, wide: true, placeholder: 'ما الذي لاحظته؟ متى يحدث؟' })}
      </div>`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'إرسال إلى الصيانة', kind: 'primary', icon: 'tools', submit: true, handler: async (form) => {
      const v = UI.formValues(form);
      const rec = await Data.maint.send({ itemId, assetId: v.assetId || '', departmentId: v.departmentId || '', unitId: v.unitId || '', reason: v.reason, symptom: v.symptom });
      UI.toast('سُجّل الجهاز تحت الصيانة'); UI.sound('success'); return rec;
    } }]
  });
};
Pages.maintDoneModal = (rec) => UI.modal({
  title: `إنهاء صيانة ${rec.itemName}`, icon: 'check', size: 'lg',
  body: html`<dl class="kv"><dt>الجهاز</dt><dd>${rec.itemName} ${[rec.brand, rec.model].filter(Boolean).join(' ')}</dd><dt>الرقم التسلسلي</dt><dd class="ltr">${rec.serial || '—'}</dd><dt>سبب الإرسال</dt><dd>${rec.reason}</dd><dt>الوصف</dt><dd>${rec.symptom || '—'}</dd></dl>
    <div class="form-grid mt">
      ${UI.field({ name: 'workDone', label: 'ما تم في الصيانة', type: 'textarea', rows: 3, required: true, wide: true, placeholder: 'مثال: استبدال مزود الطاقة وتنظيف داخلي وتحديث التعريفات' })}
      ${UI.field({ name: 'parts', label: 'القطع المستخدمة', placeholder: 'مثال: مزود طاقة 500W' })}
      ${UI.field({ name: 'result', label: 'النتيجة', type: 'select', placeholder: false, options: [{ value: 'repaired', label: 'تم الإصلاح ويعمل' }, { value: 'retired', label: 'تعذر الإصلاح — إخراج الجهاز من الخدمة' }] })}
      ${UI.field({ name: 'retireReason', label: 'سبب الإخراج من الخدمة (عند تعذر الإصلاح)', type: 'select', options: RETIRE_REASONS.map((r) => ({ value: r, label: r })), wide: true })}
    </div>`,
  actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ نتيجة الصيانة', kind: 'primary', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); const out = await Data.maint.complete(rec.id, v); UI.toast(v.result === 'retired' ? 'سُجّل الجهاز خارجاً عن الخدمة' : 'سُجّلت نتيجة الصيانة'); return out; } }]
});
Pages.maintBackModal = async (rec) => {
  const dep = rec.fromDepartmentId || '';
  const tree = dep ? await Data.units.tree(dep) : [];
  const offices = tree.flatMap((s) => s.offices.map((o) => ({ value: o.id, label: `${s.name} — ${o.name}` })));
  return UI.modal({
    title: `إرجاع ${rec.itemName} إلى الموقع`, icon: 'undo', size: 'lg',
    body: html`<p class="muted" style="margin-bottom:10px">يعود الجهاز إلى عهدة الإدارة ويُسجَّل تاريخ الإرجاع في سجله.</p>
      <div class="form-grid">${UI.fields([{ name: 'departmentId', label: 'إلى إدارة', type: 'select', options: UI.opts('departments'), value: dep, required: true }, { name: 'unitId', label: 'إلى مكتب', type: 'select', options: offices, value: rec.fromUnitId || '' }])}</div>`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تأكيد الإرجاع', kind: 'ok', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); const out = await Data.maint.back(rec.id, { departmentId: v.departmentId, unitId: v.unitId }); UI.toast('أُرجع الجهاز إلى الموقع'); return out; } }]
  });
};
Pages.retireModal = async (itemId, scope = {}) => {
  const item = await DB.get('items', itemId);
  const assets = (await Data.assets.byItem(itemId)).filter((a) => a.status !== 'retired');
  return UI.modal({
    title: `إخراج ${item ? item.name : 'جهاز'} من الخدمة`, icon: 'x', size: 'lg',
    body: html`<div class="banner tone-red">${UI.icon('alert')}<div class="grow">الجهاز الخارج عن الخدمة يخرج من أرصدة المخزن والعهد ويُحفظ في سجل الأجهزة الخارجة عن الخدمة.</div></div>
      <div class="form-grid mt">
        ${assets.length ? UI.field({ name: 'assetId', label: 'الوحدة', type: 'select', options: assets.map((a) => ({ value: a.id, label: `${a.serial}${a.tag ? ` — ${a.tag}` : ''} (${ASSET_STATUS[a.status].label})` })), required: true }) : ''}
        ${UI.field({ name: 'reason', label: 'سبب الإخراج من الخدمة', type: 'select', placeholder: false, options: RETIRE_REASONS.map((r) => ({ value: r, label: r })) })}
        ${UI.field({ name: 'replacedBy', label: 'الجهاز البديل إن وُجد', placeholder: 'اسم الجهاز أو رقمه التسلسلي' })}
        ${UI.field({ name: 'notes', label: 'ملاحظات', type: 'textarea', rows: 2, wide: true })}
      </div>`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تأكيد الإخراج من الخدمة', kind: 'danger', icon: 'x', submit: true, handler: async (form) => {
      const v = UI.formValues(form);
      if (!v.assetId) throw new AppError('اختر الوحدة المطلوب إخراجها من الخدمة');
      const a = await DB.get('assets', v.assetId);
      const dep = a ? a.departmentId : scope.departmentId || '';
      if (dep) { const ds = await DB.get('deptStock', [dep, itemId]); if (ds && ds.qty > 0) { ds.qty -= 1; ds.updatedAt = now(); await DB.put('deptStock', ds); } }
      if (a && a.status === 'in_store' && a.warehouseId) { const st = await DB.get('stock', [a.warehouseId, itemId]); await Data.inv.move({ type: 'adjust', itemId, warehouseId: a.warehouseId, qty: Math.max(0, ((st || {}).qty || 0) - 1), note: `إخراج من الخدمة: ${v.reason}` }); }
      await Data.maint.markRetired(v.assetId, v.reason, dep, v.replacedBy);
      await DB.put('maintenance', { id: uid('mt'), itemId, assetId: v.assetId, serial: a ? a.serial : '', tag: a ? a.tag || '' : '', itemName: item.name, brand: item.brand || '', model: item.model || '', fromDepartmentId: dep, fromUnitId: '', reason: v.reason, symptom: v.notes || '', status: 'retired', retireReason: v.reason, replacedBy: v.replacedBy || '', openedAt: now(), openedBy: Auth.user.id, workDone: '', parts: '', cost: '', closedAt: now(), closedBy: Auth.user.id, returnedAt: 0, returnedBy: '' });
      await Data.log('delete', 'inventory', itemId, `إخراج من الخدمة: ${item.name}${a ? ` (${a.serial})` : ''} — ${v.reason}`);
      Bus.emit('inventory', {});
      UI.toast('سُجّل الجهاز في سجل الخارج عن الخدمة'); return true;
    } }]
  });
};

/* ══════════ صيانة الأجهزة للفنيين والإداريين والمشرفين ══════════
   الاستلام بالرقم التسلسلي ← أمر صيانة يُسجَّل فيه ما تم والقطع والإضافات والتعديلات والملاحظات ← التسليم إلى الموقع السابق.
   نمط «يبقى في عهدته» (keep): لا يخرج الجهاز من عهدة إدارته ولا تتغير أرصدتها، بل تصير حالته «تحت الصيانة»
   ويُحفظ مكانه وحائزه في السجل فيعود إليهما. كل دخول للصيانة سجل مستقل، فيبقى تاريخ الجهاز كاملاً ويُرجع إليه */
Object.assign(MAINT_STATUS, {
  sent: { label: 'سُلّم — بانتظار تأكيد المستلم', tone: 'violet', icon: 'send' },
  unrepairable: { label: 'تعذر الإصلاح — بانتظار القرار', tone: 'amber', icon: 'alert' }
});
const MAINT_ACTIVE = ['open', 'done', 'unrepairable'];
const maintTicketByNo = async (raw) => {
  const q = String(raw || '').trim().toUpperCase(); if (!q) return null;
  let tk = (await DB.getAll('tickets', 'number', KR(q)))[0] || null;
  if (!tk && /^\d+$/.test(q)) tk = (await DB.getAll('tickets')).filter((x) => Number(String(x.number || '').split('-').pop()) === Number(q)).sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))[0] || null;
  if (!tk) throw new AppError(`لم أجد بلاغاً برقم ${raw}`);
  return tk;
};
Object.assign(Data.maint, {
  canWork: () => Auth.can('maint.work') || Auth.can('inventory.move'),
  /* كل سجلات الرقم التسلسلي (أو رقم الأصل)، الأحدث أولاً: للأجهزة المسجلة وغير المسجلة */
  async bySerial(serial) {
    const k = Data.assets.norm(serial); if (!k) return [];
    return (await DB.getAll('maintenance')).filter((r) => Data.assets.norm(r.serial) === k || (r.tag && Data.assets.norm(r.tag) === k)).sort((a, b) => b.openedAt - a.openedAt);
  },
  async activeOf(serial) { return (await Data.maint.bySerial(serial)).find((r) => MAINT_ACTIVE.includes(r.status)) || null; },
  /* مكان الجهاز كما هو الآن (أو كما حُفظ في سجل): الإدارة والفرع والحائز والمخزن */
  placeText(x, units = Data.list('deptUnits')) {
    const dep = x.fromDepartmentId !== undefined ? x.fromDepartmentId : x.departmentId, unit = x.fromUnitId !== undefined ? x.fromUnitId : x.unitId, holder = x.fromHolder !== undefined ? x.fromHolder : x.holder, wh = x.fromWarehouseId !== undefined ? x.fromWarehouseId : x.warehouseId;
    const place = dep ? orgLabel(dep, unit || '', units) : wh ? `المخزن: ${Data.nameOf('warehouses', wh)}` : '';
    return [place, holder ? `الحائز: ${holder}` : ''].filter(Boolean).join(' — ') || 'غير محدد';
  },
  async intake({ assetId = '', serial = '', manual = null, reason, symptom = '', broughtBy = '', accessories = '', ticketNo = '' }) {
    if (!Data.maint.canWork()) throw new AppError('لا تملك صلاحية صيانة الأجهزة');
    if (!String(reason || '').trim()) throw new AppError('اختر سبب دخول الصيانة');
    const a = assetId ? await DB.get('assets', assetId) : null;
    const sn = a ? a.serial : String(serial || '').trim(); if (!sn) throw new AppError('اكتب الرقم التسلسلي');
    if (a && a.status === 'retired') throw new AppError('هذا الجهاز مسجّل خارجاً عن الخدمة');
    const act = await Data.maint.activeOf(sn); if (act) throw new AppError(`الجهاز ${sn} في الصيانة الآن منذ ${fmtDate(act.openedAt)}`);
    const tk = ticketNo ? await maintTicketByNo(ticketNo) : null;
    const it = a ? await DB.get('items', a.itemId) : null, m = manual || {}, t = now();
    if (!a && !String(m.name || '').trim()) throw new AppError('اكتب اسم الجهاز أو نوعه');
    const holderU = !a && m.holderId ? Data.c.users.get(m.holderId) : null;
    const rec = {
      id: uid('mt'), keep: 1, itemId: a ? a.itemId : '', assetId: a ? a.id : '', serial: sn, tag: a ? a.tag || '' : '', host: a ? a.host || '' : '',
      itemName: it ? it.name : String(m.name || '').trim(), brand: it ? it.brand || '' : String(m.brand || '').trim(), model: it ? it.model || '' : String(m.model || '').trim(),
      fromDepartmentId: a ? a.departmentId || '' : m.departmentId || '', fromUnitId: a ? a.unitId || '' : m.unitId || '', fromHolder: a ? a.holder || '' : (holderU ? holderU.name : String(m.holder || '').trim()), fromHolderId: a ? a.holderId || '' : m.holderId || '',
      fromWarehouseId: a ? a.warehouseId || '' : '', prevStatus: a ? a.status : '', registered: a ? 1 : 0,
      reason: String(reason).trim(), symptom: String(symptom || '').trim(), broughtBy: String(broughtBy || '').trim(), accessories: String(accessories || '').trim(), ticketId: tk ? tk.id : '', ticketNo: tk ? tk.number : '',
      status: 'open', openedAt: t, openedBy: Auth.user.id, log: [], workDone: '', parts: '', additions: '', changes: '', notes: '', result: '',
      closedAt: 0, closedBy: '', returnedAt: 0, returnedBy: '', receiverId: '', receiverName: '', receivedAt: 0, handoverNote: '', toDepartmentId: '', toUnitId: '', updatedAt: t
    };
    await DB.put('maintenance', rec);
    if (a) await DB.put('assets', { ...a, status: 'maintenance', maintId: rec.id, updatedAt: t });
    await Data.log('update', 'maintenance', rec.id, `استلام ${rec.itemName} (${sn}) للصيانة — ${rec.reason}`);
    if (rec.fromHolderId) await Data.notify([rec.fromHolderId], { title: `استُلم جهازك للصيانة: ${rec.itemName}`, body: `${sn} — ${rec.reason}`, link: `/maint-receipt/${rec.id}`, kind: 'inventory' });
    Bus.emit('inventory', {}); return rec;
  },
  async _get(id) { const r = await DB.get('maintenance', id); if (!r) throw new AppError('سجل الصيانة غير موجود'); return r; },
  /* ملاحظة متابعة أثناء العمل: من كتبها ومتى */
  async addLog(id, text) {
    const r = await Data.maint._get(id), x = String(text || '').trim(); if (!x) throw new AppError('اكتب الملاحظة');
    if (!MAINT_ACTIVE.includes(r.status)) throw new AppError('أُغلق أمر الصيانة');
    r.log = [...(r.log || []), { at: now(), by: Auth.user.id, text: x }]; r.updatedAt = now(); await DB.put('maintenance', r); Bus.emit('inventory', {}); return r;
  },
  /* إنهاء الصيانة (ويمكن تعديل ما كُتب حتى التسليم) */
  async finish(id, { workDone, parts = '', additions = '', changes = '', notes = '', result = 'repaired' }) {
    const r = await Data.maint._get(id);
    if (!MAINT_ACTIVE.includes(r.status)) throw new AppError('سُلّم الجهاز، فلا يُعدَّل أمر صيانته');
    if (!String(workDone || '').trim()) throw new AppError('اكتب ما تم في الصيانة');
    const first = r.status === 'open', t = now();
    Object.assign(r, { workDone: String(workDone).trim(), parts: String(parts || '').trim(), additions: String(additions || '').trim(), changes: String(changes || '').trim(), notes: String(notes || '').trim(), result, status: result === 'unrepairable' ? 'unrepairable' : 'done', closedAt: first ? t : r.closedAt || t, closedBy: first ? Auth.user.id : r.closedBy || Auth.user.id, updatedAt: t });
    if (!first) r.editedAt = t;
    await DB.put('maintenance', r);
    await Data.log('update', 'maintenance', r.id, `${result === 'unrepairable' ? 'تعذر إصلاح' : 'انتهت صيانة'} ${r.itemName} (${r.serial})`);
    if (first && r.fromHolderId) await Data.notify([r.fromHolderId], { title: result === 'unrepairable' ? `تعذر إصلاح جهازك: ${r.itemName}` : `جهازك جاهز بعد الصيانة: ${r.itemName}`, body: r.serial, link: `/maint-receipt/${r.id}`, kind: 'inventory' });
    if (first && result === 'unrepairable') { const mgr = Data.list('users').filter((u) => u.active && canUser(u, 'inventory.move')).map((u) => u.id); if (mgr.length) await Data.notify(mgr, { title: `تعذر إصلاح جهاز: ${r.itemName}`, body: `${r.serial} — يحتاج قرار إخراجه من الخدمة أو إرساله لجهة خارجية`, link: `/maintenance/${r.id}`, kind: 'inventory' }); }
    Bus.emit('inventory', {}); return r;
  },
  /* التسليم: يعود الجهاز إلى مكانه وحائزه كما كانا عند الاستلام. «الآن» يسلّمه الفني يداً بيد،
     و«بتأكيد المستلم» يصل المستلمَ إشعار فيؤكد من حسابه */
  async deliver(id, { receiverId = '', receiverName = '', mode = 'now', note = '' }) {
    const r = await Data.maint._get(id);
    if (!['done', 'unrepairable'].includes(r.status)) throw new AppError(r.status === 'open' ? 'أنهِ الصيانة أولاً' : 'سُلّم الجهاز من قبل');
    const ru = receiverId ? Data.c.users.get(receiverId) : null, name = ru ? ru.name : String(receiverName || '').trim();
    if (!name) throw new AppError('حدد مستلم الجهاز');
    if (mode === 'confirm' && !ru) throw new AppError('التأكيد من المستلم يحتاج أن يكون له حساب؛ اختر «تسليم الآن» إن لم يكن');
    const t = now();
    Object.assign(r, { status: mode === 'confirm' ? 'sent' : 'returned', returnedAt: t, returnedBy: Auth.user.id, receiverId: ru ? ru.id : '', receiverName: name, receivedAt: mode === 'confirm' ? 0 : t, handoverNote: String(note || '').trim(), toDepartmentId: r.fromDepartmentId, toUnitId: r.fromUnitId, updatedAt: t });
    await DB.put('maintenance', r);
    if (r.assetId) { const a = await DB.get('assets', r.assetId); if (a && a.status === 'maintenance') await DB.put('assets', { ...a, status: r.prevStatus && r.prevStatus !== 'maintenance' ? r.prevStatus : 'issued', maintId: '', updatedAt: t }); }
    await Data.log('move', 'maintenance', r.id, `تسليم ${r.itemName} (${r.serial}) بعد الصيانة إلى ${name}`);
    if (ru) await Data.notify([ru.id], { title: mode === 'confirm' ? `جهاز بانتظار تأكيد استلامك: ${r.itemName}` : `سُلّم إليك جهاز بعد الصيانة: ${r.itemName}`, body: `${r.serial} — ${Data.maint.placeText(r)}`, link: `/maint-receipt/${r.id}`, kind: 'inventory' });
    Bus.emit('inventory', {}); return r;
  },
  /* المستلم يؤكد من حسابه (والخادم لا يقبل منه إلا هذا التغيير) */
  async confirmReceipt(id) {
    const r = await Data.maint._get(id);
    if (r.receiverId !== Auth.user.id) throw new AppError('التأكيد للمستلم المعيَّن فقط');
    if (r.status !== 'sent') throw new AppError('لا ينتظر هذا الجهاز تأكيداً');
    const t = now(); Object.assign(r, { status: 'returned', receivedAt: t, receivedConfirm: 1, updatedAt: t }); await DB.put('maintenance', r);
    const to = [r.returnedBy, r.closedBy].filter((x, i, a) => x && a.indexOf(x) === i); if (to.length) await Data.notify(to, { title: `أكّد ${Auth.user.name} استلام ${r.itemName}`, body: r.serial, link: `/maintenance/${r.id}`, kind: 'inventory' });
    Bus.emit('inventory', {}); return r;
  }
});

/* ── واجهات صيانة الأجهزة ── */
/* الإضافات والتعديلات المتراكمة على الجهاز من كل صيانة سابقة: تُعرض كأنها مواصفاته الحالية فوق مواصفات الصنف */
Pages.maintAdds = (rows) => { const list = rows.filter((r) => r.additions || r.changes).slice(0, 12); return list.length ? html`<div class="u-sec mt"><h3>${UI.icon('plus')} ما أُضيف وعُدّل على الجهاز في صياناته</h3><div class="list">${list.map((r) => html`<div class="list-row mt-add"><span class="faint small nowrap">${fmtDate(r.closedAt || r.openedAt)}</span><div class="grow">${r.additions ? html`<div><b>إضافات:</b> ${r.additions}</div>` : ''}${r.changes ? html`<div><b>تعديلات:</b> ${r.changes}</div>` : ''}</div></div>`)}</div></div>` : ''; };
/* بطاقة الجهاز بعد إدخال رقمه التسلسلي: كل بياناته ومكانه وحائزه وسجل صيانته، وزر الاستلام */
Pages.maintDeviceCard = async (q) => {
  const code = String(q || '').trim(); if (!code) return '';
  const a = await Data.assets.bySerialOrTag(code), hist = await Data.maint.bySerial(a ? a.serial : code), act = hist.find((r) => MAINT_ACTIVE.includes(r.status));
  if (!a) {
    return html`<div class="panel md-card" data-mdcard><div class="panel-body"><div class="md-head">${UI.illu('box', 'lg')}<div class="grow"><h3>الرقم <span class="ltr">${code}</span> غير مسجل في المخزن</h3><p class="muted small" style="margin:4px 0 0">${hist.length ? `دخل جهاز بهذا الرقم الصيانة ${fmtNum(hist.length)} ${hist.length === 1 ? 'مرة' : 'مرات'} من قبل، وسجلاته أدناه.` : 'لم يُسجَّل في المخزن ولم يدخل الصيانة من قبل. يمكن استلامه بإدخال بياناته يدوياً.'}</p></div>
      <div class="md-acts">${act ? html`<a class="btn btn-primary" href="#/maintenance/${act.id}">${UI.icon('tools')} أمر الصيانة الحالي</a>` : Data.maint.canWork() ? html`<button type="button" class="btn btn-primary" data-mdin="" data-mdsn="${code}">${UI.icon('tools')} استلام كجهاز غير مسجل</button>` : ''}</div></div>
      ${hist.length ? html`${Pages.maintAdds(hist)}<div class="u-sec mt"><h3>${UI.icon('tools')} سجل الصيانة (${fmtNum(hist.length)})</h3>${Pages.maintSummary(hist)}${Pages.maintTimeline(hist)}</div>` : ''}</div></div>`;
  }
  const it = (await DB.get('items', a.itemId)) || { name: 'صنف محذوف', categoryId: '' }, S = ASSET_STATUS[a.status] || ASSET_STATUS.in_store, specs = Object.entries(MAP.specsOf(a, it)), defs = specsOf(it.categoryId), lab = (k) => (defs.find((d) => d.k === k) || {}).l || k;
  const hu = a.holderId ? Data.c.users.get(a.holderId) : null, loan = a.loanId ? await DB.get('loans', a.loanId) : null;
  /* الفروع من قاعدة الجهاز مباشرة: الذاكرة تُحدَّث بعد وصول التغييرات بلحظة، فقد لا يظهر فرع أُضيف للتو */
  const units = await DB.getAll('deptUnits'), place = a.departmentId ? orgLabel(a.departmentId, a.unitId || '', units) : '';
  const tks = hu ? (await DB.getAll('tickets', 'requester_createdAt', KR([hu.id, 0], [hu.id, Infinity]))).filter((t) => OPEN.includes(t.status)).slice(-3).reverse() : [];
  return html`<div class="panel md-card" data-mdcard><div class="panel-body">
    <div class="md-head">${UI.illu(itemIllu(it), 'lg')}<div class="grow" style="min-width:0"><h3>${it.name}</h3><div class="row" style="gap:6px;flex-wrap:wrap">${UI.chip(S.tone, S.label, S.icon)}${it.brand ? UI.chip('violet', it.brand) : ''}${it.model ? UI.chip('teal', it.model) : ''}${act ? UI.chip('sky', `في الصيانة منذ ${fmtDate(act.openedAt)}`, 'tools') : ''}</div></div>
      <div class="md-acts">${act ? html`<a class="btn btn-primary" href="#/maintenance/${act.id}">${UI.icon('tools')} أمر الصيانة الحالي</a>` : Data.maint.canWork() && a.status !== 'retired' ? html`<button type="button" class="btn btn-primary" data-mdin="${a.id}">${UI.icon('tools')} استلام للصيانة</button>` : ''}<button type="button" class="btn btn-ghost" data-asset="${a.id}">${UI.icon('info')} بطاقة الوحدة</button></div></div>
    <div class="md-grid mt">
      <dl class="kv"><dt>الرقم التسلسلي</dt><dd class="ltr" style="text-align:start">${a.serial}</dd>${a.tag ? html`<dt>رقم الأصل</dt><dd class="ltr" style="text-align:start">${a.tag}</dd>` : ''}${a.host ? html`<dt>اسم الجهاز في الشبكة</dt><dd class="ltr" style="text-align:start">${a.host}</dd>` : ''}<dt>الصنف</dt><dd>${IC.label(it.categoryId) || '—'}</dd>${a.addedAt ? html`<dt>سُجّل في</dt><dd>${fmtDate(a.addedAt)}</dd>` : ''}${a.note ? html`<dt>ملاحظة</dt><dd>${a.note}</dd>` : ''}</dl>
      <dl class="kv"><dt>${UI.icon('building')} الإدارة والقسم</dt><dd>${place || (a.status === 'in_store' ? `المخزن: ${Data.nameOf('warehouses', a.warehouseId)}` : '—')}</dd><dt>${UI.icon('user')} الحائز</dt><dd>${hu ? html`<span class="row nowrap" style="gap:6px">${UI.avatar(hu, 'av-sm')}${hu.name}</span>` : a.holder || '—'}</dd>${hu && hu.phone ? html`<dt>${UI.icon('phone')} هاتفه</dt><dd class="ltr" style="text-align:start">${hu.phone}</dd>` : ''}${hu && hu.unitId ? html`<dt>${UI.icon('layers')} موضعه</dt><dd>${orgLabel(hu.departmentId, hu.unitId, Data.list('deptUnits'))}</dd>` : ''}${loan ? html`<dt>${UI.icon('clipboard')} إعارة</dt><dd>${loan.borrower || a.holder || '—'}${loan.dueAt ? ` حتى ${fmtDate(loan.dueAt)}` : ''}</dd>` : ''}</dl>
    </div>
    ${specs.length ? html`<div class="u-sec mt"><h3>${UI.icon('info')} المواصفات</h3><dl class="kv">${specs.map(([k, v]) => html`<dt>${lab(k)}</dt><dd>${Array.isArray(v) ? v.join('، ') : v}${a && a.specs && String(a.specs[k] == null ? '' : a.specs[k]).trim() ? html` <span class="chip tone-violet mdb-own" title="عُدِّلت لهذا الجهاز وحده">لهذا الجهاز</span>` : ''}</dd>`)}</dl></div>` : ''}
    ${Pages.maintAdds(hist)}
    ${tks.length ? html`<div class="u-sec mt"><h3>${UI.icon('ticket')} بلاغات مفتوحة لحائز الجهاز</h3><div class="list">${tks.map((t) => html`<a class="list-row" href="#/tickets/${t.id}"><span class="ltr faint small">${t.number}</span><b class="grow ellipsis">${t.title}</b>${UI.status(t.status)}</a>`)}</div></div>` : ''}
    <div class="u-sec mt"><h3>${UI.icon('tools')} سجل الصيانة${hist.length ? ` (${fmtNum(hist.length)})` : ''}</h3>${hist.length ? html`${Pages.maintSummary(hist)}${Pages.maintTimeline(hist)}` : html`<p class="faint small" style="margin:0">لم يدخل الصيانة من قبل.</p>`}</div>
  </div></div>`;
};
/* استلام الجهاز: سبب الدخول ووصف العطل ومن أحضره والملحقات، وربط ببلاغ. وللجهاز غير المسجل بياناته ومكانه */
Pages.maintIntakeModal = async (assetId, serial = '') => {
  const a = assetId ? await DB.get('assets', assetId) : null, it = a ? await DB.get('items', a.itemId) : null;
  const hu = a && a.holderId ? Data.c.users.get(a.holderId) : null;
  const tks = hu ? (await DB.getAll('tickets', 'requester_createdAt', KR([hu.id, 0], [hu.id, Infinity]))).filter((t) => OPEN.includes(t.status)).reverse() : [];
  const units = await DB.getAll('deptUnits');
  return UI.modal({
    title: a ? `استلام ${it ? it.name : 'الجهاز'} للصيانة` : 'استلام جهاز غير مسجل للصيانة', icon: 'tools', size: 'lg',
    body: html`${a ? html`<div class="banner tone-sky">${UI.icon('info')}<div class="grow"><b class="ltr">${a.serial}</b> — يبقى في عهدة ${Data.maint.placeText(a, units)}، وتصير حالته «تحت الصيانة» حتى يُسلَّم إلى المكان نفسه.</div></div>` : html`<div class="banner tone-amber">${UI.icon('alert')}<div class="grow">الرقم <b class="ltr">${serial}</b> غير مسجل في المخزن. أدخل بياناته ليُحفظ سجل صيانته ويُرجع إليه كلما عاد.</div></div>
      <div class="form-grid mt">${UI.field({ name: 'mname', label: 'الجهاز أو نوعه', required: true, placeholder: 'مثال: حاسب مكتبي، طابعة ليزر' })}${UI.field({ name: 'mbrand', label: 'الماركة' })}${UI.field({ name: 'mmodel', label: 'الموديل' })}<div class="field"><label>الإدارة والفرع</label>${PlacePick.html({ name: 'mplace', none: '— غير محدد —', any: true, clear: true })}</div>${UI.field({ name: 'mholderId', label: 'الحائز (حساب)', type: 'select', options: UI.userOpts() })}${UI.field({ name: 'mholder', label: 'أو اسم الحائز', placeholder: 'إن لم يكن له حساب' })}</div>`}
      <div class="form-grid mt">
        ${UI.field({ name: 'reason', label: 'سبب دخول الصيانة', type: 'select', placeholder: false, options: MAINT_REASONS.map((r) => ({ value: r, label: r })) })}
        ${UI.field({ name: 'broughtBy', label: 'أحضره', placeholder: 'اسم من سلّم الجهاز' }, hu ? hu.name : a ? a.holder || '' : '')}
        ${UI.field({ name: 'symptom', label: 'وصف العطل كما ذكره صاحبه', type: 'textarea', rows: 3, wide: true, placeholder: 'ما المشكلة؟ متى بدأت؟' })}
        ${UI.field({ name: 'accessories', label: 'ما استُلم معه', placeholder: 'مثال: شاحن، حقيبة، كابل طاقة' })}
        ${tks.length ? UI.field({ name: 'ticketSel', label: 'مرتبط ببلاغ لحائزه', type: 'select', options: tks.map((t) => ({ value: t.number, label: `${t.number} — ${t.title}` })) }) : ''}
        ${UI.field({ name: 'ticketNo', label: tks.length ? 'أو رقم بلاغ آخر' : 'مرتبط ببلاغ (اختياري)', dir: 'ltr', placeholder: 'IT-2026-00020 أو 20' })}
      </div>`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'استلام وفتح أمر الصيانة', kind: 'primary', icon: 'tools', submit: true, handler: async (form) => {
      const v = UI.formValues(form), pl = orgPlaceOf(v.mplace || '');
      const rec = await Data.maint.intake({ assetId: a ? a.id : '', serial, reason: v.reason, symptom: v.symptom, broughtBy: v.broughtBy, accessories: v.accessories, ticketNo: v.ticketNo || v.ticketSel || '', manual: a ? null : { name: v.mname, brand: v.mbrand, model: v.mmodel, departmentId: pl.departmentId, unitId: pl.unitId, holderId: v.mholderId || '', holder: v.mholder } });
      UI.toast('استُلم الجهاز وفُتح أمر صيانته'); UI.sound('success'); return rec;
    } }]
  });
};
Pages.maintFinishModal = (r) => UI.modal({
  title: `${r.status === 'open' ? 'إنهاء صيانة' : 'تعديل ما تم في صيانة'} ${r.itemName}`, icon: 'check', size: 'lg',
  body: html`<p class="muted small" style="margin:0 0 10px">يُحفظ هذا مع الجهاز، ويظهر في سجله كلما عاد للصيانة.</p><div class="form-grid">
    ${UI.field({ name: 'workDone', label: 'ما تم في الصيانة', type: 'textarea', rows: 3, required: true, wide: true, placeholder: 'مثال: فحص مزود الطاقة واستبداله، تنظيف داخلي، تحديث التعريفات' }, r.workDone)}
    ${UI.field({ name: 'parts', label: 'القطع المستبدلة', placeholder: 'مثال: مزود طاقة 500W' }, r.parts)}
    ${UI.field({ name: 'additions', label: 'الإضافات على الجهاز', placeholder: 'مثال: ذاكرة 8GB، قرص SSD 512GB' }, r.additions)}
    ${UI.field({ name: 'changes', label: 'التعديلات', type: 'textarea', rows: 2, wide: true, placeholder: 'مثال: إعادة تثبيت النظام، تغيير اسم الجهاز، ضبط الطابعة الافتراضية' }, r.changes)}
    ${UI.field({ name: 'notes', label: 'ملاحظات', type: 'textarea', rows: 2, wide: true, placeholder: 'ما يجب أن يعرفه من يصونه لاحقاً' }, r.notes)}
    ${UI.field({ name: 'result', label: 'النتيجة', type: 'select', placeholder: false, options: [{ value: 'repaired', label: 'تم الإصلاح ويعمل' }, { value: 'unrepairable', label: 'تعذر الإصلاح — يحتاج قرار المخزن' }] }, r.result || 'repaired')}
  </div>`,
  actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ', kind: 'primary', icon: 'check', submit: true, handler: async (form) => { const out = await Data.maint.finish(r.id, UI.formValues(form)); UI.toast(out.status === 'unrepairable' ? 'سُجّل تعذر الإصلاح وأُبلغ المخزن' : 'حُفظت نتيجة الصيانة'); return out; } }]
});
Pages.maintDeliverModal = (r) => {
  const hu = r.fromHolderId ? Data.c.users.get(r.fromHolderId) : null;
  return UI.modal({
    title: `تسليم ${r.itemName} بعد الصيانة`, icon: 'undo', size: 'lg',
    body: html`<div class="banner tone-teal">${UI.icon('pin')}<div class="grow">يعود إلى مكانه السابق: <b>${Data.maint.placeText(r)}</b></div></div>
      <div class="form-grid mt">
        ${UI.field({ name: 'receiverId', label: 'المستلم (حساب)', type: 'select', options: UI.userOpts() }, hu ? hu.id : '')}
        ${UI.field({ name: 'receiverName', label: 'أو اسم المستلم', placeholder: 'إن لم يكن له حساب' }, hu ? '' : r.fromHolder || '')}
        <div class="field wide"><label>طريقة التسليم</label><div class="seg"><label><input type="radio" name="mode" value="now" checked><span>${UI.icon('check')} سُلّم الآن يداً بيد</span></label><label><input type="radio" name="mode" value="confirm"><span>${UI.icon('send')} يؤكد المستلم من حسابه</span></label></div></div>
        ${UI.field({ name: 'note', label: 'ملاحظة التسليم', type: 'textarea', rows: 2, wide: true, placeholder: 'مثال: سُلّم مع الشاحن' })}
      </div>`,
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تسليم', kind: 'ok', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); const out = await Data.maint.deliver(r.id, v); UI.toast(out.status === 'sent' ? 'أُرسل للمستلم ليؤكد الاستلام' : 'سُلّم الجهاز وعاد إلى مكانه'); return out; } }]
  });
};
/* أمر الصيانة */
Pages.maintOrder = async (ctx) => {
  const id = ctx.params.id;
  const draw = async () => {
    const r = await DB.get('maintenance', id); if (!ctx.alive()) return;
    if (!r) { ctx.view.innerHTML = String(UI.empty({ illu: 'tools', title: 'أمر الصيانة غير موجود', action: html`<a class="btn btn-primary" href="#/maintenance">الصيانة</a>` })); return; }
    const S = MAINT_STATUS[r.status] || MAINT_STATUS.open, can = Data.maint.canWork() && (r.keep || Auth.can('inventory.move'));
    const prev = (await Data.maint.bySerial(r.serial)).filter((x) => x.id !== r.id), units = await DB.getAll('deptUnits'); if (!ctx.alive()) return;
    const acts = [];
    if (can && r.keep && r.status === 'open') acts.push(html`<button class="btn btn-soft" data-mo="log">${UI.icon('edit')} ملاحظة متابعة</button>`, html`<button class="btn btn-ok" data-mo="finish">${UI.icon('check')} إنهاء الصيانة</button>`);
    if (can && r.keep && ['done', 'unrepairable'].includes(r.status)) acts.push(html`<button class="btn btn-ghost" data-mo="finish">${UI.icon('edit')} تعديل ما تم</button>`, html`<button class="btn btn-primary" data-mo="deliver">${UI.icon('undo')} تسليم الجهاز</button>`);
    if (r.status === 'unrepairable' && r.assetId && Auth.can('inventory.move')) acts.push(html`<button class="btn btn-danger" data-mo="retire">${UI.icon('x')} إخراج من الخدمة</button>`);
    acts.push(html`<button class="icon-btn" data-mo="print" title="طباعة سند الصيانة">${UI.icon('print')}</button>`);
    const kv = (l, v) => (v ? html`<dt>${l}</dt><dd>${v}</dd>` : '');
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ crumbs: html`<a href="#/maintenance">الصيانة</a>${UI.icon('chevron-left')}<span class="ltr">${r.serial || '—'}</span>`, title: r.itemName, illu: 'tools', sub: html`<span class="row" style="gap:8px;margin-top:6px">${UI.chip(S.tone, S.label, S.icon)}<span class="faint small">استُلم ${timeAgo(r.openedAt)} بواسطة ${Data.userName(r.openedBy)}</span></span>`, actions: acts })}
      <div class="grid g-side">
        <div class="stack">
          ${UI.panel({ title: 'الاستلام', icon: 'inbox', body: html`<dl class="kv">${kv('سبب الدخول', r.reason)}${kv('وصف العطل', r.symptom)}${kv('أحضره', r.broughtBy)}${kv('ما استُلم معه', r.accessories)}${r.ticketId ? html`<dt>البلاغ</dt><dd><a href="#/tickets/${r.ticketId}" class="ltr">${r.ticketNo || 'فتح البلاغ'}</a></dd>` : ''}<dt>استلمه</dt><dd>${Data.userName(r.openedBy)} — ${fmtDateTime(r.openedAt)}</dd></dl>` })}
          ${r.keep ? UI.panel({ title: `المتابعة${(r.log || []).length ? ` (${fmtNum(r.log.length)})` : ''}`, icon: 'pulse', body: (r.log || []).length ? html`<div class="timeline">${r.log.map((x) => html`<div class="tl"><span class="tl-icon tone-sky">${UI.icon('edit')}</span><div style="min-width:0"><div class="tl-head"><b>${Data.userName(x.by)}</b><span class="tl-time" title="${fmtDateTime(x.at)}">${timeAgo(x.at)}</span></div><div class="bubble">${x.text}</div></div></div>`)}</div>` : html`<p class="faint small" style="margin:0">لا ملاحظات بعد. سجّل ما تكتشفه أثناء العمل بزر «ملاحظة متابعة».</p>` }) : ''}
          ${r.closedAt ? UI.panel({ title: r.status === 'unrepairable' || r.result === 'unrepairable' ? 'النتيجة: تعذر الإصلاح' : 'ما تم في الصيانة', icon: 'check', body: html`<dl class="kv">${kv('ما تم', r.workDone)}${kv('القطع المستبدلة', r.parts)}${kv('الإضافات', r.additions)}${kv('التعديلات', r.changes)}${kv('ملاحظات', r.notes)}<dt>أنهاه</dt><dd>${Data.userName(r.closedBy)} — ${fmtDateTime(r.closedAt)}${r.editedAt ? html` <span class="faint small">(عُدّل ${timeAgo(r.editedAt)})</span>` : ''}</dd></dl>` }) : ''}
          ${r.returnedAt ? UI.panel({ title: 'التسليم', icon: 'undo', body: html`<dl class="kv"><dt>المستلم</dt><dd>${r.receiverName || '—'}</dd><dt>إلى</dt><dd>${Data.maint.placeText(r, units)}</dd><dt>سلّمه</dt><dd>${Data.userName(r.returnedBy)} — ${fmtDateTime(r.returnedAt)}</dd>${kv('ملاحظة التسليم', r.handoverNote)}<dt>الاستلام</dt><dd>${r.status === 'sent' ? UI.chip('violet', 'بانتظار تأكيد المستلم', 'send') : r.receivedConfirm ? UI.chip('green', `أكّده المستلم ${fmtDateTime(r.receivedAt)}`, 'check') : UI.chip('green', 'سُلّم يداً بيد', 'check')}</dd></dl>` }) : ''}
          ${prev.length ? UI.panel({ title: `صيانات سابقة لهذا الجهاز (${fmtNum(prev.length)})`, icon: 'clock', body: html`${Pages.maintSummary(prev)}${Pages.maintTimeline(prev)}` }) : ''}
        </div>
        <div class="stack">
          ${UI.panel({ title: 'الجهاز', icon: 'box', body: html`<dl class="kv"><dt>الرقم التسلسلي</dt><dd class="ltr" style="text-align:start">${r.serial || '—'}</dd>${r.tag ? html`<dt>رقم الأصل</dt><dd class="ltr" style="text-align:start">${r.tag}</dd>` : ''}${kv('الماركة والموديل', [r.brand, r.model].filter(Boolean).join(' '))}<dt>${r.status === 'returned' || r.status === 'sent' ? 'مكانه' : 'يعود إلى'}</dt><dd>${Data.maint.placeText(r, units)}</dd>${r.registered === 0 ? html`<dt>التسجيل</dt><dd>${UI.chip('amber', 'غير مسجل في المخزن', 'alert')}</dd>` : ''}</dl>${r.assetId ? html`<button type="button" class="btn btn-ghost btn-sm mt" data-asset="${r.assetId}">${UI.icon('info')} بطاقة الوحدة</button>` : ''}` })}
          ${Pages.maintAdds(prev).toString() ? UI.panel({ title: 'الجهاز من صياناته السابقة', icon: 'plus', body: Pages.maintAdds(prev) }) : ''}
        </div>
      </div>`);
    UI.hydrate(ctx.view);
  };
  UI.on(ctx.view, 'click', '[data-mo]', async (e, el) => {
    const r = await DB.get('maintenance', id); if (!r) return; const a = el.dataset.mo;
    try {
      if (a === 'print') return Pages.printMaint(r);
      if (a === 'finish') { if (await Pages.maintFinishModal(r)) draw(); return; }
      if (a === 'deliver') { if (await Pages.maintDeliverModal(r)) draw(); return; }
      if (a === 'log') { const v = await UI.modal({ title: 'ملاحظة متابعة', icon: 'edit', body: UI.field({ name: 'text', label: 'ما الذي وجدته أو فعلته؟', type: 'textarea', rows: 3, required: true }), actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ', kind: 'primary', icon: 'check', submit: true, handler: (form) => UI.formValues(form).text }] }); if (v) { await Data.maint.addLog(id, v); draw(); } return; }
      if (a === 'retire') { const n = await Pages.retireModal(r.itemId, { departmentId: r.fromDepartmentId }); if (n) { const x = await DB.get('maintenance', id); await DB.put('maintenance', { ...x, status: 'retired', retireReason: 'تعذر الإصلاح', updatedAt: now() }); draw(); } }
    } catch (ex) { UI.error(ex); }
  });
  ctx.onCleanup(Bus.on('inventory', debounce(() => { if (ctx.alive() && !$('dialog[open]')) draw(); }, 400)));
  await draw();
};
/* صفحة المستلم: يرى جهازه وما تم فيه، ويؤكد استلامه إن كان المستلم المعيَّن */
Pages.maintReceipt = async (ctx) => {
  const id = ctx.params.id;
  const draw = async () => {
    const r = await DB.get('maintenance', id); if (!ctx.alive()) return;
    if (!r) { ctx.view.innerHTML = String(UI.empty({ illu: 'tools', title: 'لا يتوفر سجل الصيانة', text: 'ربما لم يصل جهازك بعد. حاول بعد قليل.' })); return; }
    const S = MAINT_STATUS[r.status] || MAINT_STATUS.open, mine = r.receiverId === Auth.user.id && r.status === 'sent';
    const kv = (l, v) => (v ? html`<dt>${l}</dt><dd>${v}</dd>` : '');
    ctx.view.innerHTML = String(html`${UI.pageHead({ title: `صيانة ${r.itemName}`, illu: 'tools', sub: html`<span class="row" style="gap:8px;margin-top:6px">${UI.chip(S.tone, S.label, S.icon)}<span class="ltr faint small">${r.serial}</span></span>` })}
      ${mine ? html`<div class="banner tone-violet md-confirm">${UI.icon('send')}<div class="grow"><b>سُلّم إليك هذا الجهاز بعد الصيانة.</b> أكّد استلامه ليُسجَّل.</div><button type="button" class="btn btn-primary" data-mrok>${UI.icon('check')} تأكيد الاستلام</button></div>` : ''}
      <section class="panel"><div class="panel-body"><dl class="kv">${kv('الجهاز', [r.itemName, r.brand, r.model].filter(Boolean).join(' '))}${kv('مكانه', Data.maint.placeText(r))}${kv('سبب الدخول', r.reason)}${kv('وصف العطل', r.symptom)}<dt>استُلم للصيانة</dt><dd>${fmtDateTime(r.openedAt)}</dd>${kv('ما تم', r.workDone)}${kv('القطع المستبدلة', r.parts)}${kv('الإضافات', r.additions)}${kv('التعديلات', r.changes)}${kv('ملاحظات', r.notes)}${r.returnedAt ? html`<dt>سُلّم</dt><dd>${fmtDateTime(r.returnedAt)}${r.receiverName ? ` إلى ${r.receiverName}` : ''}</dd>` : ''}${r.receivedConfirm ? html`<dt>تأكيد الاستلام</dt><dd>${fmtDateTime(r.receivedAt)}</dd>` : ''}</dl></div></section>`);
  };
  UI.on(ctx.view, 'click', '[data-mrok]', async (e, el) => { UI.busy(el, true); try { await Data.maint.confirmReceipt(id); UI.toast('شكراً، سُجّل استلامك للجهاز'); draw(); } catch (ex) { UI.error(ex); UI.busy(el, false); } });
  ctx.onCleanup(Bus.on('inventory', debounce(() => { if (ctx.alive()) draw(); }, 400)));
  await draw();
};

/* صفحة الصيانة */
Pages.maintenance = async (ctx) => {
  const st = { tab: 'open', q: '', from: '', to: '', sn: ctx.query.sn || '' };
  const draw = async () => {
    const all = (await Data.maint.list()).sort((a, b) => b.openedAt - a.openedAt);
    if (!ctx.alive()) return;
    const inRange = (r) => { const f = st.from ? startOfDay(fromDateInput(st.from, true)) : 0, t = st.to ? startOfDay(fromDateInput(st.to, true)) + DAY - 1 : Infinity; return r.openedAt >= f && r.openedAt <= t; };
    const qn = normalizeAr(st.q);
    const rows = all.filter((r) => (st.tab === 'all' || r.status === st.tab) && inRange(r) && (!qn || normalizeAr(`${r.itemName} ${r.serial} ${r.tag} ${r.reason} ${r.workDone} ${Data.nameOf('departments', r.fromDepartmentId, '')}`).includes(qn)));
    const count = (s) => all.filter((r) => r.status === s).length;
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ title: 'الصيانة', sub: 'استلام الأجهزة برقمها التسلسلي، وما تم فيها، وتسليمها إلى مواقعها، مع سجل كل صيانة سابقة', illu: 'tools', actions: html`${Auth.can('inventory.move') ? html`<button class="btn btn-ghost" data-act="send" title="يخرج الجهاز من رصيد عهدة الإدارة حتى يُرجع">${UI.icon('tools')} إرسال من العهدة</button>` : ''}${Auth.can('inventory.read') ? html`<a class="btn btn-ghost" href="#/inventory/retired">${UI.icon('x')} الخارج عن الخدمة</a>` : ''}<button class="btn btn-ghost" data-act="xls">${UI.icon('download')} تصدير</button>` })}
      ${Data.maint.canWork() ? html`<section class="panel md-find"><div class="panel-body"><form class="md-search" data-mdfind><span class="md-ic">${UI.icon('tools')}</span><div class="grow"><label for="mdsn"><b>استلام جهاز أو البحث عنه</b><span class="faint small"> — أدخل الرقم التسلسلي أو رقم الأصل لعرض كل بياناته ومكانه وسجل صيانته</span></label><div class="row nowrap" style="gap:8px;margin-top:6px"><input id="mdsn" class="input ltr" dir="ltr" autocomplete="off" placeholder="SN / Asset tag" value="${st.sn}"><button type="submit" class="btn btn-primary">${UI.icon('search')} عرض الجهاز</button>${UI.scanBtn('mdsn', 'btn btn-soft')}</div></div></form><div data-mdout></div></div></section>` : ''}
      <div class="kpis">
        ${UI.kpi({ label: 'تحت الصيانة', icon: 'tools', tone: 'sky', value: count('open') })}
        ${UI.kpi({ label: 'بانتظار التسليم', icon: 'check', tone: 'teal', value: count('done') + count('unrepairable') })}
        ${UI.kpi({ label: 'أُرجعت للمواقع', icon: 'undo', tone: 'green', value: count('returned') })}
        ${UI.kpi({ label: 'خارجة عن الخدمة', icon: 'x', tone: 'red', value: count('retired') })}
      </div>
      <section class="panel mt"><div class="toolbar">
        <div class="tabs">${[['open', 'تحت الصيانة'], ['done', 'بانتظار التسليم'], ['unrepairable', 'تعذر إصلاحها'], ['sent', 'بانتظار تأكيد المستلم'], ['returned', 'مكتملة'], ['retired', 'خارجة عن الخدمة'], ['all', 'الكل']].filter(([k]) => k === 'all' || ['open', 'done', 'returned'].includes(k) || count(k)).map(([k, l]) => html`<button class="tab${st.tab === k ? ' active' : ''}" data-tab="${k}">${l}${count(k) && k !== 'all' ? html`<span class="count">${fmtNum(count(k))}</span>` : ''}</button>`)}</div>
        <div class="search-box">${UI.icon('search')}<input id="mq" type="search" placeholder="الجهاز أو الرقم التسلسلي أو الإدارة" value="${st.q}"></div>
        <div class="range-bar"><span class="faint small">من</span><input type="date" id="mFrom" dir="ltr" lang="en-GB" value="${st.from}"><span class="faint small">إلى</span><input type="date" id="mTo" dir="ltr" lang="en-GB" value="${st.to}"></div>
      </div>
      ${rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>الجهاز</th><th>الرقم التسلسلي</th><th>من</th><th>السبب</th><th>الحالة</th><th>التاريخ</th><th></th></tr></thead><tbody class="stagger">${rows.slice(0, 200).map((r) => html`<tr><td><button type="button" class="t-title link-title" data-device="${r.itemId}"><div><div>${r.itemName}</div><div class="t-sub">${[r.brand, r.model].filter(Boolean).join(' ')}</div></div></button></td><td class="t-num ltr">${r.serial || '—'}${r.tag ? html`<div class="t-sub ltr" style="text-align:start">أصل: ${r.tag}</div>` : ''}</td><td class="small">${Data.nameOf('departments', r.fromDepartmentId, '—')}</td><td class="small">${r.reason}</td><td>${UI.chip(MAINT_STATUS[r.status].tone, MAINT_STATUS[r.status].label, MAINT_STATUS[r.status].icon)}</td><td class="faint nowrap">${fmtDate(r.openedAt)}</td><td class="nowrap">${r.keep ? html`<a class="btn btn-sm ${MAINT_ACTIVE.includes(r.status) ? 'btn-primary' : 'btn-ghost'}" href="#/maintenance/${r.id}">${UI.icon(MAINT_ACTIVE.includes(r.status) ? 'tools' : 'eye')} أمر الصيانة</a>` : Auth.can('inventory.move') ? html`${r.status === 'open' ? html`<button class="btn btn-sm btn-ok" data-done="${r.id}">${UI.icon('check')} إنهاء الصيانة</button>` : ''}${r.status === 'done' ? html`<button class="btn btn-sm btn-primary" data-back="${r.id}">${UI.icon('undo')} إرجاع للموقع</button>` : ''}` : ''}<button class="btn btn-ghost btn-sm" data-print="${r.id}">${UI.icon('print')}</button></td></tr>`)}</tbody></table></div>`
        : html`<div class="panel-body">${UI.empty({ illu: 'tools', title: 'لا توجد سجلات صيانة', text: 'أرسل جهازاً للصيانة من صفحة العهدة أو من بطاقة الجهاز.' })}</div>`}</section>`);
    UI.hydrate(ctx.view);
    ctx.rows = rows;
    if (st.sn) showDevice(st.sn, false);
    $('#mq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); draw(); }, 250));
    ['mFrom', 'mTo'].forEach((id) => { const el = $('#' + id, ctx.view); if (el) el.onchange = () => { st[id === 'mFrom' ? 'from' : 'to'] = el.value; draw(); }; });
  };
  UI.on(ctx.view, 'click', '[data-tab]', (e, el) => { st.tab = el.dataset.tab; draw(); });
  /* عرض الجهاز بالرقم التسلسلي، ثم الاستلام */
  const showDevice = async (sn, scroll = true) => {
    const out = $('[data-mdout]', ctx.view); if (!out) return;
    st.sn = String(sn || '').trim(); try { history.replaceState(history.state, '', `#/maintenance${st.sn ? `?sn=${encodeURIComponent(st.sn)}` : ''}`); } catch (_) { /* تجاهل */ }
    out.innerHTML = st.sn ? String(await Pages.maintDeviceCard(st.sn)) : ''; UI.hydrate(out);
    if (scroll && out.firstElementChild) out.firstElementChild.scrollIntoView({ block: 'nearest', behavior: UI.reduced() ? 'auto' : 'smooth' });
  };
  ctx.view.addEventListener('submit', (e) => { if (!e.target.matches('[data-mdfind]')) return; e.preventDefault(); const v = ($('#mdsn', ctx.view) || {}).value || ''; if (!v.trim()) { UI.toast('أدخل الرقم التسلسلي', 'warn'); return; } showDevice(v); });
  UI.on(ctx.view, 'click', '[data-mdin]', async (e, el) => { const rec = await Pages.maintIntakeModal(el.dataset.mdin, el.dataset.mdsn || st.sn); if (rec) Router.go(`/maintenance/${rec.id}`); });
  UI.on(ctx.view, 'click', '[data-device]', async (e, el) => { await Pages.deviceModal(el.dataset.device, {}); });
  UI.on(ctx.view, 'click', '[data-done]', async (e, el) => { const r = await DB.get('maintenance', el.dataset.done); if (r && (await Pages.maintDoneModal(r))) { st.tab = 'done'; draw(); } });
  UI.on(ctx.view, 'click', '[data-back]', async (e, el) => { const r = await DB.get('maintenance', el.dataset.back); if (r && (await Pages.maintBackModal(r))) draw(); });
  UI.on(ctx.view, 'click', '[data-print]', async (e, el) => { const r = await DB.get('maintenance', el.dataset.print); if (r) Pages.printMaint(r); });
  UI.on(ctx.view, 'click', '[data-act="send"]', async () => { const id = await Pages.pickItemModal('اختر الجهاز المطلوب إرساله للصيانة'); if (id && (await Pages.maintSendModal(id, {}))) draw(); });
  UI.on(ctx.view, 'click', '[data-act="xls"]', () => {
    const rows = ctx.rows || [];
    downloadBlob(XL.write([{ name: 'الصيانة', widths: [30, 18, 20, 22, 18, 30, 18, 16], rows: [['الجهاز', 'الرقم التسلسلي', 'الإدارة', 'السبب', 'الحالة', 'ما تم في الصيانة', 'القطع', 'التاريخ'], ...rows.map((r) => [r.itemName, r.serial || '', Data.nameOf('departments', r.fromDepartmentId, ''), r.reason, MAINT_STATUS[r.status].label, r.workDone || '', r.parts || '', fmtDate(r.openedAt)])] }]), `تقرير-الصيانة-${dateInput(now())}.xlsx`);
    UI.toast('تم التصدير');
  });
  Pages.bindInv(ctx, draw);
  await draw();
};
Pages.printMaint = (r) => UI.print(html`<h2 style="text-align:center">سند صيانة جهاز</h2>
  <table><tr><th>الجهاز</th><td>${r.itemName}</td><th>الماركة والموديل</th><td>${[r.brand, r.model].filter(Boolean).join(' ') || '—'}</td></tr>
    <tr><th>الرقم التسلسلي</th><td class="ltr">${r.serial || '—'}</td><th>رقم الأصل</th><td class="ltr">${r.tag || '—'}</td></tr>
    <tr><th>الإدارة</th><td>${Data.nameOf('departments', r.fromDepartmentId, '—')}</td><th>تاريخ الإرسال</th><td>${fmtDateTime(r.openedAt)}</td></tr>
    <tr><th>سبب الإرسال</th><td>${r.reason}</td><th>الحالة</th><td>${MAINT_STATUS[r.status].label}</td></tr>
    <tr><th>أرسله للصيانة</th><td>${who(r.openedBy)}</td><th>الفني المنفذ</th><td>${r.closedBy ? who(r.closedBy) : '—'}</td></tr>
    <tr><th>وصف العطل</th><td colspan="3">${r.symptom || '—'}</td></tr>
    <tr><th>ما تم في الصيانة</th><td colspan="3">${r.workDone || '—'}</td></tr>
    <tr><th>القطع المستخدمة</th><td colspan="3">${r.parts || '—'}</td></tr>
    ${r.additions ? html`<tr><th>الإضافات</th><td colspan="3">${r.additions}</td></tr>` : ''}${r.changes ? html`<tr><th>التعديلات</th><td colspan="3">${r.changes}</td></tr>` : ''}${r.notes ? html`<tr><th>ملاحظات</th><td colspan="3">${r.notes}</td></tr>` : ''}
    ${r.keep ? html`<tr><th>مكان الجهاز</th><td colspan="3">${Data.maint.placeText(r)}</td></tr>${r.accessories ? html`<tr><th>ما استُلم معه</th><td colspan="3">${r.accessories}</td></tr>` : ''}${r.receiverName ? html`<tr><th>المستلم</th><td>${r.receiverName}</td><th>تاريخ التسليم</th><td>${r.returnedAt ? fmtDateTime(r.returnedAt) : '—'}</td></tr>` : ''}` : ''}
    ${r.returnedAt ? html`<tr><th>تاريخ الإرجاع</th><td>${fmtDateTime(r.returnedAt)}</td><th>أُرجع إلى</th><td>${Data.nameOf('departments', r.toDepartmentId, '—')}</td></tr>` : ''}</table>
  ${UI.signBlock([{ title: 'الفني المنفّذ للصيانة', userId: r.closedBy || r.openedBy }, { title: 'مستلم الجهاز' }])}`, `سند صيانة ${r.itemName}`);

/* سجل الأجهزة الخارجة عن الخدمة */
Pages.retired = async (ctx) => {
  const st = { q: '', from: '', to: '' };
  const draw = async () => {
    const assets = (await DB.getAll('assets')).filter((a) => a.status === 'retired');
    const maint = await Data.maint.list();
    if (!ctx.alive()) return;
    const info = new Map(maint.filter((m) => m.status === 'retired').map((m) => [m.assetId, m]));
    const items = new Map((await DB.getAll('items')).map((i) => [i.id, i]));
    const qn = normalizeAr(st.q);
    const rows = assets.filter((a) => {
      const f = st.from ? startOfDay(fromDateInput(st.from, true)) : 0, t = st.to ? startOfDay(fromDateInput(st.to, true)) + DAY - 1 : Infinity;
      const at = a.retiredAt || a.updatedAt || 0;
      return at >= f && at <= t && (!qn || normalizeAr(`${a.serial} ${a.tag || ''} ${(items.get(a.itemId) || {}).name || ''} ${a.retireReason || ''} ${Data.nameOf('departments', a.retiredFrom, '')}`).includes(qn));
    }).sort((a, b) => (b.retiredAt || 0) - (a.retiredAt || 0));
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ title: 'الأجهزة الخارجة عن الخدمة', sub: 'الأجهزة التي أُخرجت من الخدمة أو التالفة، لا تُحتسب ضمن أرصدة المخزن ولا عهد الإدارات', illu: 'box', actions: html`<a class="btn btn-ghost" href="#/maintenance">${UI.icon('tools')} الصيانة</a><button class="btn btn-ghost" data-act="xls">${UI.icon('download')} تصدير</button>` })}
      <div class="kpis">${UI.kpi({ label: 'إجمالي الخارجة عن الخدمة', icon: 'x', tone: 'red', value: assets.length })}${UI.kpi({ label: 'خلال 90 يوماً', icon: 'clock', tone: 'amber', value: assets.filter((a) => now() - (a.retiredAt || 0) < 90 * DAY).length })}${UI.kpi({ label: 'إدارات متأثرة', icon: 'building', tone: 'violet', value: new Set(assets.map((a) => a.retiredFrom).filter(Boolean)).size })}</div>
      <section class="panel mt"><div class="toolbar"><div class="search-box">${UI.icon('search')}<input id="rq" type="search" placeholder="الرقم التسلسلي أو الجهاز أو السبب" value="${st.q}"></div><div class="range-bar"><span class="faint small">من</span><input type="date" id="rFrom" dir="ltr" lang="en-GB" value="${st.from}"><span class="faint small">إلى</span><input type="date" id="rTo" dir="ltr" lang="en-GB" value="${st.to}"></div></div>
      ${rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>الجهاز</th><th>الرقم التسلسلي</th><th>سبب الإخراج من الخدمة</th><th>كان في</th><th>البديل</th><th>التاريخ</th></tr></thead><tbody class="stagger">${rows.slice(0, 200).map((a) => { const it = items.get(a.itemId) || {}, m = info.get(a.id) || {}; return html`<tr><td><button type="button" class="t-title link-title" data-asset="${a.id}">${UI.illu(itemIllu(it))}<div><div>${it.name || 'صنف محذوف'}</div><div class="t-sub">${[it.brand, it.model].filter(Boolean).join(' ')}</div></div></button></td><td class="t-num ltr">${a.serial}${a.tag ? html`<div class="t-sub ltr" style="text-align:start">أصل: ${a.tag}</div>` : ''}</td><td class="small">${a.retireReason || m.retireReason || '—'}</td><td class="small">${Data.nameOf('departments', a.retiredFrom, '—')}</td><td class="small">${a.replacedBy || '—'}</td><td class="faint nowrap">${a.retiredAt ? fmtDate(a.retiredAt) : '—'}</td></tr>`; })}</tbody></table></div>` : html`<div class="panel-body">${UI.empty({ illu: 'box', title: 'لا توجد أجهزة خارجة عن الخدمة', text: 'الأجهزة التي تُخرج من الخدمة أو يتعذر إصلاحها تظهر هنا مع أسبابها.' })}</div>`}</section>`);
    UI.hydrate(ctx.view); ctx.rows = rows; ctx.items = items;
    $('#rq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); draw(); }, 250));
    ['rFrom', 'rTo'].forEach((id) => { const el = $('#' + id, ctx.view); if (el) el.onchange = () => { st[id === 'rFrom' ? 'from' : 'to'] = el.value; draw(); }; });
  };
  UI.on(ctx.view, 'click', '[data-device]', async (e, el) => { await Pages.deviceModal(el.dataset.device, {}); });
  UI.on(ctx.view, 'click', '[data-act="xls"]', () => {
    const rows = ctx.rows || [], items = ctx.items || new Map();
    downloadBlob(XL.write([{ name: 'خارج الخدمة', widths: [30, 18, 26, 22, 22, 16], rows: [['الجهاز', 'الرقم التسلسلي', 'سبب الإخراج من الخدمة', 'كان في', 'البديل', 'التاريخ'], ...rows.map((a) => { const it = items.get(a.itemId) || {}; return [it.name || '', a.serial, a.retireReason || '', Data.nameOf('departments', a.retiredFrom, ''), a.replacedBy || '', a.retiredAt ? fmtDate(a.retiredAt) : '']; })] }]), `الأجهزة-الخارجة-عن-الخدمة-${dateInput(now())}.xlsx`);
  });
  Pages.bindInv(ctx, draw);
  await draw();
};

/* اختيار صنف سريع */
Pages.pickItemModal = async (title = 'اختر الصنف') => {
  const items = (await DB.getAll('items')).sort((a, b) => String(a.name).localeCompare(String(b.name), 'ar'));
  return UI.modal({ title, icon: 'box', size: 'lg', body: html`${UI.field({ name: 'itemId', label: 'الصنف', type: 'select', required: true, options: items.map((i) => ({ value: i.id, label: `${i.name}${i.model ? ` — ${i.model}` : ''}` })), wide: true })}`, actions: [{ label: 'إلغاء', kind: 'ghost', value: null }, { label: 'متابعة', kind: 'primary', icon: 'check', submit: true, handler: (form) => form.querySelector('[name="itemId"]').value }] });
};


/* ── مكتبة النماذج والاستمارات، وأيقونات الماركات ── */
const FORM_ICONS = ['card', 'book', 'clipboard', 'paper', 'archive', 'key', 'tools', 'printer', 'computer', 'network', 'box', 'bell', 'smartcard', 'fingerprint', 'barcode', 'router'];
const canManageForms = () => canUser(Auth.user, 'users.manage') || canUser(Auth.user, 'forms.manage');
const canHideForms = () => canManageForms() || canUser(Auth.user, 'forms.hide');
Data.forms = {
  async list() { try { await this.seedBuiltin(); } catch (e) { console.warn('forms seed', e); } return (await DB.getAll('forms')).sort((a, b) => (a.order || 0) - (b.order || 0) || String(a.title).localeCompare(String(b.title), 'ar')); },
  async save(rec) {
    if (!canManageForms()) throw new AppError('لا تملك صلاحية إدارة النماذج');
    const t = now();
    const out = { id: rec.id || uid('fm'), title: String(rec.title || '').trim(), desc: String(rec.desc || '').trim(), icon: rec.icon || 'paper', categoryId: rec.categoryId || '', file: rec.file || null, order: Number(rec.order) || 0, noDownload: rec.noDownload ? 1 : 0, hidden: rec.hidden ? 1 : 0, createdAt: rec.createdAt || t, updatedAt: t, userId: rec.userId || Auth.user.id, _rev: rec._rev };
    if (!out.title) throw new AppError('اكتب اسم النموذج');
    if (!out.file) throw new AppError('ارفع ملف النموذج');
    await DB.put('forms', out);
    await Data.log('update', 'settings', out.id, `${rec.id ? 'تعديل' : 'إضافة'} نموذج: ${out.title}`);
    Bus.emit('forms', {});
    return out;
  },
  /* الاستمارات الرسمية المضمّنة في الملف تُضاف إلى المكتبة مرة واحدة فقط */
  /* علامة الإضافة محلية لكل جهاز: من يملك إدارة النماذج يرفعها للخادم، وغيره يضيفها لجهازه فقط حتى تصله نسخة الخادم */
  async seedBuiltin() {
    const flag = `sq_seed_forms_v2:${Auth.user ? Auth.user.id : ''}`; try { if (localStorage.getItem(flag)) return; } catch (_) { /* تجاهل */ }
    const CAT = [[/شبكة/, 'network', 'network'], [/مجلد/, 'service_request', 'folder'], [/بطاقة/, 'card', 'card']], t = now();
    const recs = await Promise.all($$('script[data-form]').map(async (el, i) => {
      const name = el.dataset.name || `استمارة ${i + 1}`, [, categoryId = '', icon = 'paper'] = CAT.find(([re]) => re.test(name)) || [];
      const b64 = el.dataset.src ? '' : el.textContent.trim();
      const data = el.dataset.src ? await fetch(el.dataset.src).then((r) => { if (!r.ok) throw new AppError('تعذر تحميل الاستمارة'); return r.blob(); }).then((b) => blobToDataURL(new Blob([b], { type: 'application/pdf' }))) : `data:application/pdf;base64,${b64}`;
      return { id: `fm_builtin_${i + 1}`, title: name, desc: 'استمارة رسمية معتمدة — للمعاينة والطباعة والتحميل', icon, categoryId, order: i, createdAt: t, updatedAt: t, file: { name: `${name}.pdf`, type: 'application/pdf', size: Number(el.dataset.size) || Math.round(b64.length * 0.75), at: t, data } };
    }));
    const local = Sync.on && Sync.raw && !canManageForms();
    for (const r of recs) {
      const cur = await DB.get('forms', r.id);
      if (!cur) await (local ? Sync.raw.put('forms', r) : DB.put('forms', r));
      else if (!local && Sync.on && !cur._rev) await DB.put('forms', cur); /* نسخة محلية لم تصل الخادم بعد */
    }
    try { localStorage.setItem(flag, String(t)); } catch (_) { /* تجاهل */ }
  },
  async remove(id) {
    if (!canManageForms()) throw new AppError('لا تملك صلاحية حذف النماذج');
    const rec = await DB.get('forms', id);
    await DB.del('forms', id);
    await Data.log('delete', 'settings', id, `حذف نموذج: ${rec ? rec.title : id}`);
    Bus.emit('forms', {});
  }
};
Pages.previewFile = (file) => {
  if (!file) return;
  const type = String(file.type || '');
  const body = type.includes('pdf') ? html`<iframe class="file-view" src="${file.data}" title="${file.name}"></iframe>`
    : type.startsWith('image/') ? html`<img class="file-view" src="${file.data}" alt="${file.name}">`
      : html`<div class="file-none">${UI.icon('file')}<b>${file.name}</b><span>هذا النوع لا يُعرض داخل النظام، حمّله لفتحه ببرنامجه.</span></div>`;
  return UI.modal({
    title: file.name, icon: 'file', size: 'xl',
    body,
    actions: [{ label: 'إغلاق', kind: 'ghost' }, { label: 'تحميل', kind: 'primary', icon: 'download', handler: () => { downloadBlob(dataToBlob(file.data), file.name); return false; } }]
  });
};
Pages.formModal = async (id = '') => {
  const rec = id ? await DB.get('forms', id) : { icon: 'paper' };
  return UI.modal({
    title: id ? `تعديل ${rec.title}` : 'نموذج جديد', icon: 'file', size: 'lg',
    body: html`${UI.fields([{ name: 'title', label: 'اسم النموذج', required: true, wide: true, placeholder: 'مثال: استمارة طلب بطاقة دخول' }, { name: 'desc', label: 'وصف مختصر', type: 'textarea', rows: 2, wide: true, placeholder: 'لمن هذا النموذج ومتى يُستخدم؟' }, { name: 'categoryId', label: 'مرتبط بفئة بلاغات (اختياري)', type: 'select', options: UI.opts('categories') }, { name: 'order', label: 'الترتيب', type: 'number', min: 0 }], rec)}
      <div class="field mt"><label>الأيقونة</label><div class="tiles sm cat-pick">${FORM_ICONS.map((k) => html`<label><input type="radio" name="icon" value="${k}"${(rec.icon || 'paper') === k ? raw(' checked') : ''}><span class="tile">${UI.illu(k)}<b>${ILLU_LABELS[k] || k}</b></span></label>`)}</div></div>
      <div class="field mt"><label for="fmFile">ملف النموذج</label>${rec.file ? html`<div class="form-bar" style="margin-bottom:8px">${UI.icon('file')}<div class="grow"><b>${rec.file.name}</b><div class="t-sub">${fmtBytes(rec.file.size)}</div></div><button type="button" class="btn btn-sm btn-soft" data-prev="${id}">${UI.icon('eye')} معاينة</button></div>` : ''}<input id="fmFile" name="file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,image/*"><small class="hint">PDF أو Word أو صورة، بحد أقصى 3 ميجابايت.${rec.file ? ' اترك الحقل فارغاً للإبقاء على الملف الحالي.' : ''}</small></div>`,
    onMount: (form) => { UI.on(form, 'click', '[data-prev]', async () => { const r = await DB.get('forms', id); if (r && r.file) Pages.previewFile(r.file); }); },
    actions: [{ label: 'إلغاء', kind: 'ghost' }, ...(id ? [{ label: 'حذف', kind: 'danger', icon: 'trash', handler: async () => { if (!(await UI.confirm('حذف هذا النموذج نهائياً؟', { danger: true, ok: 'حذف' }))) return false; await Data.forms.remove(id); UI.toast('حُذف النموذج'); return true; } }] : []), { label: 'حفظ', kind: 'primary', icon: 'check', submit: true, handler: async (form) => {
      const v = UI.formValues(form), fi = form.querySelector('[name="file"]'), f = fi && fi.files && fi.files[0];
      let file = rec.file || null;
      if (f) { if (f.size > 3 * 1024 * 1024) throw new AppError('حجم الملف أكبر من 3 ميجابايت'); file = { name: f.name, type: f.type, size: f.size, at: now(), data: await fileToData(f) }; }
      const out = await Data.forms.save({ ...rec, ...v, id: id || undefined, file });
      UI.toast('حُفظ النموذج'); return out;
    } }]
  });
};
Pages.formsPage = async (ctx) => {
  /* إعدادات التعبئة الفورية في مكتبة النماذج نفسها (كانت في صفحة «تشغيل الخصائص» منفصلة عن النماذج) */
  const ffCan = () => ['formfill.manage', 'forms.manage', 'settings'].some((p) => canUser(Auth.user, p));
  ctx.view.addEventListener('change', async (e) => {
    const el = e.target.closest('[data-ffsw]'); if (!el) return;
    const key = { ffon: 'off', ffsign: 'noSign', ffdl: 'hideDl' }[el.dataset.ffsw], on = el.checked;
    try { await XCFG.save('formfill', 'formFill', { ...(Data.c.formFill || {}), [key]: on ? 0 : 1 }, 'تحديث إعدادات التعبئة الفورية'); UI.toast(on ? 'فُعّل' : 'أُوقف'); } catch (err) { el.checked = !on; UI.error(err); }
    st.ffOpen = true; draw();
  });
  const st = { q: '', cat: '' };
  const draw = async () => {
    const all = await Data.forms.list();
    if (!ctx.alive()) return;
    const qn = normalizeAr(st.q);
    const rows = all.filter((f) => (!f.hidden || canHideForms()) && (!st.cat || f.categoryId === st.cat) && (!qn || normalizeAr(`${f.title} ${f.desc} ${Data.nameOf('categories', f.categoryId, '')}`).includes(qn)));
    const manage = canManageForms(), hider = canHideForms();
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ title: 'النماذج والاستمارات', sub: 'استمارات جاهزة للعرض داخل النظام والتحميل والطباعة', illu: 'paper', actions: html`${manage ? html`<button class="btn btn-primary" data-act="new">${UI.icon('plus')} نموذج جديد</button>` : ''}<button class="btn btn-ghost" data-blankcard>${UI.icon('print')} استمارة بطاقة فارغة</button>` })}
      ${manage || hider ? UI.stateLegend(['off', 'lock'], { off: 'مخفي عن الموظفين', lock: 'التحميل موقوف' }) : ''}
      ${ffCan() ? html`<details class="panel ff-set"${st.ffOpen ? raw(' open') : ''}><summary>${UI.icon('edit')}<b>التعبئة الفورية</b><span class="cc-st ${FF.on() ? 'on' : 'off'}"><i></i>${FF.on() ? 'مفعّلة' : 'موقوفة'}</span><span class="faint small grow">تعبئة المستند داخل النظام وإرفاقه بالبلاغ مباشرة</span></summary><div class="panel-body ff-sws">${[['ffon', FF.on(), 'إتاحة التعبئة الفورية للموظفين'], ['ffsign', FF.signOn(), 'السماح بالتوقيع بخط اليد داخل الاستمارة'], ['ffdl', !FF.hideDl(), 'إبقاء زر «تحميل» بجانب التعبئة الفورية']].map(([k, on, t]) => html`<label class="switch"><input type="checkbox" data-ffsw="${k}"${on ? raw(' checked') : ''}><i></i><span>${t}</span></label>`)}</div></details>` : ''}
      <section class="panel"><div class="toolbar"><div class="search-box">${UI.icon('search')}<input id="fq" type="search" placeholder="ابحث باسم النموذج" value="${st.q}"></div><select id="fcat"><option value="">كل الفئات</option>${UI.opts('categories').map((o) => html`<option value="${o.value}"${st.cat === o.value ? raw(' selected') : ''}>${o.label}</option>`)}</select><span class="faint small">${arCount(rows.length, AR.item).replace('صنف', 'نموذج').replace('أصناف', 'نماذج')}</span></div>
      ${rows.length ? html`<div class="forms-grid">${rows.map((f) => html`<article class="form-card${f.hidden ? ' off x-off' : ''}${(manage || hider) && (f.noDownload || docLocked(f.categoryId)) ? ' x-lock' : ''}" data-fv="${f.id}"><button type="button" class="fc-thumb" data-fview="${f.id}" title="عرض «${f.title}»">${UI.illu(f.icon || 'paper')}<i>${UI.icon('eye')} عرض</i></button><div class="fc-body"><b>${f.title}</b><p class="t-sub fc-sum">${FV.sum(f)}</p><div class="row" style="gap:6px;flex-wrap:wrap">${f.categoryId ? UI.chip('sky', Data.nameOf('categories', f.categoryId), 'tag') : ''}${f.file ? UI.chip('slate', fmtBytes(f.file.size)) : ''}${f.hidden ? UI.chip('red', 'مخفي عن الموظفين', 'eye-off') : ''}${(manage || hider) && (f.noDownload || docLocked(f.categoryId)) ? UI.chip('amber', 'التحميل موقوف', 'lock') : ''}</div></div>
        <div class="fc-actions">${FF.on() && FF.fillable(f.file) && !((f.noDownload || docLocked(f.categoryId)) && !manage) ? html`<button class="btn btn-sm btn-primary" data-ffill="${f.id}">${UI.icon('edit')} تعبئة فورية</button>` : ''}${f.categoryId && eformOn(f.categoryId) && Data.c.categories.get(f.categoryId) && !Data.c.categories.get(f.categoryId).hidden ? html`<a class="btn btn-sm btn-primary" href="#/tickets/new?cat=${f.categoryId}">${UI.icon('edit')} تعبئة إلكترونية</a>` : ''}${f.file ? html`<button class="btn btn-sm btn-primary" data-fview="${f.id}">${UI.icon('eye')} عرض</button>` : ''}${!manage && (f.noDownload || docLocked(f.categoryId)) ? html`<span class="chip tone-slate">${UI.icon('lock')} التحميل موقوف</span>` : html`<button class="btn btn-sm btn-soft" data-dl="${f.id}">${UI.icon('download')} تحميل</button>`}${hider ? html`<button class="btn btn-sm btn-ghost" data-hideform="${f.id}" title="${f.hidden ? 'إظهار المستند للموظفين' : 'إخفاء المستند عن الموظفين'}">${UI.icon(f.hidden ? 'eye' : 'eye-off')} ${f.hidden ? 'إظهار' : 'إخفاء'}</button>` : ''}${manage ? html`<button class="btn btn-sm btn-ghost" data-lockdl="${f.id}" title="${f.noDownload ? 'السماح بالتحميل للموظفين' : 'إيقاف التحميل للموظفين'}">${UI.icon(f.noDownload ? 'lock' : 'download')} ${f.noDownload ? 'موقوف' : 'متاح'}</button><button class="btn btn-sm btn-ghost" data-edit="${f.id}">${UI.icon('edit')}</button>` : ''}</div></article>`)}</div>`
        : html`<div class="panel-body">${UI.empty({ illu: 'paper', title: 'لا توجد نماذج بعد', text: manage ? 'أضف الاستمارات التي يحتاجها الموظفون ليحمّلوها من هنا.' : 'ستظهر هنا الاستمارات فور إضافتها من قسم تقنية المعلومات.', action: manage ? html`<button class="btn btn-primary" data-act="new">${UI.icon('plus')} نموذج جديد</button>` : '' })}</div>`}</section>`);
    UI.hydrate(ctx.view); FV.hydrate(ctx.view);
    $('#fq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); draw(); }, 250));
    $('#fcat', ctx.view).onchange = (e) => { st.cat = e.target.value; draw(); };
  };
  UI.on(ctx.view, 'click', '[data-view]', async (e, el) => { const f = await DB.get('forms', el.dataset.view); if (f && f.file) Pages.previewFile(f.file); });
  UI.on(ctx.view, 'click', '[data-lockdl]', async (e, el) => { const f = await DB.get('forms', el.dataset.lockdl); if (!f) return; f.noDownload = f.noDownload ? 0 : 1; f.updatedAt = now(); await DB.put('forms', f); Bus.emit('forms', {}); UI.toast(f.noDownload ? `أُوقف تحميل «${f.title}» للموظفين` : `أصبح «${f.title}» متاحاً للتحميل`); draw(); });
  UI.on(ctx.view, 'click', '[data-hideform]', async (e, el) => { if (!canHideForms()) return; const f = await DB.get('forms', el.dataset.hideform); if (!f) return;
    /* نموذج مدمج لم يُسجَّل على الخادم بعد (يسجّله من يملك إدارة النماذج عند فتحه هذه الصفحة): إخفاؤه وحده يُرفض */
    if (Sync.on && !f._rev && !canManageForms()) { UI.toast('هذا النموذج لم يُسجَّل على الخادم بعد. يفتح المشرف أو مسؤول النماذج هذه الصفحة مرة فيُسجَّل، ثم يمكن إخفاؤه', 'warn', 8000); return; }
    f.hidden = f.hidden ? 0 : 1; f.updatedAt = now(); await DB.put('forms', f); await Data.log('update', 'settings', f.id, `${f.hidden ? 'إخفاء' : 'إظهار'} نموذج: ${f.title}`); Bus.emit('forms', {}); UI.toast(f.hidden ? `أُخفي «${f.title}» عن الموظفين` : `أصبح «${f.title}» ظاهراً للموظفين`); draw(); });
  UI.on(ctx.view, 'click', '[data-dl]', async (e, el) => { const f = await DB.get('forms', el.dataset.dl); if (f && (f.noDownload || docLocked(f.categoryId)) && !canManageForms()) { UI.toast('التحميل موقوف لهذا النموذج', 'warn'); return; } if (f && f.file) { downloadBlob(dataToBlob(f.file.data), f.file.name); UI.toast('تم التحميل'); } });
  UI.on(ctx.view, 'click', '[data-edit]', async (e, el) => { if (await Pages.formModal(el.dataset.edit)) draw(); });
  UI.on(ctx.view, 'click', '[data-act="new"]', async () => { if (await Pages.formModal()) draw(); });
  ctx.onCleanup(Bus.on('forms', debounce(() => { if (ctx.alive()) draw(); }, 400)));
  await draw();
};

/* أيقونات الماركات داخل الفئات */
Data.brands = {
  key: (catId, brand) => `${catId}|${String(brand || '').trim()}`,
  async map() { const rows = await DB.getAll('brandIcons'); return new Map(rows.map((r) => [r.id, r.illustration])); },
  async set(catId, brand, illustration) {
    if (!canUser(Auth.user, 'inventory.manage')) throw new AppError('هذه العملية لمن يملك إدارة المخزون');
    const id = Data.brands.key(catId, brand);
    await DB.put('brandIcons', { id, categoryId: catId, brand, illustration, updatedAt: now() });
    Bus.emit('inventory', {});
  }
};
Pages.brandIconModal = (catId, brand, current = '') => UI.modal({
  title: `أيقونة ${brand}`, icon: 'box', size: 'lg',
  body: html`<p class="muted" style="margin-bottom:10px">اختر رسمة تميّز أجهزة ${brand} داخل فئة ${Data.nameOf('itemCategories', catId, '')}.</p>
    <div class="tiles sm cat-pick">${Iso.names.map((k) => html`<label><input type="radio" name="illustration" value="${k}"${current === k ? raw(' checked') : ''}><span class="tile">${UI.illu(k)}<b>${ILLU_LABELS[k] || k}</b></span></label>`)}</div>`,
  actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ الأيقونة', kind: 'primary', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); await Data.brands.set(catId, brand, v.illustration); UI.toast('حُفظت أيقونة الماركة'); return true; } }]
});

/* ── سجل أعمال القسم: تسجيل الأعمال اليومية للفنيين والإداريين ── */
const WORK_TYPES = [
  { k: 'maintenance', l: 'صيانة جهاز', ic: 'tools', tone: 'sky' },
  { k: 'visit', l: 'زيارة إدارة', ic: 'building', tone: 'violet' },
  { k: 'install', l: 'تركيب وتجهيز', ic: 'download', tone: 'teal' },
  { k: 'network', l: 'أعمال شبكة', ic: 'network', tone: 'brass' },
  { k: 'workshop', l: 'ورشة عمل', ic: 'users', tone: 'amber' },
  { k: 'lecture', l: 'محاضرة أو تدريب', ic: 'book', tone: 'green' },
  { k: 'meeting', l: 'اجتماع', ic: 'users', tone: 'slate' },
  { k: 'remote', l: 'دعم عن بُعد', ic: 'display', tone: 'sky' },
  { k: 'inventory', l: 'أعمال المخزن', ic: 'warehouse', tone: 'teal' },
  { k: 'admin', l: 'أعمال إدارية', ic: 'file', tone: 'violet' },
  { k: 'other', l: 'أعمال أخرى', ic: 'box', tone: 'slate' }
];
const workType = (k) => WORK_TYPES.find((t) => t.k === k) || WORK_TYPES[WORK_TYPES.length - 1];
const COMMON_WORKS = [
  ['صيانة جهاز حاسب', 'maintenance'], ['تغيير حبر طابعة', 'maintenance'], ['إصلاح طابعة وانحشار ورق', 'maintenance'],
  ['تنصيب نظام تشغيل وبرامج', 'install'], ['تجهيز جهاز جديد وتسليمه', 'install'], ['ربط طابعة بالشبكة', 'network'],
  ['تمديد نقطة شبكة', 'network'], ['متابعة انقطاع الشبكة', 'network'], ['زيارة دورية لإدارة', 'visit'],
  ['تجهيز قاعة لمحاضرة', 'workshop'], ['تشغيل جهاز العرض ومتابعة الفعالية', 'workshop'], ['تدريب موظفين على نظام', 'lecture'],
  ['دعم عن بُعد لحل مشكلة برنامج', 'remote'], ['جرد وترتيب المخزن', 'inventory'], ['إعداد حسابات بريد ومستخدمين', 'admin'],
  ['نسخ احتياطي ومتابعة الخوادم', 'admin']
];
const canSeeAllWork = () => canUser(Auth.user, 'worklog.all') || canUser(Auth.user, 'reports') || canUser(Auth.user, 'users.manage');
Data.work = {
  list: () => DB.getAll('worklog'),
  async save(rec) {
    const t = now();
    const out = {
      id: rec.id || uid('wl'), userId: rec.userId || Auth.user.id, at: rec.at || startOfDay(),
      type: rec.type || 'other', title: String(rec.title || '').trim(), details: String(rec.details || '').trim(),
      departmentId: rec.departmentId || '', locationId: rec.locationId || '', place: String(rec.place || '').trim(),
      hours: Number(rec.hours) || 0, people: Number(rec.people) || 0, ticketId: rec.ticketId || '',
      withWhom: String(rec.withWhom || '').trim(), result: rec.result || 'done',
      createdAt: rec.createdAt || t, updatedAt: t, _rev: rec._rev
    };
    if (!out.title) throw new AppError('اكتب وصف العمل');
    await DB.put('worklog', out);
    Bus.emit('worklog', {});
    return out;
  },
  async remove(id) {
    const rec = await DB.get('worklog', id); if (!rec) return;
    if (rec.userId !== Auth.user.id && !canUser(Auth.user, 'users.manage')) throw new AppError('لا يمكنك حذف عمل غيرك');
    await DB.del('worklog', id); Bus.emit('worklog', {});
  }
};
Pages.workModal = async (id = '', preset = {}) => {
  const customTypes = await Pages.customWorkTypes();
  const rec = id ? await DB.get('worklog', id) : { at: startOfDay(), type: preset.type || 'maintenance', result: 'done', ...preset };
  return UI.modal({
    title: id ? 'تعديل عمل' : 'تسجيل عمل', icon: 'clipboard', size: 'lg',
    body: html`<div class="field wide"><label>نوع العمل</label><div class="choice-pick">${WORK_TYPES.map((t) => html`<label><input type="radio" name="type" value="${t.k}"${(rec.type || 'maintenance') === t.k ? raw(' checked') : ''}><span>${UI.icon(t.ic)}${t.l}</span></label>`)}${customTypes.map((t) => html`<label><input type="radio" name="type" value="${t.text}"${rec.type === t.text ? raw(' checked') : ''}><span>${UI.icon('star')}${t.text}</span></label>`)}<button type="button" class="chip-add" data-addtype>${UI.icon('plus')} نوع آخر</button></div></div>
      <div class="field wide"><label class="row" style="justify-content:space-between"><span>وصف العمل<em>*</em></span><span class="row" style="gap:6px"><button type="button" class="btn btn-ghost btn-sm" data-replies="work" data-target="wlTitle">${UI.icon('book')} أعمال محفوظة</button><button type="button" class="btn btn-ghost btn-sm" data-savereply="wlTitle" data-kind="work">${UI.icon('plus')} حفظ العمل</button></span></label><input id="wlTitle" name="title" value="${rec.title || ''}" placeholder="مثال: صيانة جهاز حاسب في مكتب 214" autocomplete="off"><div class="chip-row mt">${COMMON_WORKS.slice(0, 8).map(([w, k]) => html`<button type="button" class="qchip" data-work="${w}" data-wtype="${k}">${w}</button>`)}</div></div>
      <div class="form-grid mt">
        ${UI.field({ name: 'at', label: 'تاريخ العمل', type: 'date' }, dateInput(rec.at || now()))}
        ${UI.combo({ name: 'departmentId', label: 'الإدارة أو الجهة المستفيدة', value: rec.departmentId ? Data.nameOf('departments', rec.departmentId, '') : '', options: Data.list('departments').map((d) => ({ value: d.name, label: d.name })), placeholder: 'اختر من القائمة أو اكتب الجهة' })}
        ${UI.field({ name: 'place', label: 'المكتب أو القاعة' }, rec.place)}
        ${UI.field({ name: 'hours', label: 'عدد الساعات', type: 'number', min: 0, step: '0.5' }, rec.hours || '')}
        ${UI.field({ name: 'people', label: 'عدد المستفيدين', type: 'number', min: 0 }, rec.people || '')}
        ${UI.field({ name: 'withWhom', label: 'بمشاركة (زملاء)' }, rec.withWhom)}
        ${UI.field({ name: 'result', label: 'النتيجة', type: 'select', placeholder: false, options: [{ value: 'done', label: 'مكتمل' }, { value: 'partial', label: 'جزئي — يحتاج متابعة' }, { value: 'followup', label: 'يحتاج زيارة أخرى' }] }, rec.result || 'done')}
        ${UI.field({ name: 'details', label: 'تفاصيل إضافية', type: 'textarea', rows: 3, wide: true }, rec.details)}
      </div>`,
    onMount: (form) => {
      UI.on(form, 'click', '[data-work]', (e, el) => {
        form.querySelector('#wlTitle').value = el.dataset.work;
        const r = form.querySelector(`input[name="type"][value="${el.dataset.wtype}"]`); if (r) r.checked = true;
      });
    },
    actions: [{ label: 'إلغاء', kind: 'ghost' }, ...(id ? [{ label: 'حذف', kind: 'danger', icon: 'trash', handler: async () => { if (!(await UI.confirm('حذف هذا السجل؟', { danger: true, ok: 'حذف' }))) return false; await Data.work.remove(id); UI.toast('حُذف السجل'); return true; } }] : []), { label: 'حفظ العمل', kind: 'primary', icon: 'check', submit: true, handler: async (form) => {
      const v = UI.formValues(form);
      const out = await Data.work.save({ ...rec, ...v, id: id || undefined, at: v.at ? startOfDay(fromDateInput(v.at, true)) : startOfDay() });
      UI.toast('سُجّل العمل'); UI.sound('success'); return out;
    } }]
  });
};
Pages.worklog = async (ctx) => {
  const all = canSeeAllWork();
  const st = { scope: all ? 'team' : 'me', q: '', type: '', user: '', from: dateInput(startOfDay() - 29 * DAY), to: dateInput(now()) };
  const draw = async () => {
    const rows0 = (await Data.work.list()).sort((a, b) => b.at - a.at || b.createdAt - a.createdAt);
    if (!ctx.alive()) return;
    const f = startOfDay(fromDateInput(st.from, true)), t = startOfDay(fromDateInput(st.to, true)) + DAY - 1;
    const qn = normalizeAr(st.q);
    const rows = rows0.filter((r) => r.at >= f && r.at <= t
      && (st.scope === 'team' ? true : r.userId === Auth.user.id)
      && (!st.type || r.type === st.type) && (!st.user || r.userId === st.user)
      && (!qn || normalizeAr(`${r.title} ${r.details} ${Data.userName(r.userId)} ${(r.departmentText || Data.nameOf('departments', r.departmentId, ''))}`).includes(qn)));
    const hours = rows.reduce((s, r) => s + (Number(r.hours) || 0), 0);
    const people = rows.reduce((s, r) => s + (Number(r.people) || 0), 0);
    const byType = new Map(), byUser = new Map(), byDep = new Map();
    rows.forEach((r) => { byType.set(r.type, (byType.get(r.type) || 0) + 1); byUser.set(r.userId, (byUser.get(r.userId) || 0) + 1); if (r.departmentId) byDep.set(r.departmentId, (byDep.get(r.departmentId) || 0) + 1); });
    const staff = Data.list('users').filter((u) => u.active && canUser(u, 'tickets.work'));
    ctx.view.innerHTML = String(html`
      ${UI.pageHead({ title: 'أعمال القسم', sub: 'سجل يومي لأعمال الفنيين والإداريين: صيانة وزيارات وورش ومحاضرات', illu: 'clipboard', actions: html`<button class="btn btn-primary" data-act="new">${UI.icon('plus')} تسجيل عمل</button><button class="btn btn-ghost" data-act="xls">${UI.icon('download')} تصدير</button><button class="btn btn-ghost" data-act="print">${UI.icon('print')} طباعة</button>` })}
      <div class="kpis">
        ${UI.kpi({ label: 'الأعمال المسجّلة', icon: 'clipboard', tone: 'violet', value: rows.length })}
        ${UI.kpi({ label: 'ساعات العمل', icon: 'clock', tone: 'sky', value: Math.round(hours), foot: html`<span class="delta">${fmtNum(Math.round(hours * 10) / 10)} ساعة بالضبط</span>` })}
        ${UI.kpi({ label: 'المستفيدون', icon: 'users', tone: 'teal', value: people })}
        ${UI.kpi({ label: 'إدارات مخدومة', icon: 'building', tone: 'brass', value: byDep.size })}
      </div>
      <section class="panel mt"><div class="toolbar">
        ${all ? html`<div class="seg sm">${[['team', 'أعمال القسم'], ['me', 'أعمالي']].map(([k, l]) => html`<label><input type="radio" name="wscope" value="${k}"${st.scope === k ? raw(' checked') : ''}><span>${l}</span></label>`)}</div>` : ''}
        <div class="search-box">${UI.icon('search')}<input id="wq" type="search" placeholder="ابحث في الأعمال" value="${st.q}"></div>
        <select id="wtype"><option value="">كل الأنواع</option>${WORK_TYPES.map((x) => html`<option value="${x.k}"${st.type === x.k ? raw(' selected') : ''}>${x.l}</option>`)}</select>
        ${all ? html`<select id="wuser"><option value="">كل الموظفين</option>${staff.map((u) => html`<option value="${u.id}"${st.user === u.id ? raw(' selected') : ''}>${u.name}</option>`)}</select>` : ''}
        <div class="range-bar"><span class="faint small">من</span><input type="date" id="wFrom" dir="ltr" lang="en-GB" value="${st.from}"><span class="faint small">إلى</span><input type="date" id="wTo" dir="ltr" lang="en-GB" value="${st.to}"></div>
      </div>
      ${rows.length ? html`<div class="table-wrap"><table class="table"><thead><tr><th>التاريخ</th><th>العمل</th><th>النوع</th><th>الإدارة</th><th>المنفّذ</th><th>ساعات</th><th></th></tr></thead><tbody class="stagger">${rows.slice(0, 250).map((r) => { const ty = workType(r.type); return html`<tr><td class="faint nowrap">${fmtDate(r.at)}</td><td><div><b>${r.title}</b>${r.details ? html`<div class="t-sub ellipsis">${r.details}</div>` : ''}</div></td><td>${UI.chip(ty.tone, ty.l, ty.ic)}</td><td class="small">${(r.departmentText || Data.nameOf('departments', r.departmentId, '—'))}${r.place ? html`<div class="t-sub">${r.place}</div>` : ''}</td><td class="small">${Data.userName(r.userId)}</td><td>${r.hours ? fmtNum(r.hours) : '—'}</td><td class="nowrap">${r.userId === Auth.user.id || canUser(Auth.user, 'users.manage') ? html`<button class="btn btn-ghost btn-sm" data-edit="${r.id}">${UI.icon('edit')}</button>` : ''}</td></tr>`; })}</tbody></table></div>`
        : html`<div class="panel-body">${UI.empty({ illu: 'clipboard', title: 'لا توجد أعمال في هذه الفترة', text: 'سجّل أعمالك اليومية لتظهر هنا وتُحتسب في تقارير القسم.', action: html`<button class="btn btn-primary" data-act="new">${UI.icon('plus')} تسجيل عمل</button>` })}</div>`}</section>
      ${rows.length ? html`<div class="grid g-2 mt">
        ${UI.panel({ title: 'حسب نوع العمل', icon: 'chart', body: UI.chart.hbars([...byType].sort((a, b) => b[1] - a[1]).map(([k, v], i) => ({ label: workType(k).l, value: v, tone: workType(k).tone || TONES[i % TONES.length] }))) })}
        ${UI.panel({ title: 'حسب المنفّذ', icon: 'users', body: UI.chart.hbars([...byUser].sort((a, b) => b[1] - a[1]).slice(0, 10).map(([k, v], i) => ({ label: Data.userName(k), value: v, tone: TONES[i % TONES.length] }))) })}
      </div>` : ''}`);
    UI.hydrate(ctx.view); ctx.rows = rows; ctx.meta = { from: f, to: t };
    $('#wq', ctx.view).addEventListener('input', debounce((e) => { st.q = e.target.value.trim(); draw(); }, 250));
    const bind = (id, key) => { const el = $('#' + id, ctx.view); if (el) el.onchange = () => { st[key] = el.value; draw(); }; };
    bind('wtype', 'type'); bind('wuser', 'user'); bind('wFrom', 'from'); bind('wTo', 'to');
  };
  UI.on(ctx.view, 'change', 'input[name="wscope"]', (e, el) => { st.scope = el.value; draw(); });
  UI.on(ctx.view, 'click', '[data-act="new"]', async () => { if (await Pages.workModal()) draw(); });
  UI.on(ctx.view, 'click', '[data-edit]', async (e, el) => { if (await Pages.workModal(el.dataset.edit)) draw(); });
  UI.on(ctx.view, 'click', '[data-act="xls"]', () => {
    const rows = ctx.rows || [];
    downloadBlob(XL.write([
      { name: 'الأعمال', widths: [14, 40, 18, 22, 20, 10, 12, 30], rows: [['التاريخ', 'العمل', 'النوع', 'الإدارة', 'المنفّذ', 'ساعات', 'المستفيدون', 'تفاصيل'], ...rows.map((r) => [fmtDate(r.at), r.title, workType(r.type).l, (r.departmentText || Data.nameOf('departments', r.departmentId, '')), Data.userName(r.userId), String(r.hours || ''), String(r.people || ''), r.details || ''])] },
      { name: 'حسب النوع', widths: [24, 12], rows: [['النوع', 'العدد'], ...[...rows.reduce((m, r) => m.set(r.type, (m.get(r.type) || 0) + 1), new Map())].map(([k, v]) => [workType(k).l, String(v)])] },
      { name: 'حسب المنفّذ', widths: [26, 12, 12], rows: [['المنفّذ', 'عدد الأعمال', 'الساعات'], ...[...rows.reduce((m, r) => { const x = m.get(r.userId) || { n: 0, h: 0 }; x.n++; x.h += Number(r.hours) || 0; return m.set(r.userId, x); }, new Map())].map(([k, v]) => [Data.userName(k), String(v.n), String(Math.round(v.h * 10) / 10)])] }
    ]), `أعمال-القسم-${st.from}_${st.to}.xlsx`);
    UI.toast('تم التصدير');
  });
  UI.on(ctx.view, 'click', '[data-act="print"]', () => {
    const rows = ctx.rows || [], m = ctx.meta || {};
    UI.print(html`<h2 style="text-align:center">تقرير أعمال القسم</h2><p style="text-align:center">الفترة من ${fmtDate(m.from)} إلى ${fmtDate(m.to)} — ${arCount(rows.length, AR.item).replace('صنف', 'عمل').replace('أصناف', 'أعمال')}</p>
      <table><tr><th>م</th><th>التاريخ</th><th>العمل</th><th>النوع</th><th>الإدارة</th><th>المنفّذ</th><th>ساعات</th></tr>
      ${rows.map((r, i) => html`<tr><td>${i + 1}</td><td>${fmtDate(r.at)}</td><td>${r.title}</td><td>${workType(r.type).l}</td><td>${(r.departmentText || Data.nameOf('departments', r.departmentId, ''))}</td><td>${Data.userName(r.userId)}</td><td>${r.hours || ''}</td></tr>`)}</table>
      ${UI.signBlock([{ title: 'مُعدّ التقرير', userId: Auth.user.id }])}`, 'تقرير أعمال القسم');
  });
  ctx.onCleanup(Bus.on('worklog', debounce(() => { if (ctx.alive()) draw(); }, 400)));
  await draw();
};

/* ── متابعة الأعمال: مستكشف مجلدات بلا حدود (مثل قرص التخزين) مع أعمال مرتبطة بالإدارات ── */
const WORK_STATUS = {
  open: { label: 'جديد', tone: 'sky', icon: 'plus' },
  progress: { label: 'قيد العمل', tone: 'amber', icon: 'play' },
  waiting: { label: 'بانتظار طرف آخر', tone: 'violet', icon: 'clock' },
  done: { label: 'منتهي', tone: 'green', icon: 'check' },
  canceled: { label: 'ملغى', tone: 'slate', icon: 'x' }
};
const WORK_PRIO = { low: 'عادية', medium: 'متوسطة', high: 'عالية' };
const FOLDER_ICONS = Iso.names;
const canManageWorks = () => canUser(Auth.user, 'works') || canUser(Auth.user, 'users.manage');
const sortByOrder = (a, b) => (a.order || 0) - (b.order || 0) || String(a.name || a.title).localeCompare(String(b.name || b.title), 'ar');
/* فهرس سريع لشجرة المجلدات: الأبناء، الأعمال، والمجاميع لكل مجلد وما تحته */
const worksIndex = (folders, items) => {
  const byId = new Map(folders.map((f) => [f.id, f])), kids = new Map(), direct = new Map();
  folders.forEach((f) => { const p = byId.has(f.parentId) ? f.parentId : ''; if (!kids.has(p)) kids.set(p, []); kids.get(p).push(f); });
  kids.forEach((a) => a.sort(sortByOrder));
  items.forEach((i) => { const k = byId.has(i.folderId) ? i.folderId : ''; if (!direct.has(k)) direct.set(k, []); direct.get(k).push(i); });
  const memo = new Map();
  const total = (id) => { if (memo.has(id)) return memo.get(id); const t = { items: (direct.get(id) || []).length, folders: (kids.get(id) || []).length }; (kids.get(id) || []).forEach((c) => { const x = total(c.id); t.items += x.items; t.folders += x.folders; }); memo.set(id, t); return t; };
  const descend = (id) => { const out = [id]; (kids.get(id) || []).forEach((c) => out.push(...descend(c.id))); return out; };
  const path = (id) => { const out = []; let cur = byId.get(id), guard = 0; while (cur && guard++ < 200) { out.unshift(cur); cur = byId.get(cur.parentId); } return out; };
  const pathName = (id) => path(id).map((f) => f.name).join(' / ');
  const flat = (pid = '', depth = 0, out = []) => { (kids.get(pid) || []).forEach((f) => { out.push({ f, depth }); flat(f.id, depth + 1, out); }); return out; };
  return { byId, kids: (id) => kids.get(id) || [], direct: (id) => direct.get(id) || [], total, descend, path, pathName, flat };
};
Data.works = {
  folders: () => DB.getAll('workFolders'),
  items: () => DB.getAll('workItems'),
  async ensure() {
    if (!(await DB.count('workFolders'))) {
      const t = now();
      await DB.bulkPut('workFolders', [
        { id: 'wf_internal', parentId: '', name: 'الأعمال الداخلية', icon: 'building', tone: 'violet', order: 1, createdAt: t, updatedAt: t },
        { id: 'wf_external', parentId: '', name: 'الأعمال الخارجية', icon: 'network', tone: 'sky', order: 2, createdAt: t, updatedAt: t },
        { id: 'wf_projects', parentId: '', name: 'المشاريع والمبادرات', icon: 'archive', tone: 'brass', order: 3, createdAt: t, updatedAt: t }
      ]);
    }
    await seedWorkSubfolders();
  },
  async saveFolder(rec) {
    if (!canManageWorks()) throw new AppError('لا تملك صلاحية إدارة الأعمال');
    const t = now(), out = { id: rec.id || uid('wf'), parentId: rec.parentId || '', name: String(rec.name || '').trim(), icon: rec.icon || 'folder', tone: rec.tone || 'sky', note: String(rec.note || '').trim(), order: Number(rec.order) || 0, createdBy: rec.createdBy || Auth.user.id, createdAt: rec.createdAt || t, updatedAt: t, _rev: rec._rev };
    if (!out.name) throw new AppError('اكتب اسم المجلد');
    if (out.parentId) { const idx = worksIndex(await this.folders(), []); if (rec.id && idx.descend(rec.id).includes(out.parentId)) throw new AppError('لا يمكن نقل المجلد إلى داخل نفسه أو أحد مجلداته الفرعية'); }
    const siblings = (await this.folders()).filter((f) => (f.parentId || '') === out.parentId && f.id !== out.id);
    if (siblings.some((f) => normalizeAr(f.name) === normalizeAr(out.name))) throw new AppError('يوجد مجلد بالاسم نفسه في هذا المكان');
    if (!rec.id && !rec.order) out.order = siblings.length + 1;
    await DB.put('workFolders', out); Bus.emit('works', {}); return out;
  },
  async moveFolder(id, parentId) { const f = await DB.get('workFolders', id); if (!f) return; if ((f.parentId || '') === (parentId || '')) return f; return this.saveFolder({ ...f, parentId: parentId || '' }); },
  async moveItem(id, folderId) { const i = await DB.get('workItems', id); if (!i || i.folderId === folderId) return i; return this.saveItem({ ...i, folderId }); },
  /* حذف المجلد: فارغاً مباشرة، أو بكل محتواه عند التأكيد */
  async removeFolder(id, recursive = false) {
    if (!canManageWorks()) throw new AppError('لا تملك الصلاحية');
    const [folders, items] = await Promise.all([this.folders(), this.items()]), idx = worksIndex(folders, items), tot = idx.total(id);
    if ((tot.items || tot.folders) && !recursive) throw new AppError('المجلد يحتوي مجلدات أو أعمالاً');
    const ids = new Set(idx.descend(id));
    for (const i of items.filter((x) => ids.has(x.folderId))) await DB.del('workItems', i.id);
    for (const fid of [...ids].reverse()) await DB.del('workFolders', fid);
    await Data.log('delete', 'works', id, `حذف مجلد أعمال: ${(idx.byId.get(id) || {}).name || ''}`);
    Bus.emit('works', {});
  },
  async saveItem(rec) {
    if (!canManageWorks()) throw new AppError('لا تملك صلاحية إدارة الأعمال');
    const t = now(), deps = [...new Set([].concat(rec.departmentIds || []).filter((d) => Data.c.departments.has(d)))], out = {
      id: rec.id || uid('wi'), folderId: rec.folderId || '', title: String(rec.title || '').trim(), desc: String(rec.desc || '').trim(),
      status: WORK_STATUS[rec.status] ? rec.status : 'open', priority: WORK_PRIO[rec.priority] ? rec.priority : 'medium', dueAt: rec.dueAt || 0, ownerId: rec.ownerId || Auth.user.id,
      departmentIds: deps, partner: String(rec.partner || '').trim(), notes: String(rec.notes || '').trim(), files: rec.files || [],
      doneAt: rec.status === 'done' ? rec.doneAt || t : 0, createdBy: rec.createdBy || Auth.user.id, createdAt: rec.createdAt || t, updatedAt: t, _rev: rec._rev
    };
    if (!out.title) throw new AppError('اكتب عنوان العمل');
    if (!out.folderId) throw new AppError('اختر المجلد');
    await DB.put('workItems', out);
    if (out.ownerId && out.ownerId !== Auth.user.id && (!rec.id || rec.ownerId !== out.ownerId)) await Data.notify([out.ownerId], { title: `أُسند إليك عمل: ${out.title}`, body: WORK_STATUS[out.status].label, link: `/works?f=${out.folderId}`, kind: 'work' });
    Bus.emit('works', {}); return out;
  },
  async removeItem(id) { if (!canManageWorks()) throw new AppError('لا تملك الصلاحية'); await DB.del('workItems', id); Bus.emit('works', {}); }
};
const folderOptions = (idx, exclude = null) => { const bad = exclude ? new Set(idx.descend(exclude)) : new Set(); return idx.flat().filter(({ f }) => !bad.has(f.id)).map(({ f, depth }) => ({ value: f.id, label: `${'   '.repeat(depth)}${depth ? '↳ ' : ''}${f.name}` })); };
