  const fileRow = (f, i) => html`<div class="list-row"><span class="n-ic tone-sky">${UI.icon('file')}</span><div class="grow ellipsis"><b>${f.name}</b><div class="t-sub">${fmtBytes(f.size)}</div></div><button type="button" class="btn btn-ghost btn-sm" data-vf="${i}">${UI.icon('eye')}</button><button type="button" class="icon-btn" data-rf="${i}" aria-label="حذف">${UI.icon('trash')}</button></div>`;
