    const walk = (pid, depth, parent) => all.filter((u) => u.departmentId === depId && (u.parentId || '') === pid).sort(sortByOrder).forEach((u) => { const r = row(u, depth, parent); rows.push(r); walk(u.id, depth + 1, r); });
