/* نوع الفرع من أول كلمة في اسمه، وإلا حسب مستواه */
const ORG_TYPE_WORDS = { 'قسم': 'section', 'شعبه': 'branch', 'وحده': 'unit', 'مكتب': 'office' };
const orgTypeWord = (name) => ORG_TYPE_WORDS[normalizeAr(name).split(' ')[0]] || '';
