  UI.on(el, 'click', '[data-ren]', async (e, el) => { const x = ImgLib.custom.find((i) => i.id === el.dataset.ren); if (!x) return; const r = await UI.modal({ title: 'إعادة تسمية الصورة', icon: 'edit', body: UI.fields([{ name: 'name', label: 'الاسم', required: true, wide: true }], { name: x.name }), actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ', kind: 'primary', submit: true, handler: async (f) => { await ImgLib.rename(x.id, UI.formValues(f).name); return true; } }] }); if (r) draw(); });
