const tableCols = (f) => ((f.o && f.o.length ? f.o : ['الرقم العسكري', 'الرتبة', 'الاسم'])).map((line) => { const [l, ch] = String(line).split('='); return { l: l.trim(), o: ch ? ch.split('/').map((x) => x.trim()).filter(Boolean) : /الرتبة/.test(l) ? Data.list('ranks').map((r) => r.name) : null }; });
const tableRowHTML = (f, cols, r = []) => `<tr>${cols.map((c, i) => `<td>${c.o ? `<select data-cfcell aria-label="${esc(c.l)}"><option value=""></option>${c.o.map((o) => `<option${r[i] === o ? ' selected' : ''}>${esc(o)}</option>`).join('')}</select>` : `<input data-cfcell aria-label="${esc(c.l)}" value="${esc(r[i] || '')}"${/الرقم|الهاتف/.test(c.l) ? ' dir="ltr"' : ''}>`}</td>`).join('')}<td><button type="button" class="icon-btn" data-cftdel title="حذف الصف">${UI.icon('trash')}</button></td></tr>`;
