/* ── حالة الخدمة لمدة محددة ثم العودة التلقائية، وقوالب التعاميم ── */
const DUR_UNITS = { m: { label: 'دقيقة', ms: MIN }, h: { label: 'ساعة', ms: 60 * MIN }, d: { label: 'يوم', ms: DAY } };
