  const quick = [[30, 'm', '30 دقيقة'], [1, 'h', 'ساعة'], [2, 'h', 'ساعتان'], [4, 'h', '4 ساعات'], [1, 'd', 'يوم'], [3, 'd', '3 أيام']];
