      const upd = () => { const n = Number(dur.value); hint.textContent = n > 0 ? `تعود للعمل تلقائياً: ${fmtDateTime(now() + n * DUR_UNITS[unit.value].ms)}` : 'بدون مدة: تبقى الحالة حتى تغييرها يدوياً'; };
