Pages.maintTimeline = (rows) => html`<div class="mt-list">${rows.map((r, i) => { const S = MAINT_STATUS[r.status] || MAINT_STATUS.open, end = r.returnedAt || r.closedAt || 0; return html`<div class="mt-rec tone-${S.tone}">
  <div class="mt-rec-head"><span class="mt-no">${fmtNum(rows.length - i)}</span><b>${r.reason || 'صيانة'}</b>${UI.chip(S.tone, S.label, S.icon)}<span class="faint small">${fmtDate(r.openedAt)}${end ? ` ← ${fmtDate(end)}` : ''} · ${end ? `استغرقت ${fmtDuration(end - r.openedAt)}` : `منذ ${fmtDuration(now() - r.openedAt)}`}</span></div>
  <dl class="kv mt-kv">${r.serial ? html`<dt>الوحدة</dt><dd class="ltr" style="text-align:start">${r.serial}${r.tag && r.tag !== r.serial ? ` · ${r.tag}` : ''}</dd>` : ''}${r.symptom ? html`<dt>الأعراض</dt><dd>${r.symptom}</dd>` : ''}${r.keep ? html`<dt>كان في</dt><dd>${Data.maint.placeText(r)}</dd>` : r.fromDepartmentId ? html`<dt>أُرسل من</dt><dd>${Data.nameOf('departments', r.fromDepartmentId)}</dd>` : ''}<dt>${r.keep ? 'استلمه' : 'أرسله'}</dt><dd>${Data.userName(r.openedBy)} — ${fmtDateTime(r.openedAt)}</dd>${r.workDone ? html`<dt>ما تم</dt><dd>${r.workDone}</dd>` : ''}${r.parts ? html`<dt>القطع المستبدلة</dt><dd>${r.parts}</dd>` : ''}${r.additions ? html`<dt>الإضافات</dt><dd>${r.additions}</dd>` : ''}${r.changes ? html`<dt>التعديلات</dt><dd>${r.changes}</dd>` : ''}${r.notes ? html`<dt>ملاحظات</dt><dd>${r.notes}</dd>` : ''}${(r.log || []).length ? html`<dt>المتابعة</dt><dd>${r.log.map((x) => html`<div class="small">${fmtDate(x.at)} — ${Data.userName(x.by)}: ${x.text}</div>`)}</dd>` : ''}${r.closedAt ? html`<dt>أنهاها</dt><dd>${Data.userName(r.closedBy)} — ${fmtDateTime(r.closedAt)}</dd>` : ''}${r.receiverName ? html`<dt>سُلّم إلى</dt><dd>${r.receiverName}${r.receivedConfirm ? ' (أكّد الاستلام)' : r.status === 'sent' ? ' (بانتظار تأكيده)' : ''}</dd>` : ''}${r.keep ? html`<dd style="grid-column:1/-1"><a href="#/maintenance/${r.id}" data-closemodal>فتح أمر الصيانة</a></dd>` : ''}${r.retireReason ? html`<dt>سبب الإخراج من الخدمة</dt><dd>${r.retireReason}</dd>` : ''}${r.returnedAt ? html`<dt>أُرجع إلى</dt><dd>${Data.nameOf('departments', r.toDepartmentId, 'المخزن')} — ${fmtDateTime(r.returnedAt)}</dd>` : ''}${r.ticketId ? html`<dt>البلاغ</dt><dd><a href="#/tickets/${r.ticketId}" data-closemodal>فتح البلاغ المرتبط</a></dd>` : ''}</dl></div>`; })}</div>`;
Pages.maintSummary = (rows) => { const days = rows.reduce((s, r) => s + Math.max(0, (r.returnedAt || r.closedAt || now()) - r.openedAt), 0), open = rows.filter((r) => r.status === 'open').length; return html`<div class="mt-sum"><span><b>${fmtNum(rows.length)}</b> ${rows.length === 1 ? 'مرة' : 'مرات'} دخل الصيانة</span><span><b>${fmtDuration(days)}</b> إجمالي مدة الصيانة</span>${open ? html`<span class="tone-sky"><b>${fmtNum(open)}</b> قيد الصيانة الآن</span>` : ''}${rows[0] ? html`<span>آخر صيانة ${fmtDate(rows[0].openedAt)}</span>` : ''}</div>`; };
