      form.querySelector('[data-ibq]').addEventListener('input', (e) => { const q = e.target.value.trim().toLowerCase(); $$('[data-ibpane] .ib-cell', form).forEach((c) => { c.hidden = !!q && !String(c.dataset.q).toLowerCase().includes(q); }); });
