    facts: [['الإدارة', Data.nameOf('departments', l.departmentId, '—')], ['موعد الإرجاع', l.dueAt ? fmtDate(l.dueAt) : 'عهدة دائمة'], ['المسلِّم (الفني)', who(l.userId)]],
