  const chips = () => [...[...sel.groups].map((g) => ['g', g, (VAULT.group(g) || {}).name || 'مجموعة محذوفة', 'violet', 'users']), ...[...sel.roles].map((r) => ['r', r, NOTE_ROLE_ALL[r], 'teal', 'shield']), ...[...sel.users].map((id) => ['u', id, Data.userName(id), 'sky', 'user'])];
