MOVES.dept_adjust = { label: 'تصحيح عهدة', sign: 0 }; MOVE_TONE.dept_adjust = 'amber';
const InvLock = {
  KEY: 'inv:lock', cur: {},
  async state() { let v = {}; try { const r = await DB.get('meta', this.KEY); v = (r && r.value) || {}; } catch (_) { /* تجاهل */ } this.cur = v; return v; },
  isLocked() { return !!(this.cur && this.cur.del); },
  canToggle: () => !!Auth.user && (Auth.user.role === 'supervisor' || canUser(Auth.user, 'custody.lock')),
  async locked() { return !!(await this.state()).del; },
  async guard() { if (await this.locked()) throw new AppError('حذف الأجهزة مقفل. التعديل متاح، أما الحذف فيحتاج فتح القفل من «أقفال المخزن والعهد»'); },
  async set(on) {
    if (!this.canToggle()) throw new AppError('قفل الحذف وفتحه للمشرف ومن يملك صلاحية «أقفال المخزن والعهد»');
    await DB.put('meta', { key: this.KEY, value: { del: on ? 1 : 0, by: Auth.user.id, at: now() } });
    this.cur = { del: on ? 1 : 0, by: Auth.user.id, at: now() };
    await Data.log('update', 'inventory', '', on ? 'قفل حذف الأجهزة والأصناف والعهد' : 'فتح حذف الأجهزة والأصناف والعهد');
    const who = Data.list('users').filter((u) => u.active && u.id !== Auth.user.id && (canUser(u, 'inventory.manage') || canUser(u, 'custody.direct'))).map((u) => u.id);
    if (who.length) await Data.notify(who, { title: on ? 'قُفل حذف الأجهزة' : 'فُتح حذف الأجهزة', body: on ? 'لم يعد بالإمكان حذف الأصناف والأجهزة والعهد المسجلة. التعديل والإضافة متاحان حسب الصلاحيات.' : `فتحه ${Auth.user.name}`, link: '/inventory', kind: 'system' });
    Bus.emit('inventory', {});
  }
};
Custody.canToggle = () => !!Auth.user && (Auth.user.role === 'supervisor' || canUser(Auth.user, 'custody.lock'));
