/* ── استخدام الصنف: ما الذي يرتبط به قبل حذفه ── */
Data.inv.usage = async (id) => {
  const [stock, dept, units, assets, loans, maint, moves] = await Promise.all([DB.getAll('stock', 'itemId', KR(id)), DB.getAll('deptStock', 'itemId', KR(id)), DB.getAll('unitStock', 'itemId', KR(id)), Data.assets.byItem(id), DB.getAll('loans', 'itemId', KR(id)), Data.maint.byItem(id), DB.getAll('movements', 'item_at', KR([id, 0], [id, Infinity]))]);
  const sum = (a) => a.reduce((s, r) => s + (Number(r.qty) || 0), 0);
  return { stock, dept, units, assets, loans, maint, moves, inStore: sum(stock.filter((s) => s.qty > 0)), inDept: sum(dept.filter((d) => d.qty > 0)), activeLoans: loans.filter((l) => l.status === 'active').length, openMaint: maint.filter((m) => m.status === 'open').length };
};
/* حذف نهائي للصنف مع كل ما يتعلق به: الأرصدة والعهد والوحدات والإعارات والصيانة والحركات. السندات المطبوعة تبقى وثائق كما هي */
Data.inv.purgeItem = async (id) => {
  if (!canUser(Auth.user, 'inventory.manage')) throw new AppError('حذف الأصناف لمن يملك صلاحية إدارة الأصناف');
  await InvLock.guard();
  const it = await DB.get('items', id); if (!it) throw new AppError('الصنف غير موجود');
  const u = await Data.inv.usage(id);
  await DB.run(['items', 'stock', 'deptStock', 'unitStock', 'assets', 'loans', 'maintenance', 'movements'], async (T) => {
    for (const s of u.stock) await T.del('stock', [s.warehouseId, s.itemId]);
    for (const d of u.dept) await T.del('deptStock', [d.departmentId, d.itemId]);
    for (const x of u.units) await T.del('unitStock', [x.unitId, x.itemId]);
    for (const a of u.assets) await T.del('assets', a.id);
    for (const l of u.loans) await T.del('loans', l.id);
    for (const m of u.maint) await T.del('maintenance', m.id);
    for (const m of u.moves) await T.del('movements', m.id);
    await T.del('items', id);
  });
  await Data.log('delete', 'inventory', id, `حذف نهائي للصنف ${it.name}: ${fmtNum(u.inStore)} في المخازن، ${fmtNum(u.inDept)} بعهدة الإدارات، ${fmtNum(u.assets.length)} وحدة مسلسلة، ${fmtNum(u.moves.length)} حركة`);
  Bus.emit('inventory', { itemId: id });
  return u;
};
{
  const ri0 = Data.inv.removeItem;
  Data.inv.removeItem = async (id) => { if (await InvLock.locked()) { const u = await Data.inv.usage(id); if (!u.moves.length && !u.assets.length && !u.maint.length) throw new AppError('حذف الأجهزة مقفل. يمكنك أرشفة الصنف بدل حذفه'); } return ri0(id); };
  const rm0 = Data.inv.removeMistakes;
  Data.inv.removeMistakes = async (...a) => { await InvLock.guard(); return rm0(...a); };
}
Data.inv.archive = async (id) => {
  if (!canUser(Auth.user, 'inventory.manage')) throw new AppError('للمخولين فقط');
  const it = await DB.get('items', id); if (!it) return;
  await DB.put('items', { ...it, archived: 1, updatedAt: now() });
  await Data.log('delete', 'inventory', id, `أرشفة الصنف ${it.name}`); Bus.emit('inventory', { itemId: id });
};
Pages.itemDeleteFlow = async (id) => {
  const it = await DB.get('items', id); if (!it) return false;
  if (it.archived) { if (await UI.confirm(`استعادة «${it.name}» من الأرشيف ليظهر في المخزن مجدداً؟`, { ok: 'استعادة', icon: 'undo' })) { await Data.inv.restoreItem(id); UI.toast('استُعيد الصنف'); return 'restored'; } return false; }
  const [u, locked] = await Promise.all([Data.inv.usage(id), InvLock.locked()]);
  const busy = u.inStore || u.inDept || u.activeLoans || u.openMaint, history = u.moves.length || u.assets.length || u.maint.length;
  if (!busy && !history && !locked) {
    if (!(await UI.confirm(`حذف الصنف «${it.name}»؟ لا توجد عليه أرصدة أو حركات.`, { danger: true, ok: 'حذف' }))) return false;
    await Data.inv.removeItem(id); UI.toast('حُذف الصنف'); return 'deleted';
  }
  const facts = [[u.inStore, 'في المخازن', 'warehouse'], [u.inDept, 'بعهدة الإدارات', 'building'], [u.assets.length, 'وحدة مسلسلة', 'tag'], [u.loans.length, 'عهدة أفراد وإعارة', 'clipboard'], [u.maint.length, 'سجل صيانة', 'tools'], [u.moves.length, 'حركة في السجل', 'refresh']].filter(([n]) => n);
  const canArchive = !busy;
  const r = await UI.modal({
    title: `حذف «${it.name}»`, icon: 'trash', size: 'md',
    body: html`${facts.length ? html`<div class="purge-facts">${facts.map(([n, l, ic]) => html`<span>${UI.icon(ic)} <b>${fmtNum(n)}</b> ${l}</span>`)}</div>` : ''}
      ${locked ? html`<div class="banner tone-red mt">${UI.icon('lock')}<div class="grow"><b>حذف الأجهزة مقفل</b><div class="small">يمكن الأرشفة فقط (إخفاء الصنف مع بقاء سجله). لفتح الحذف: الإعدادات ← أقفال المخزن والعهد.</div></div></div>` : ''}
      <div class="purge-opts mt">
        <label class="purge-opt${canArchive ? '' : ' off'}"><input type="radio" name="how" value="archive"${canArchive ? raw(' checked') : raw(' disabled')}><span><b>${UI.icon('archive')} أرشفة</b><small>${canArchive ? 'يختفي من المخزن والقوائم، ويبقى سجله في التقارير، ويمكن استعادته.' : 'غير متاحة: عليه أرصدة أو عهد قائمة.'}</small></span></label>
        ${locked ? '' : html`<label class="purge-opt danger"><input type="radio" name="how" value="purge"${canArchive ? '' : raw(' checked')}><span><b>${UI.icon('trash')} حذف نهائي مع كل ما يتعلق به</b><small>يُحذف الصنف وأرصدته في المخازن وعهده لدى الإدارات والأقسام ووحداته المسلسلة وإعاراته وصيانته وحركاته من الخادم ومن كل الأجهزة. السندات المطبوعة سابقاً تبقى.</small></span></label>`}
      </div>
      ${locked ? '' : html`<label class="chk mt purge-ok"><input type="checkbox" name="sure"> أفهم أن الحذف النهائي لا يمكن التراجع عنه</label>`}`,
    onMount: (form) => {
      const btn = form.querySelector('.modal-foot .btn-danger'), sync = () => { const how = (form.querySelector('[name="how"]:checked') || {}).value; if (btn) btn.disabled = !how || (how === 'purge' && !form.querySelector('[name="sure"]').checked); };
      form.addEventListener('change', sync); sync();
    },
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'تنفيذ', kind: 'danger', icon: 'check', submit: true, handler: async (form) => {
      const how = (form.querySelector('[name="how"]:checked') || {}).value;
      if (how === 'archive') { await Data.inv.archive(id); return 'archived'; }
      if (how === 'purge') { if (!form.querySelector('[name="sure"]').checked) throw new AppError('أكّد الحذف النهائي'); await Data.inv.purgeItem(id); return 'purged'; }
      return null;
    } }]
  });
  if (r === 'archived') UI.toast('أُرشف الصنف، ويمكن استعادته');
  if (r === 'purged') UI.toast('حُذف الصنف نهائياً مع كل ما يتعلق به');
  return r;
};

/* ── الوحدات المسلسلة: تعديل وحذف من نافذة الجهاز ── */
Data.assets.purge = async (id) => {
  if (!Auth.can('inventory.manage') && !Auth.can('inventory.move') && !Auth.can('custody.direct')) throw new AppError('لا تملك صلاحية حذف الوحدات');
  await InvLock.guard();
  const a = await DB.get('assets', id); if (!a) return null;
  if (a.status === 'in_store' && a.warehouseId) return Data.inv.removeMistakes(a.itemId, a.warehouseId, [a.id], 1, 'حذف وحدة سُجلت بالخطأ');
  const at = now(), me = Auth.user.id;
  await DB.run(['assets', 'deptStock', 'unitStock', 'movements'], async (T) => {
    if (a.departmentId && ['issued', 'maintenance'].includes(a.status)) {
      const ds = await T.get('deptStock', [a.departmentId, a.itemId]);
      if (ds && ds.qty > 0) { ds.qty -= 1; ds.updatedAt = at; await T.put('deptStock', ds); }
      if (a.unitId) { const us = await T.get('unitStock', [a.unitId, a.itemId]); if (us && us.qty > 0) { us.qty -= 1; us.updatedAt = at; await T.put('unitStock', us); } }
      await T.put('movements', { id: uid('mv'), type: 'dept_adjust', itemId: a.itemId, warehouseId: '', qty: 1, delta: 0, ddelta: -1, balance: null, at, userId: me, note: `حذف وحدة سُجلت بالخطأ: ${a.serial}`, ref: '', party: Data.nameOf('departments', a.departmentId), departmentId: a.departmentId, fix: 1 });
    }
    await T.del('assets', a.id);
  });
  await Data.log('delete', 'assets', id, `حذف وحدة ${a.serial}`); Bus.emit('inventory', {}); return a;
};
Pages.assetActs = (a) => {
  const edit = Auth.can('inventory.move') || Auth.can('inventory.manage') || Auth.can('custody.direct');
  if (!edit) return '';
  return html`<button type="button" class="icon-btn" data-aedit="${a.id}" title="تعديل الرقم التسلسلي وبياناته">${UI.icon('edit')}</button>${InvLock.isLocked() ? '' : html`<button type="button" class="icon-btn danger" data-apurge="${a.id}" title="حذف الوحدة (سُجلت بالخطأ)">${UI.icon('trash')}</button>`}`;
};
