/* ── تصحيح عهد الإدارات والأقسام: تعديل الكمية أو الحذف من المستوى نفسه ── */
Data.custodyFix = {
  async ctx(departmentId, unitId, itemId) {
    const ds = (await DB.get('deptStock', [departmentId, itemId])) || { departmentId, itemId, qty: 0 };
    const rows = (await DB.getAll('unitStock', 'itemId', KR(itemId))).filter((r) => r.departmentId === departmentId && r.qty > 0);
    const assigned = rows.reduce((s, r) => s + r.qty, 0), us = unitId ? rows.find((r) => r.unitId === unitId) : null;
    return { ds, rows, assigned, here: unitId ? (us ? us.qty : 0) : Math.max(0, ds.qty - assigned) };
  },
  async set({ departmentId, unitId = '', itemId, qty, note = '' }) {
    if (!(await Custody.allowed())) throw new AppError('تعديل العهد المسجلة متاح أثناء فتح الإضافة المباشرة فقط');
    const n = Math.floor(Number(qty)); if (!(n >= 0)) throw new AppError('أدخل كمية صحيحة (صفر أو أكثر)');
    const c = await this.ctx(departmentId, unitId, itemId), delta = n - c.here;
    if (!delta) return 0;
    if (delta < 0) await InvLock.guard();
    const at = now(), me = Auth.user.id, item = await DB.get('items', itemId);
    await DB.run(['deptStock', 'unitStock', 'movements'], async (T) => {
      const ds = (await T.get('deptStock', [departmentId, itemId])) || { departmentId, itemId, qty: 0 };
      ds.qty = Math.max(0, (Number(ds.qty) || 0) + delta); ds.updatedAt = at; await T.put('deptStock', ds);
      if (unitId) { const us = (await T.get('unitStock', [unitId, itemId])) || { unitId, itemId, departmentId, qty: 0 }; us.qty = n; us.departmentId = departmentId; us.updatedAt = at; await T.put('unitStock', us); }
      await T.put('movements', { id: uid('mv'), type: 'dept_adjust', itemId, warehouseId: '', qty: Math.abs(delta), delta: 0, ddelta: delta, balance: null, at, userId: me, note: note || `تصحيح كمية العهدة إلى ${fmtNum(n)}`, ref: '', party: Data.nameOf('departments', departmentId), departmentId, unitId, fix: 1 });
    });
    await Data.log('move', 'inventory', itemId, `تصحيح عهدة ${item ? item.name : ''} لدى ${Data.nameOf('departments', departmentId)}: ${delta > 0 ? '+' : ''}${fmtNum(delta)}`);
    Bus.emit('inventory', { itemId }); return delta;
  },
  /* الحذف من المستوى: تصفير الكمية وحذف وحداته المسلسلة في المكان نفسه */
  async remove({ departmentId, unitId = '', itemId }) {
    await InvLock.guard();
    const c = await this.ctx(departmentId, unitId, itemId);
    const units = (await Data.assets.byItem(itemId)).filter((a) => a.departmentId === departmentId && a.status === 'issued' && (unitId ? a.unitId === unitId : !a.unitId)).slice(0, c.here);
    await this.set({ departmentId, unitId, itemId, qty: 0, note: 'حذف من العهدة' });
    for (const a of units) await DB.del('assets', a.id);
    return c.here;
  }
};
document.addEventListener('click', async (e) => {
  const fx = e.target.closest && e.target.closest('.ct [data-ctfix]'), dl = e.target.closest && e.target.closest('.ct [data-ctdel]'), ad = e.target.closest && e.target.closest('[data-ctadd]');
  if (!fx && !dl && !ad) return;
  e.preventDefault(); e.stopPropagation();
  try {
    if (ad) { const [dep, un] = ad.dataset.ctadd.split('|'); await Pages.directCustodyModal(dep, un || ''); return; }
    const b = fx || dl, [k, id] = b.dataset.lvl.split(':'), itemId = b.dataset.ctfix || b.dataset.ctdel;
    const units = k === 'u' ? await DB.getAll('deptUnits') : [], un = units.find((x) => x.id === id), departmentId = k === 'u' ? (un || {}).departmentId : id, unitId = k === 'u' ? id : '';
    const item = await DB.get('items', itemId), c = await Data.custodyFix.ctx(departmentId, unitId, itemId), place = unitId ? (un || {}).name : `${Data.nameOf('departments', departmentId)} (غير موزّع على الأقسام)`;
    if (dl) {
      if (!(await UI.confirm(`حذف «${item ? item.name : 'الصنف'}» من عهدة ${place}؟ الكمية هنا ${fmtNum(c.here)}، وتُحذف وحداته المسلسلة في هذا المكان.`, { danger: true, ok: 'حذف' }))) return;
      const n = await Data.custodyFix.remove({ departmentId, unitId, itemId }); UI.toast(`حُذف ${fmtNum(n)} من العهدة`); return;
    }
    const r = await UI.modal({ title: `تعديل الكمية — ${item ? item.name : ''}`, icon: 'edit', size: 'sm',
      body: html`<p class="muted" style="margin-top:0">${UI.icon('pin')} ${place}</p>${UI.fields([{ name: 'qty', label: `الكمية هنا (الحالية ${fmtNum(c.here)})`, type: 'number', min: 0, required: true }, { name: 'note', label: 'سبب التعديل', placeholder: 'مثال: خطأ في العد', wide: true }], { qty: c.here })}${InvLock.isLocked() ? html`<p class="hint">${UI.icon('lock')} حذف الأجهزة مقفل: يمكن الزيادة فقط.</p>` : ''}`,
      actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حفظ', kind: 'primary', icon: 'check', submit: true, handler: async (form) => { const v = UI.formValues(form); return { d: await Data.custodyFix.set({ departmentId, unitId, itemId, qty: v.qty, note: String(v.note || '').trim() }) }; } }] });
    if (r) UI.toast(r.d ? 'حُدّثت الكمية' : 'لم تتغير الكمية');
  } catch (ex) { UI.error(ex); }
}, true);


/* ══════════ صفحة «أقفال المخزن والعهد» في مركز الإعدادات ══════════ */
Pages.ccLocks = async (ctx) => {
  const draw = async () => {
    const [cs, ls] = await Promise.all([Custody.state(), InvLock.state()]);
    const can = Custody.canToggle(), holders = Data.list('users').filter((u) => u.active && u.role !== 'supervisor' && (u.extraPerms || []).includes('custody.lock'));
    const direct = Data.list('users').filter((u) => u.active && u.role !== 'supervisor' && canUser(u, 'custody.direct')).length;
    ctx.view.innerHTML = String(html`${UI.pageHead({ title: 'أقفال المخزن والعهد', sub: 'متى يُسمح بالإضافة المباشرة لعهد الإدارات، ومتى يُمنع حذف الأجهزة والأصناف', illu: 'key' })}
      <div class="grid g-2">
        ${UI.panel({ title: 'الإضافة المباشرة لعهد الإدارات', icon: cs.open ? 'key' : 'lock', body: html`<div class="lk-state tone-${cs.open ? 'teal' : 'slate'}">${UI.icon(cs.open ? 'key' : 'lock')}<div class="grow"><b>${cs.open ? 'مفتوحة' : 'مغلقة'}</b><small>${cs.open ? (cs.until ? `حتى ${fmtDateTime(cs.until)}` : 'حتى تُغلق') + (cs.by ? ` — فتحها ${Data.userName(cs.by)}` : '') : 'تتم العهدة عبر الصرف أو الإعارة أو الاستبدال أو النقل فقط'}</small></div></div>
          <p class="muted small">عند فتحها يستطيع من يملك صلاحية «إضافة عهدة للإدارات مباشرة» (${fmtNum(direct)} حساب، والمشرف) تسجيل الأجهزة الموجودة فعلاً لدى الإدارات وأقسامها ومكاتبها، وتصحيح كمياتها.</p>
          ${can ? html`<div class="row" style="gap:8px">${cs.open ? html`<button class="btn btn-danger" data-clock="close">${UI.icon('lock')} إغلاق الإضافة المباشرة</button>` : html`<button class="btn btn-primary" data-clock="open">${UI.icon('key')} فتح الإضافة المباشرة</button>`}<a class="btn btn-ghost" href="#/inventory/departments">${UI.icon('building')} عهدة الإدارات</a></div>` : ''}` })}
        ${UI.panel({ title: 'حذف الأجهزة والأصناف', icon: ls.del ? 'lock' : 'trash', body: html`<div class="lk-state tone-${ls.del ? 'red' : 'teal'}">${UI.icon(ls.del ? 'lock' : 'check')}<div class="grow"><b>${ls.del ? 'الحذف مقفل' : 'الحذف متاح لأصحاب الصلاحية'}</b><small>${ls.by ? `${ls.del ? 'قفله' : 'فتحه'} ${Data.userName(ls.by)} — ${fmtDateTime(ls.at)}` : 'لم يُقفل بعد'}</small></div></div>
          <p class="muted small">عند القفل لا يستطيع أحد (ولا المشرف حتى يفتحه) حذف: الأصناف، والوحدات المسلسلة، وعهد الإدارات والأقسام، ولا تنظيف بيانات المخزن. ويبقى التعديل والإضافة والأرشفة متاحة حسب الصلاحيات، ويرفض الخادم أي حذف حتى لو أُرسل من جهاز آخر.</p>
          ${can ? html`<button class="btn ${ls.del ? 'btn-soft' : 'btn-danger'}" data-invlock="${ls.del ? 'off' : 'on'}">${UI.icon(ls.del ? 'key' : 'lock')} ${ls.del ? 'فتح الحذف' : 'قفل الحذف'}</button>` : ''}` })}
      </div>
      ${UI.panel({ cls: 'mt', title: 'من يتحكم في الأقفال', icon: 'users', body: html`<p class="muted small" style="margin-top:0">المشرف دائماً، ومن تمنحه صلاحية «أقفال المخزن والعهد» من صفحة المستخدمين والصلاحيات.</p>${holders.length ? html`<div class="row" style="gap:6px;flex-wrap:wrap">${holders.map((u) => UI.chip('violet', u.name, 'user'))}</div>` : html`<p class="faint small">لم تُمنح الصلاحية لأحد غير المشرف.</p>`}${Auth.can('users.manage') ? html`<a class="btn btn-ghost btn-sm mt" href="#/settings?s=users">${UI.icon('users')} المستخدمون والصلاحيات</a>` : ''}` })}`);
  };
  UI.on(ctx.view, 'click', '[data-invlock]', async (e, b) => {
    const on = b.dataset.invlock === 'on';
    if (on && !(await UI.confirm('قفل حذف الأجهزة والأصناف والعهد للجميع؟ يبقى التعديل والإضافة متاحين.', { ok: 'قفل الحذف', danger: true }))) return;
    try { await InvLock.set(on); UI.toast(on ? 'قُفل الحذف' : 'فُتح الحذف'); draw(); } catch (ex) { UI.error(ex); }
  });
  ctx.onCleanup(Bus.on('inventory', debounce(() => { if (ctx.alive()) draw(); }, 300)));
  await draw();
};
