/* ══════════ تنظيف البيانات للبدء الرسمي ══════════
   «بداية رسمية» تحذف البيانات التشغيلية وتُبقي الهيكل والتصنيفات والحسابات، والحسابات تُختار واحداً واحداً بدل حذفها كلها */
const WIPE_OFFICIAL = WIPE_GROUPS.filter((g) => !g[4]).map((g) => g[0]);
Pages.wipeModal = async () => {
  if (!Auth.user || Auth.user.role !== 'supervisor') return UI.toast('هذه العملية للمشرف فقط', 'warn');
  const counts = {};
  for (const [k, , , stores] of WIPE_GROUPS) counts[k] = (await Promise.all(stores.map((s) => DB.count(s).catch(() => 0)))).reduce((a, b) => a + b, 0);
  const locked = await InvLock.locked();
  const users = (await DB.getAll('users')).filter((u) => u.id !== Auth.user.id && u.role !== 'supervisor' && u.role !== 'monitor' && !u.system)
    .sort((a, b) => String(a.role).localeCompare(String(b.role)) || String(a.name).localeCompare(String(b.name), 'ar'));
  const r = await UI.modal({
    title: 'تنظيف البيانات', icon: 'trash', size: 'lg',
    body: html`<div class="banner tone-red">${UI.icon('alert')}<div class="grow"><b>تُحذف البيانات المختارة نهائياً من الخادم ومن كل الأجهزة.</b><div class="small">خذ نسخة احتياطية أولاً. تبقى دائماً الإعدادات العامة وحسابك وحسابات المشرفين، ويُعاد ترقيم البلاغات والأصناف والسندات من 1.</div></div></div>
      <div class="wipe-presets mt"><button type="button" class="btn btn-primary btn-sm" data-wipeoff>${UI.icon('check')} بداية رسمية (موصى به)</button><button type="button" class="btn btn-soft btn-sm" data-wipeall>${UI.icon('trash')} حذف كل شيء</button><button type="button" class="btn btn-ghost btn-sm" data-wipenone>إلغاء التحديد</button></div>
      <p class="faint small">«بداية رسمية»: تُحذف البلاغات والاستفسارات والإشعارات والمخزن والعهد والسندات والأعمال والاستبيانات والإعلانات والصيانة الخارجية وسجل النشاط، ويبقى الهيكل التنظيمي والتصنيفات وكتالوج الطابعات وقاعدة المعرفة والنماذج والحسابات.</p>
      <div class="wipe-list mt">${WIPE_GROUPS.map(([k, label, icon, , off]) => { const lk = locked && k === 'inventory'; return html`<label class="wipe-row${off ? ' warn' : ''}${lk ? ' locked' : ''}"><input type="checkbox" name="g" value="${k}"${!off && !lk ? raw(' checked') : ''}${lk ? raw(' disabled') : ''}><span class="wipe-ic">${UI.icon(lk ? 'lock' : icon)}</span><span class="grow">${label}${lk ? html` <small class="faint">— حذف الأجهزة مقفل، افتحه أولاً من «أقفال المخزن والعهد»</small>` : ''}</span><b class="wipe-n">${fmtNum(counts[k])}</b></label>`; })}
        <div class="wipe-row warn wipe-urow"><span class="wipe-ic">${UI.icon('users')}</span><span class="grow">حسابات مستخدمين تختارها <small class="faint">— حسابك والمشرفون لا يُحذفون</small></span><b class="wipe-n" data-wun>0</b><button type="button" class="btn btn-sm btn-soft" data-wupick>${UI.icon('users')} اختيار الحسابات (${fmtNum(users.length)})</button></div>
        <div class="wipe-ulist" data-wulist hidden><div class="row" style="gap:6px;margin-bottom:6px;flex-wrap:wrap"><div class="search-box grow">${UI.icon('search')}<input type="search" data-wuq placeholder="ابحث بالاسم أو اسم المستخدم"></div><button type="button" class="btn btn-sm btn-ghost" data-wusel="all">تحديد الظاهر</button><button type="button" class="btn btn-sm btn-ghost" data-wusel="none">إلغاء</button>${users.some((u) => u.demo) ? html`<button type="button" class="btn btn-sm btn-ghost" data-wusel="demo">التجريبية فقط</button>` : ''}</div>
          <div class="wipe-users">${users.length ? users.map((u) => html`<label data-wuname="${normalizeAr(`${u.name} ${u.username}`)}"><input type="checkbox" name="uid" value="${u.id}"${u.demo ? raw(' checked') : ''}><span><b>${u.name}</b><small>${ROLES[u.role] || u.role} · ${u.username}${u.departmentId ? ` · ${Data.nameOf('departments', u.departmentId, '')}` : ''}${u.demo ? ' · تجريبي' : ''}</small></span></label>`) : html`<p class="faint small">لا توجد حسابات غير حسابك وحسابات المشرفين.</p>`}</div></div></div>
      <div class="field mt"><label>للتأكيد اكتب: <b class="wipe-phrase">${WIPE_PHRASE}</b></label><input name="confirm" autocomplete="off" placeholder="${WIPE_PHRASE}"></div>`,
    onMount: (form) => {
      const btn = form.querySelector('.modal-foot .btn-danger');
      const sync = () => { const n = $$('[name="uid"]:checked', form).length; $('[data-wun]', form).textContent = fmtNum(n); btn.disabled = form.querySelector('[name="confirm"]').value.trim() !== WIPE_PHRASE || !form.querySelector('[name="g"]:checked, [name="uid"]:checked'); };
      form.addEventListener('input', sync); form.addEventListener('change', sync); sync();
      const setG = (fn) => { $$('[name="g"]', form).forEach((c) => { if (!c.disabled) c.checked = fn(c.value); }); };
      UI.on(form, 'click', '[data-wipeoff]', () => { setG((k) => WIPE_OFFICIAL.includes(k)); $$('[name="uid"]', form).forEach((c) => { c.checked = false; }); sync(); });
      UI.on(form, 'click', '[data-wipeall]', () => { setG(() => true); $$('[name="uid"]', form).forEach((c) => { c.checked = true; }); $('[data-wulist]', form).hidden = false; sync(); });
      UI.on(form, 'click', '[data-wipenone]', () => { setG(() => false); $$('[name="uid"]', form).forEach((c) => { c.checked = false; }); sync(); });
      UI.on(form, 'click', '[data-wupick]', () => { const l = $('[data-wulist]', form); l.hidden = !l.hidden; if (!l.hidden) $('[data-wuq]', form).focus(); });
      UI.on(form, 'click', '[data-wusel]', (e, b) => { const m = b.dataset.wusel; $$('.wipe-users label', form).forEach((l) => { const c = $('input', l); if (m === 'all') { if (!l.hidden) c.checked = true; } else if (m === 'none') c.checked = false; else c.checked = !!users.find((u) => u.id === c.value && u.demo); }); sync(); });
      form.addEventListener('input', (e) => { if (!e.target.matches('[data-wuq]')) return; const q = normalizeAr(e.target.value.trim()); $$('.wipe-users label', form).forEach((l) => { l.hidden = !!q && !l.dataset.wuname.includes(q); }); });
    },
    actions: [{ label: 'إلغاء', kind: 'ghost' }, { label: 'حذف نهائياً', kind: 'danger', icon: 'trash', submit: true, handler: async (form) => {
      const groups = $$('[name="g"]:checked', form).map((x) => x.value), userIds = $$('[name="uid"]:checked', form).map((x) => x.value);
      if (form.querySelector('[name="confirm"]').value.trim() !== WIPE_PHRASE) throw new AppError('اكتب عبارة التأكيد كما هي');
      return Data.wipeTrial(groups, userIds);
    } }]
  });
  if (r) { UI.toast('حُذفت البيانات المختارة، وسيُعاد تحميل النظام', 'ok', 6000); setTimeout(() => location.reload(), 1600); }
  return r;
};
Data.wipeTrial = async (groups, userIds = []) => {
  if (groups.includes('inventory') && (await InvLock.locked())) throw new AppError('حذف الأجهزة مقفل: افتحه أولاً من «أقفال المخزن والعهد» ثم أعد المحاولة');
  const ids = Array.isArray(userIds) ? userIds : [];
  const stores = WIPE_GROUPS.filter(([k]) => groups.includes(k)).flatMap(([, , , s]) => s);
  let res = { counts: {} };
  if (Sync.on) {
    if (!Sync.token) throw new AppError('لا يوجد اتصال بالخادم، أعد المحاولة بعد عودة الاتصال');
    Sync.queue = Sync.queue.filter((op) => !stores.includes(op.store) && !(op.store === 'users' && ids.includes(String(op.id)))); Sync.saveQueue();
    res = await Sync.call('wipe', { body: { groups, userIds: ids, confirm: WIPE_PHRASE } });
  }
  const put = Sync.on ? Sync.raw.put : (s, v) => DB.put(s, v), del = Sync.on ? Sync.raw.del : (s, k) => DB.del(s, k);
  for (const s of stores) await DB.clear(s);
  for (const id of ids) { const u = await DB.get('users', id); if (u && u.id !== Auth.user.id && u.role !== 'supervisor' && u.role !== 'monitor' && !u.system) await del('users', u.id); }
  const seqs = { tickets: ['ticket'], inventory: ['item', 'loan', 'voucher'], extmaint: ['extmaint'], mtrack: ['mtrack'] };
  for (const g of groups) for (const n of seqs[g] || []) await put('meta', { key: `seq:${n}`, value: 0 });
  await Data.log('delete', 'system', '', `تنظيف البيانات: ${groups.map((g) => (WIPE_GROUPS.find((x) => x[0] === g) || [])[1]).join('، ')}${ids.length ? `، و${fmtNum(ids.length)} حساب` : ''}`);
  return res;
};
