  if (p.mode === 'bot') return `left:${e.x}mm;top:auto;bottom:${p.bottom}mm;width:${e.w}mm;${hh};z-index:${z}`;
  if (p.mode === 'str') return `left:${e.x}mm;top:${p.top}mm;bottom:${p.bottom}mm;width:${e.w}mm;z-index:${z}`;
