UI.tonePick = (name, cur) => html`<div class="snd-tones" role="radiogroup">${SND_STYLES.map(([k, l]) => html`<label><input type="radio" name="${name}" value="${k}"${cur === k ? raw(' checked') : ''}><span>${UI.icon('sound')}${l}</span></label>`)}</div>`;
/* قائمة نغمات منسدلة تُسمع النغمة عند اختيارها (حقل نغمة شاشة العرض في حسابها) */
document.addEventListener('change', (e) => { const el = e.target; if (el.matches && el.matches('select[data-tone-preview]') && SND_TIMBRE[el.value]) Snd.play('ticket', { style: el.value }); });
