    const t = String((n && n.title) || '');
    if (/^عاجل|متوقفة|عطل حرج/.test(t)) return 'urgent';
    if (/تأخر|تجاوز|منخفض|متأثر|^تنبيه/.test(t)) return 'warn';
    if (n && n.kind === 'chat') return 'message';
    if (n && (n.kind === 'ticket' || n.kind === 'work') && /بلاغ جديد|أُسند إليك/.test(t)) return 'ticket';
    if (/تعمل بشكل طبيعي/.test(t)) return 'success';
