    ctx.onCleanup(Bus.on('snd:state', () => TvSound.banner()));
    UI.on(ctx.view, 'click', '[data-act="sound"]', () => setTimeout(() => TvSound.banner(), 300));
    const tb = setTimeout(() => TvSound.banner(), 700);
