      const z = zone(ev.clientX, ev.clientY); st.dock = z; if (z === 'float') { st.pos = { x: Math.round(ev.clientX - dx), y: Math.round(ev.clientY - dy) }; CM.set('pos', st.pos); }
      CM.set('dock', st.dock); place();
