  UI.on(ctx.view, 'click', '[data-cmsave]', async (e, b) => { UI.busy(b, true); try { const r = await Pages.cmCommit(b.dataset.cmsave === 'print'); if (r) await draw(); } catch (ex) { UI.error(ex); } finally { if (b.isConnected) UI.busy(b, false); } });
