  const vOf = new Map(); vouchers.forEach((v) => (v.movementIds || []).forEach((id) => vOf.set(id, v)));
  const loanByNo = new Map(loans.map((l) => [l.number, l])), vByLoan = new Map(); vouchers.forEach((v) => (v.loanIds || []).forEach((id) => vByLoan.set(id, v)));
