    return html`${body}${more > 0 ? html`<div class="rc-more"><button type="button" class="btn btn-soft" data-rcmore>${UI.icon('chevron-down')} عرض ${fmtNum(Math.min(more, 300))} أخرى (المتبقي ${fmtNum(more)})</button></div>` : ''}`;
