    $$('[data-vper]', ctx.view).forEach((x) => { const on = x.dataset.vper === st.per; x.classList.toggle('on', on); x.setAttribute('aria-pressed', on ? 'true' : 'false'); });
    const c = $('.vc-custom', ctx.view); if (c) c.hidden = st.per !== 'custom';
