  nameOf(file) { return String(file.name || 'خط').replace(/\.(ttf|otf|woff2?|ttc)$/i, '').replace(/[_]+/g, ' ').replace(/\s*-\s*(regular|bold|normal|book|medium)$/i, '').trim(); },
