    if (!(await UI.confirm(`حذف الخط المرفوع «${x.family}» (${Number(x.weight) === 700 ? 'عريض' : 'عادي'})؟ القوالب التي تستخدمه تُطبع ببديله.`, { danger: true, ok: 'حذف' }))) return false;
